// Flight Optimizer Engine State
let flightOriginAirport = null;
let flightDestAirport = null;
let flightDestinationAirport = null;
let isFlightOptimizerActive = false;
let flightRouteLineGroup = null;

function filterByAirline(airlineName, btnEl = null) {
    const originAp = selectedAirport;
    if (!originAp) return;

    if (!activeRouteOrigin || activeRouteOrigin.icao !== originAp.icao) {
        selectedAirlines.clear();
        activeRouteOrigin = originAp;
    }

    if (selectedAirlines.has(airlineName)) {
        selectedAirlines.delete(airlineName);
        if (selectedAirlines.size === 0) {
            activeRouteOrigin = null;
            selectedAirline = null;
        } else {
            selectedAirline = Array.from(selectedAirlines)[selectedAirlines.size - 1];
        }
    } else {
        const destIcaos = (originAp.routes && originAp.routes[airlineName]) || [];
        if (destIcaos.length === 0 && selectedAirlines.size === 0) {
            showCustomModal({
                title: 'No Route Destinations',
                message: `No scheduled route destination data found for ${airlineName} from ${originAp.icao}.`,
                type: 'info',
                confirmText: 'OK'
            });
            return;
        }
        selectedAirlines.add(airlineName);
        selectedAirline = airlineName;
        activeRouteOrigin = originAp;
    }

    filterAirports();
    updateFilterUI();
    updateAirlinePillsUI(originAp);
}

let AIRLINE_TO_IATA = {};
let AIRLINE_TO_IATA_LOWER = {};

async function loadAirlineIataDatabase() {
    try {
        const resp = await fetch('airlines_iata.json');
        if (resp.ok) {
            AIRLINE_TO_IATA = await resp.json();
            AIRLINE_TO_IATA_LOWER = {};
            for (const [k, v] of Object.entries(AIRLINE_TO_IATA)) {
                if (k && v) AIRLINE_TO_IATA_LOWER[k.toLowerCase()] = v;
            }
        }
    } catch (e) {
        console.warn("Could not load airlines_iata.json:", e);
    }
}
loadAirlineIataDatabase();

function getAirlineIata(al) {
    if (!al) return null;
    const clean = al.trim();
    if (AIRLINE_TO_IATA[clean]) return AIRLINE_TO_IATA[clean];
    const lower = clean.toLowerCase();
    if (AIRLINE_TO_IATA_LOWER[lower]) return AIRLINE_TO_IATA_LOWER[lower];
    if (clean.length === 2 && clean === clean.toUpperCase()) return clean;
    return null;
}

function getAirlineLogoUrls(al) {
    if (!al) return { logoUrl: '', fallbackLogoUrl: '' };
    const clean = al.trim();
    const lower = clean.toLowerCase();

    // Specific overrides for airlines with reassigned/legacy IATA codes (e.g. Air Berlin vs Bonza)
    if (lower === 'air berlin' || lower === 'airberlin') {
        return {
            logoUrl: 'assets/logos/airberlin.svg',
            fallbackLogoUrl: 'assets/logos/airberlin.svg'
        };
    }

    const iata = getAirlineIata(al);
    if (!iata) return { logoUrl: '', fallbackLogoUrl: '' };

    return {
        logoUrl: `https://pics.avs.io/300/100/${iata}.png`,
        fallbackLogoUrl: `https://images.kiwi.com/airlines/128x128/${iata}.png`
    };
}

function updateAirlinePillsUI(ap) {
    if (!ap) return;
    const airlinesListEl = document.getElementById('drawer-airlines-list');
    if (!airlinesListEl) return;

    const btns = airlinesListEl.querySelectorAll('button[data-airline]');
    btns.forEach(btn => {
        const alName = btn.getAttribute('data-airline');
        if (!alName) return;

        const isActive = selectedAirlines.has(alName) && (activeRouteOrigin && activeRouteOrigin.icao === ap.icao);
        const img = btn.querySelector('img');

        if (img) {
            // Card with logo: clean white background, thick bottle green border when active
            if (isActive) {
                btn.className = 'group relative min-h-[50px] rounded-xl overflow-hidden transition-all cursor-pointer flex items-center justify-center p-1.5 text-center bg-white border-4 border-emerald-700 shadow-md shadow-emerald-950/30';
            } else {
                btn.className = 'group relative min-h-[50px] rounded-xl overflow-hidden transition-all cursor-pointer flex items-center justify-center p-1.5 text-center bg-white border-4 border-transparent hover:border-emerald-700/50';
            }
            img.className = 'w-full h-full object-contain object-center';
        } else {
            // Text-only fallback for airlines without logo
            if (isActive) {
                btn.className = 'group relative min-h-[50px] rounded-xl overflow-hidden transition-all cursor-pointer flex items-center justify-center p-1.5 text-center bg-emerald-800 text-white font-bold border-4 border-emerald-600 shadow-md shadow-emerald-950/30';
            } else {
                btn.className = 'group relative min-h-[50px] rounded-xl overflow-hidden transition-all cursor-pointer flex items-center justify-center p-1.5 text-center bg-slate-800 text-slate-300 font-medium border-4 border-transparent hover:border-emerald-700/50';
            }
        }
    });
}

function clearAirlineFilter() {
    selectedAirline = null;
    selectedAirlines.clear();
    activeRouteOrigin = null;
    filterAirports();
    updateFilterUI();
    if (selectedAirport) {
        showAirportDetails(selectedAirport);
    }
}

/* ================= FLIGHT OPTIMIZER (MODE VOL & FPS BOOST) ================= */

let isSuppressingHoverPopups = false;

function suppressHoverPopupsTemporarily() {
    isSuppressingHoverPopups = true;
    if (map) map.closePopup();
    setTimeout(() => {
        isSuppressingHoverPopups = false;
    }, 500);
}

function setFlightOrigin(ap) {
    if (!ap) {
        flightOriginAirport = null;
    } else {
        if (flightDestAirport && flightDestAirport.icao === ap.icao) {
            flightDestAirport = null;
        }
        flightOriginAirport = ap;
    }
    updateFlightOptimizerUI();
    drawFlightOptimizerRoute();
    suppressHoverPopupsTemporarily();
}

function setFlightDest(ap) {
    if (!ap) {
        flightDestAirport = null;
    } else {
        if (flightOriginAirport && flightOriginAirport.icao === ap.icao) {
            flightOriginAirport = null;
        }
        flightDestAirport = ap;
    }
    updateFlightOptimizerUI();
    drawFlightOptimizerRoute();
    suppressHoverPopupsTemporarily();
}

function setFlightOriginByIcao(icao) {
    const ap = getAirportByIcao(icao);
    if (ap) setFlightOrigin(ap);
}

function setFlightDestByIcao(icao) {
    const ap = getAirportByIcao(icao);
    if (ap) setFlightDest(ap);
}

function clearFlightOrigin() {
    flightOriginAirport = null;
    updateFlightOptimizerUI();
    drawFlightOptimizerRoute();
    suppressHoverPopupsTemporarily();
}

function clearFlightDest() {
    flightDestAirport = null;
    updateFlightOptimizerUI();
    drawFlightOptimizerRoute();
    suppressHoverPopupsTemporarily();
}

function clearFlightSelection() {
    flightOriginAirport = null;
    flightDestAirport = null;
    isFlightOptimizerActive = false;
    if (flightRouteLineGroup) {
        flightRouteLineGroup.clearLayers();
    }
    updateFlightOptimizerUI();
    filterAirports();
}

function updateFlightOptimizerUI() {
    const bar = document.getElementById('flight-optimizer-bar');
    if (bar) {
        bar.classList.add('hidden');
        bar.classList.remove('flex');
        bar.style.display = 'none';
    }
}

function drawFlightOptimizerRoute() {
    if (flightRouteLineGroup) {
        flightRouteLineGroup.clearLayers();
    } else {
        if (map) flightRouteLineGroup = L.layerGroup().addTo(map);
    }

    if (!flightOriginAirport || !flightDestAirport || !flightRouteLineGroup) return;

    const lat1 = flightOriginAirport.lat;
    const lon1 = flightOriginAirport.lon;
    const lat2 = flightDestAirport.lat;
    const lon2 = flightDestAirport.lon;

    if (!lat1 || !lon1 || !lat2 || !lon2) return;

    const arcPoints = createBezierArcPoints(lat1, lon1, lat2, lon2, 35);

    // Draw glowing flight route line (Emerald green gradient glow)
    const glowLine = L.polyline(arcPoints, {
        color: '#10b981', // Neon Emerald
        weight: 3.5,
        opacity: 0.9,
        smoothFactor: 1
    });

    glowLine.addTo(flightRouteLineGroup);
}

async function executeFlightOptimizer() {
    const keepIcaos = [];
    if (flightOriginAirport) keepIcaos.push(flightOriginAirport.icao);
    if (flightDestAirport) keepIcaos.push(flightDestAirport.icao);

    if (keepIcaos.length === 0) {
        showCustomModal("Select Departure & Arrival", "Please select at least one Departure or Arrival airport before running Flight Optimizer.", "info");
        return;
    }

    showCustomModal({
        title: '',
        message: `<div class="flex flex-col items-center justify-center py-2 text-center">` +
                 `  <p class="text-sm text-slate-100 font-bold mb-1">Optimizing Flight (${routeText})</p>` +
                 `  <p class="text-xs text-slate-400">Disabling non-flight sceneries to maximize MSFS performance...</p>` +
                 `  <p class="mt-3.5 text-sm font-bold text-slate-100">Please wait<span class="loading-dots ml-1"><span>.</span><span>.</span><span>.</span></span></p>` +
                 `</div>`,
        type: 'loading'
    });

    try {
        if (window.pywebview) {
            const resRaw = await window.pywebview.api.optimize_flight_mode(JSON.stringify(keepIcaos));
            const res = JSON.parse(resRaw);
            if (res.status === 'ok') {
                isFlightOptimizerActive = true;
                if (res.airports && res.airports.length > 0) {
                    allAirportsData = res.airports;
                }
                updateStats(allAirportsData);
                updateFlightOptimizerUI();
                filterAirports();
                showCustomModal(
                    "Flight Optimizer Active",
                    `Kept ${keepIcaos.join(' & ')} active.\nDisabled ${res.disabled_count} other sceneries for maximum FPS during your flight!`,
                    "success"
                );
            } else {
                showCustomModal("Optimization Error", res.message || "Failed to optimize sceneries.", "error");
            }
        }
    } catch (err) {
        console.error("Failed to execute flight optimizer:", err);
        showCustomModal("Error", "Flight Optimizer execution failed: " + err, "error");
    }
}

function applyRestoredAirportsData(airports) {
    if (airports && airports.length > 0) {
        allAirportsData = airports;
        allAirportsData.forEach(ap => {
            if (userRatingsMap && userRatingsMap[ap.icao] !== undefined) {
                ap.rating = userRatingsMap[ap.icao];
            } else {
                ap.rating = ap.rating || 0;
            }
            if (typeof buildAirportSearchKey === 'function') {
                ap._searchKey = buildAirportSearchKey(ap);
            }
        });
        rebuildAirportsByIcaoIndex();
        updateStats(allAirportsData);
        updateFilterUI();
    }
}

async function executeRestoreAllSceneries() {
    return restoreFlightCorridorSceneries();
}

function executeFlightOptimizerQuickPrompt() {
    if (selectedAirport) {
        if (!flightOriginAirport) {
            setFlightOrigin(selectedAirport);
            showCustomModal("Departure Airport Set 🛫", `Set ${selectedAirport.icao} as Departure airport. Now select an Arrival airport and click 'Disable Rest (+FPS)'!`, "info");
        } else if (!flightDestAirport && selectedAirport.icao !== flightOriginAirport.icao) {
            setFlightDest(selectedAirport);
            showCustomModal("Arrival Airport Set 🛬", `Set ${selectedAirport.icao} as Arrival airport. Click 'Disable Rest (+FPS)' on the bottom bar to launch Flight Mode!`, "info");
        } else {
            updateFlightOptimizerUI();
        }
    } else {
        updateFlightOptimizerUI();
        showCustomModal("Flight Optimizer 🚀", "Select a Departure airport and an Arrival airport from the map/drawer, then click 'Disable Rest (+FPS)' to disable all other sceneries during your flight!", "info");
    }
}

// Initialize App
let isAppLoading = false;
let isAppInitialized = false;

async function ensureAppLoaded() {
    if (isAppLoading || isAppInitialized || (allAirportsData && allAirportsData.length > 0)) return;
    isAppLoading = true;

    for (let i = 0; i < 60; i++) {
        if (window.pywebview && window.pywebview.api && window.pywebview.api.get_airports) {
            isAppInitialized = true;
            await loadInitialAppData();
            isAppLoading = false;
            return;
        }
        await new Promise(r => setTimeout(r, 100));
    }

    if (!isAppInitialized && (!allAirportsData || allAirportsData.length === 0)) {
        isAppInitialized = true;
        await loadInitialAppData();
    }
    isAppLoading = false;
}

document.addEventListener('DOMContentLoaded', () => {
    try {
        localStorage.removeItem('sceneryx_my_rig_pinned');
        sessionStorage.removeItem('sceneryx_my_rig_pinned');
    } catch (e) {}
    if (typeof isRigWindowSessionPinned !== 'undefined') isRigWindowSessionPinned = false;
    if (window.windowManager) window.windowManager.init();
    initMap();
    initSidebarResize();
    initDrawerResize();
    initDrawerAccordions();
    initLeftFilterAccordions();
    renderStarRatingWidget(0);
    renderFilterStarWidget(0);
    ensureAppLoaded();
});

window.addEventListener('pywebviewready', async () => {
    await ensureAppLoaded();
});

let isMapDragging = false;

/* ================= MAP PANIC RESET (UNIVERSAL DOUBLE-CLICK RESET) ================= */
function triggerMapPanicReset() {
    if (countryClickTimeout) {
        clearTimeout(countryClickTimeout);
        countryClickTimeout = null;
    }

    // 1. Close overlay modals & suites
    if (typeof closeSettingsModal === 'function') closeSettingsModal();
    if (typeof closeExportModal === 'function') closeExportModal();
    if (typeof closeRescanModal === 'function') closeRescanModal();
    if (typeof exitFlightOptimizerMode === 'function') {
        exitFlightOptimizerMode();
    } else {
        const optModal = document.getElementById('flight-optimizer-modal');
        if (optModal) {
            optModal.classList.add('hidden');
            optModal.classList.remove('flex');
        }
    }

    // 2. Exit Flight Planning mode if active
    if (typeof isFlightPlanningMode !== 'undefined' && isFlightPlanningMode && typeof exitFlightPlanningMode === 'function') {
        exitFlightPlanningMode();
    }

    // 3. Clear temporary route preview & active selections
    if (typeof flightCorridorArrivalAirport !== 'undefined' && flightCorridorArrivalAirport) {
        flightCorridorArrivalAirport = null;
        if (typeof activeRouteLinesGroup !== 'undefined' && activeRouteLinesGroup) activeRouteLinesGroup.clearLayers();
    }
    selectedAirport = null;
    currentRadialAirport = null;
    currentRadialMarker = null;

    if (typeof closeDrawerWithoutCameraChange === 'function') {
        closeDrawerWithoutCameraChange();
    }

    // 4. Clear search, reset country mode & restore default filters
    if (typeof clearSearch === 'function') {
        clearSearch(false);
    }

    // 5. Ensure all radial wheels, route badges and inspection modals are closed
    if (typeof clearRouteAirportBadges === 'function') {
        clearRouteAirportBadges();
    }
    if (typeof closeAirportRadialMenu === 'function') {
        closeAirportRadialMenu();
    }
    if (typeof closeClassicAirportView === 'function') {
        closeClassicAirportView();
    }
    if (typeof closeFilterRadialMenu === 'function') {
        closeFilterRadialMenu();
    }
    if (typeof closeRadialDetailsModal === 'function') {
        closeRadialDetailsModal();
    }
    if (typeof closeRadialAirlinesModal === 'function') {
        closeRadialAirlinesModal();
    }

    // 6. Reset camera smoothly to configured startup region
    if (typeof resetCameraToStartupRegion === 'function') {
        resetCameraToStartupRegion();
    } else if (typeof resetCameraToDefaultView === 'function') {
        resetCameraToDefaultView();
    }

    // 7. Feedback toast
    if (typeof showToast === 'function') {
        showToast(t('map.panic_reset', 'Reset to default view & state'), 'info', 2200);
    }
}

function initMap() {
    map = L.map('map', {
        center: [20.0, 0.0], // Global world view (Screenshot 3)
        zoom: 2.5,
        minZoom: 2,
        zoomControl: false,
        worldCopyJump: true,
        preferCanvas: true,
        doubleClickZoom: false,
        wheelPxPerZoomLevel: 120, // Smooth mouse wheel zooming
        wheelDebounceTime: 60,    // Debounce rapid wheel events to prevent animation queue lag
        zoomAnimation: true,
        fadeAnimation: true,
        markerZoomAnimation: true,
        renderer: L.canvas({ padding: 0.5 })
    });

    L.control.zoom({ position: 'topright' }).addTo(map);
    window.leafletMap = map;
    window.map = map;

    L.tileLayer('https://server.arcgisonline.com/ArcGIS/rest/services/Canvas/World_Dark_Gray_Base/MapServer/tile/{z}/{y}/{x}', {
        attribution: 'Tiles &copy; Esri &mdash; Esri, DeLorme, NAVTEQ',
        maxZoom: 16,
        updateWhenIdle: true,     // DO NOT fetch/decode tiles during pan gestures (maintains 60+ fps panning!)
        updateWhenZooming: false,  // DO NOT fetch intermediate tiles during zoom animations
        keepBuffer: 8,             // Keep 8 tiles outside viewport in memory (no re-fetching on small pans)
        crossOrigin: true
    }).addTo(map);

    // Dedicated map pane for operating airline route lines (z-index 550: above country polygons, below markers)
    if (map && !map.getPane('routeLinesPane')) {
        const rPane = map.createPane('routeLinesPane');
        rPane.style.zIndex = '550';
        rPane.style.pointerEvents = 'none';
    }

    markerClusterGroup = L.markerClusterGroup({
        chunkedLoading: true,
        chunkInterval: 120,
        chunkDelay: 15,
        maxClusterRadius: function (zoom) {
            if (zoom <= 3) return 50;
            if (zoom <= 5) return 40;
            return 30;
        },
        disableClusteringAtZoom: 8, // Keep clusters at regional level to avoid rendering hundreds of unclustered DOM nodes simultaneously
        spiderfyOnMaxZoom: true,
        showCoverageOnHover: false,
        zoomToBoundsOnClick: true,
        animate: true,
        animateAddingMarkers: false
    });

    map.addLayer(markerClusterGroup);

    // Auto-refresh airline route lines on moveend/zoomend to guarantee unbroken display
    map.on('moveend zoomend', () => {
        if (selectedAirlines.size > 0 && activeRouteOrigin) {
            renderRouteLines(currentlyFilteredAirports);
        }
    });

    // Hierarchical progressive disclosure of airport labels by zoom (and dynamic route badge scaling)
    map.on('zoom zoomend zoomanim viewreset move moveend', (e) => {
        const targetZoom = (e && typeof e.zoom === 'number') ? e.zoom : undefined;
        if (typeof updateRouteAirportBadgesZoomScale === 'function') {
            updateRouteAirportBadgesZoomScale(targetZoom);
        }
    });
    map.on('zoomend', () => {
        updateMapZoomTier();
    });
    map.on('moveend', () => {
        if (typeof syncRouteBadgesWrapping === 'function') {
            syncRouteBadgesWrapping();
        }
    });
    updateMapZoomTier();

    // Map drag tracking to distinguish panning from clean left-clicks
    map.on('dragstart movestart', () => {
        isMapDragging = true;
    });
    map.on('dragend moveend', () => {
        setTimeout(() => {
            isMapDragging = false;
        }, 100);
    });

    // Single click on neutral map area: closes radial menu & drawer WITHOUT changing camera (ignored on drag/pan)
    map.on('click', () => {
        if (isMapDragging) return;
        if (isFilterRadialOpen) {
            closeFilterRadialMenu();
        }

        // When any radial modal or extension is open (Airport Details, Operating Airlines, Sceneries),
        // clicking outside on the map should NOT close the radial menu nor the window!
        // It stays open so the user can inspect the map and jump between airports.
        const sceneriesExt = document.getElementById('radial-sceneries-extension');
        const isSceneriesOpen = sceneriesExt && !sceneriesExt.classList.contains('hidden');
        if (isDetailsModalOpen() || isAirlinesModalOpen() || isSceneriesOpen) {
            return;
        }

        // Classic Mode Navigation: Deselect airport on background map click
        if (isClassicNavMode()) {
            if (typeof closeClassicAirportView === 'function') {
                closeClassicAirportView();
            }
        }

        // Strict Flight Planning Mode Protection:
        if (isFlightPlanningMode) {
            closeAirportRadialMenu();
            return;
        }

        closeAirportRadialMenu();
        if (countryClickTimeout) {
            clearTimeout(countryClickTimeout);
            countryClickTimeout = null;
        }
        if (activeDrawerMode !== 'MAP' || selectedAirport || selectedCountryCode) {
            closeDrawerWithoutCameraChange();
        }
        selectedAirport = null;
        if (flightCorridorArrivalAirport) {
            flightCorridorArrivalAirport = null;
            if (activeRouteLinesGroup) activeRouteLinesGroup.clearLayers();
            filterAirports();
        }
    });

    // Right-Click event on map: opens the floating Contextual Filter Radial Menu (Radial mode only)
    map.on('contextmenu', (e) => {
        if (e.originalEvent) {
            e.originalEvent.preventDefault();
            e.originalEvent.stopPropagation();
        }
        if (isClassicNavMode()) return;
        openFilterRadialMenu(e.originalEvent.clientX, e.originalEvent.clientY);
    });

    // Prevent clicks inside radial menu, sceneries extension, toolbar and modals from bubbling to Leaflet map
    const radialMenuEl = document.getElementById('airport-radial-menu');
    if (radialMenuEl) {
        L.DomEvent.disableClickPropagation(radialMenuEl);
        L.DomEvent.disableScrollPropagation(radialMenuEl);
    }
    const filterRadialMenuEl = document.getElementById('filter-radial-menu');
    if (filterRadialMenuEl) {
        L.DomEvent.disableClickPropagation(filterRadialMenuEl);
        L.DomEvent.disableScrollPropagation(filterRadialMenuEl);
        initDraggableFilterRadial();
    }
    const radialExtEl = document.getElementById('radial-sceneries-extension');
    if (radialExtEl) {
        L.DomEvent.disableClickPropagation(radialExtEl);
        L.DomEvent.disableScrollPropagation(radialExtEl);
    }
    const bottomToolbarEl = document.getElementById('bottom-map-toolbar');
    if (bottomToolbarEl) {
        L.DomEvent.disableClickPropagation(bottomToolbarEl);
        L.DomEvent.disableScrollPropagation(bottomToolbarEl);
    }
    const settingsModalEl = document.getElementById('settings-modal');
    if (settingsModalEl) {
        L.DomEvent.disableClickPropagation(settingsModalEl);
        L.DomEvent.disableScrollPropagation(settingsModalEl);
    }

    // High-performance RAF-throttled radial menu updates during pan/zoom
    let radialMenuMoveRaf = null;
    function onMapMoveUpdateRadial() {
        if (!currentRadialAirport && !isAirlinesModalOpen() && !isDetailsModalOpen() && !isSceneriesExtensionOpen() && !isFlightOptimizerModalOpen()) return;
        if (!radialMenuMoveRaf) {
            radialMenuMoveRaf = requestAnimationFrame(() => {
                radialMenuMoveRaf = null;
                updateRadialMenuPosition(false);
                if (typeof isFlightOptimizerModalOpen === 'function' && isFlightOptimizerModalOpen() && !hasUserDraggedOptimizerModal) {
                    positionFlightOptimizerModal();
                }
            });
        }
    }
    map.on('move', onMapMoveUpdateRadial);
    map.on('zoom viewreset moveend', () => {
        updateRadialMenuPosition(false);
        if (typeof isFlightOptimizerModalOpen === 'function' && isFlightOptimizerModalOpen() && !hasUserDraggedOptimizerModal) {
            positionFlightOptimizerModal();
        }
    });
    map.on('zoomend', updateCountryInteractivityState);
    window.addEventListener('resize', () => {
        updateRadialMenuPosition(false);
        if (typeof isFlightOptimizerModalOpen === 'function' && isFlightOptimizerModalOpen() && !hasUserDraggedOptimizerModal) {
            positionFlightOptimizerModal();
        }
    });

    // Double-click on neutral map area: PANIC RESET (aborts all actions & returns to default startup state)
    map.on('dblclick', (e) => {
        if (e && e.originalEvent) {
            L.DomEvent.stopPropagation(e.originalEvent);
        }
        triggerMapPanicReset();
    });

    loadCountryOverlays();
}

let countryGeoJsonLayer = null;
let selectedCountryCode = null;
let selectedCountryPolygonLayer = null;
let countryClickTimeout = null;
const MAX_COUNTRY_INTERACTION_ZOOM = 6.5;
let lastCountriesInactiveState = null;

function updateCountryInteractivityState() {
    const mapEl = document.getElementById('map');
    if (!mapEl || !map) return;
    const isZoomedIn = (typeof map.getZoom === 'function') && map.getZoom() > MAX_COUNTRY_INTERACTION_ZOOM;
    if (lastCountriesInactiveState === isZoomedIn) return;
    lastCountriesInactiveState = isZoomedIn;

    if (isZoomedIn) {
        mapEl.classList.add('countries-inactive');
        if (countryGeoJsonLayer) {
            countryGeoJsonLayer.eachLayer(layer => {
                const iso = getFeatureIso(layer.feature);
                const isSelected = (selectedCountryCode && iso && selectedCountryCode === iso);
                if (!isSelected) {
                    countryGeoJsonLayer.resetStyle(layer);
                }
            });
        }
    } else {
        mapEl.classList.remove('countries-inactive');
    }
}

const STANDARD_DRAWER_WIDTH = 460;

function ensureStandardDrawerWidth() {
    const drawer = document.getElementById('detail-drawer');
    if (!drawer) return;
    drawer.style.width = `${STANDARD_DRAWER_WIDTH}px`;
    try {
        localStorage.setItem('sceneryx_drawer_width', STANDARD_DRAWER_WIDTH);
    } catch(e) {}
}

function setDrawerSlidePosition(mode) {
    const track = document.getElementById('drawer-sliding-track');
    if (!track) return;
    ensureStandardDrawerWidth();
    if (mode === 'COUNTRY') {
        track.style.transform = 'translateX(-50%)';
    } else {
        track.style.transform = 'translateX(0%)';
    }
}

function resetCameraToStartupRegion() {
    if (!map) return;
    map.stop();
    const PAN_DURATION = (currentSettings && currentSettings.camera_pan_duration !== undefined)
        ? parseFloat(currentSettings.camera_pan_duration)
        : 1.1;
    const regKey = currentSettings && currentSettings.camera_startup_region;
    if (regKey && regKey !== 'world' && regKey !== 'default' && REGION_VIEWPORTS[regKey]) {
        const vp = REGION_VIEWPORTS[regKey];
        map.flyTo(vp.center, vp.zoom, { animate: true, duration: PAN_DURATION });
        return;
    }
    // Default global World view
    map.flyTo([25.0, 10.0], 3.0, { animate: true, duration: PAN_DURATION });
}

function resetCameraToDefaultView() {
    if (!map) return;
    map.stop();
    const PAN_DURATION = (currentSettings && currentSettings.camera_pan_duration !== undefined)
        ? parseFloat(currentSettings.camera_pan_duration)
        : 1.1;
    // Priority 1: Active filter region in sidebar (user's immediate working focus)
    if (selectedRegion && REGION_VIEWPORTS[selectedRegion]) {
        const vp = REGION_VIEWPORTS[selectedRegion];
        map.flyTo(vp.center, vp.zoom, { animate: true, duration: PAN_DURATION });
        return;
    }
    // Priority 2 & 3: Startup camera region configured in user Settings or World view
    resetCameraToStartupRegion();
}

function closeDrawerWithoutCameraChange() {
    if (isFlightPlanningMode) return;
    exitCountryMode(false);
}

function restoreMapToNeutralState(flyCamera = false) {
    if (isFlightPlanningMode) return;
    exitCountryMode(flyCamera);
}

function getFeatureIso(feature) {
    if (!feature || !feature.properties) return '';
    const p = feature.properties;
    let iso = p.ISO_A2_EH;
    if (!iso || iso === '-99') {
        iso = p.ISO_A2;
    }
    if (!iso || iso === '-99') {
        iso = p.ISO_A3 || p.ADM0_A3 || p.SU_A3 || '';
    }
    return (iso || '').toString().toUpperCase().trim();
}

async function loadCountryOverlays() {
    try {
        const resp = await fetch('countries.geojson');
        if (!resp.ok) return;
        const geoData = await resp.json();

        countryGeoJsonLayer = L.geoJSON(geoData, {
            style: feature => {
                const iso = getFeatureIso(feature);
                const isSelected = (selectedCountryCode && iso && selectedCountryCode === iso);
                return {
                    fillColor: isSelected ? '#a855f7' : '#06b6d4',
                    fillOpacity: isSelected ? 0.22 : 0.0,
                    color: isSelected ? '#a855f7' : '#475569',
                    weight: isSelected ? 2 : 0.5,
                    opacity: isSelected ? 0.9 : 0.3
                };
            },
            onEachFeature: (feature, layer) => {
                const props = feature.properties || {};
                const cName = props.NAME || props.ADMIN || props.NAME_LONG || 'Country';
                const iso = getFeatureIso(feature);

                layer.on({
                    mouseover: (e) => {
                        if (isMapDragging) return;
                        // Only active at country/regional zoom level
                        if (map && typeof map.getZoom === 'function' && map.getZoom() > MAX_COUNTRY_INTERACTION_ZOOM) return;
                        // Do not show hover highlight on countries if radial menu is open or an airport is active
                        if (currentRadialAirport || selectedAirport) return;
                        const l = e.target;
                        if (!selectedCountryCode || selectedCountryCode !== iso) {
                            l.setStyle({
                                fillColor: '#06b6d4',
                                fillOpacity: 0.16,
                                color: '#06b6d4',
                                weight: 1.5,
                                opacity: 0.8
                            });
                        }
                    },
                    mouseout: (e) => {
                        if (countryGeoJsonLayer) {
                            countryGeoJsonLayer.resetStyle(e.target);
                        }
                    },
                    click: (e) => {
                        L.DomEvent.stopPropagation(e);
                        if (isMapDragging) return;

                        // When any radial sub-mode (Details, Airlines, Sceneries) is open,
                        // clicking on the map/country should NEVER close the radial menu nor the window!
                        if (isDetailsModalOpen() || isAirlinesModalOpen() || isSceneriesExtensionOpen()) {
                            return;
                        }

                        // When zoomed in, country clicks are completely disabled
                        if (map && typeof map.getZoom === 'function' && map.getZoom() > MAX_COUNTRY_INTERACTION_ZOOM) {
                            if (currentRadialAirport || selectedAirport || activeDrawerMode !== 'MAP') {
                                closeAirportRadialMenu();
                                selectedAirport = null;
                                if (activeDrawerMode !== 'MAP') {
                                    closeDrawerWithoutCameraChange();
                                }
                            }
                            return;
                        }
                        // Priority Guard: If radial menu is open or an airport is currently selected, clicking anywhere on a country simply closes it and blocks country mode!
                        if (currentRadialAirport || selectedAirport || activeDrawerMode === 'AIRPORT') {
                            closeAirportRadialMenu();
                            selectedAirport = null;
                            if (activeDrawerMode !== 'MAP') {
                                closeDrawerWithoutCameraChange();
                            }
                            return;
                        }
                        if (isFilterRadialOpen) {
                            closeFilterRadialMenu();
                            return;
                        }
                        // If drawer is closed, debounce single click to allow double click detection
                        if (countryClickTimeout) {
                            clearTimeout(countryClickTimeout);
                            countryClickTimeout = null;
                        }
                        countryClickTimeout = setTimeout(() => {
                            countryClickTimeout = null;
                            toggleCountrySelection(iso, cName, layer);
                        }, 220);
                    },
                    contextmenu: (e) => {
                        if (e.originalEvent) {
                            e.originalEvent.preventDefault();
                            e.originalEvent.stopPropagation();
                        }
                        if (isClassicNavMode()) return;
                        openFilterRadialMenu(e.originalEvent.clientX, e.originalEvent.clientY);
                    },
                    dblclick: (e) => {
                        L.DomEvent.stopPropagation(e);
                        triggerMapPanicReset();
                    }
                });
            }
        }).addTo(map);
        updateCountryInteractivityState();
    } catch (err) {
        console.error("Failed to load country overlay GeoJSON:", err);
    }
}

function openCountryDrawer(iso, countryName) {
    if (!iso || iso === '-99') return;

    activeDrawerMode = 'COUNTRY';
    selectedAirport = null;

    updateCountryFilterButtonsUI();

    // Auto-hide Left Sidebar to maximize map viewport
    const sb = document.getElementById('sidebar-panel');
    const sbHandle = document.getElementById('sidebar-resize-handle');
    if (sb) {
        sb.style.marginLeft = `-${sb.offsetWidth || 360}px`;
        sb.classList.add('opacity-0', 'pointer-events-none');
    }
    if (sbHandle) sbHandle.classList.add('hidden');

    // 1. Find all airports belonging to this country
    const isoUpper = iso.toUpperCase().trim();
    const countryAirports = allAirportsData.filter(ap => {
        const apIso = ((ap.country || ap.iso_country || '').toString()).toUpperCase().trim();
        return apIso === isoUpper;
    });

    if (countryAirports.length === 0) {
        exitCountryMode();
        return;
    }

    // 2. Set Header Data with Full English Country Name & High-Res Country Flag
    const resolvedName = (typeof getLocalizedCountryName === 'function') ? getLocalizedCountryName(isoUpper, countryName) : (ISO_TO_COUNTRY_NAME[isoUpper] || countryName || isoUpper);
    const flagImgEl = document.getElementById('country-drawer-flag-img');
    const flagBgEl = document.getElementById('country-hero-flag-bg');
    const flagUrl = `https://flagcdn.com/w160/${isoUpper.toLowerCase()}.png`;
    const flagBgUrl = `https://flagcdn.com/w640/${isoUpper.toLowerCase()}.png`;

    if (flagImgEl) {
        flagImgEl.src = flagUrl;
        flagImgEl.alt = resolvedName;
        flagImgEl.style.display = 'block';
        flagImgEl.onerror = () => { flagImgEl.style.display = 'none'; };
    }
    if (flagBgEl) {
        flagBgEl.src = flagBgUrl;
        flagBgEl.alt = '';
        flagBgEl.style.display = 'block';
        flagBgEl.onerror = () => { flagBgEl.style.display = 'none'; };
    }

    const nameEl = document.getElementById('country-drawer-name');
    if (nameEl) nameEl.innerText = resolvedName;

    const totalEl = document.getElementById('country-drawer-total-airports');
    if (totalEl) totalEl.innerText = countryAirports.length.toLocaleString();

    // 3. Compute Breakdown Statistics
    let countPayware = 0;
    let countFreeware = 0;
    let countAsobo = 0;
    let countDefault = 0;

    let countInt = 0;
    let countReg = 0;
    let countGa = 0;
    let countHw = 0;

    let totalSpentEur = 0;
    const processedBundles = new Set();

    const customSceneryAirports = [];

    countryAirports.forEach(ap => {
        const hasCustom = hasCustomAddonSources(ap);
        const pt = getAirportPricingType(ap);

        if (hasCustom) {
            customSceneryAirports.push(ap);
            if (pt === 'Payware') {
                countPayware++;
                // Compute spent price in EUR / local currency
                if (ap.is_bundle || ap.bundle_id) {
                    const bKey = ap.bundle_id || ap.package_name;
                    if (!processedBundles.has(bKey)) {
                        processedBundles.add(bKey);
                        totalSpentEur += (ap.bundle_total_price || 29.90);
                    }
                } else {
                    totalSpentEur += (ap.price_eur || 0);
                }
            } else if (pt === 'Asobo') {
                countAsobo++;
            } else {
                countFreeware++;
            }
        } else {
            countDefault++;
        }

        // Airport Type
        const typeStr = (ap.english_type || ap.type || '').toLowerCase();
        if (typeStr.includes('international')) {
            countInt++;
        } else if (typeStr.includes('regional')) {
            countReg++;
        } else if (typeStr.includes('general') || typeStr.includes('ga')) {
            countGa++;
        } else if (typeStr.includes('heli') || typeStr.includes('water')) {
            countHw++;
        } else {
            countReg++;
        }
    });

    // Populate Pricing Breakdown
    const pEl = document.getElementById('country-count-payware');
    if (pEl) pEl.innerText = countPayware;
    const fEl = document.getElementById('country-count-freeware');
    if (fEl) fEl.innerText = countFreeware;
    const aEl = document.getElementById('country-count-asobo');
    if (aEl) aEl.innerText = countAsobo;
    const dEl = document.getElementById('country-count-default');
    if (dEl) dEl.innerText = countDefault;

    // Populate Total Spent
    const spentEl = document.getElementById('country-drawer-total-spent');
    if (spentEl) spentEl.innerText = formatCurrency(totalSpentEur);

    // Populate Airport Types
    const intEl = document.getElementById('country-type-int');
    if (intEl) intEl.innerText = countInt;
    const regEl = document.getElementById('country-type-reg');
    if (regEl) regEl.innerText = countReg;
    const gaEl = document.getElementById('country-type-ga');
    if (gaEl) gaEl.innerText = countGa;
    const hwEl = document.getElementById('country-type-hw');
    if (hwEl) hwEl.innerText = countHw;

    // Update Interactive Country Filter Buttons
    updateCountryFilterButtonsUI();

    // Filter Airports in this country based on active country pricing & type filter sets
    const filteredCountryAirports = countryAirports.filter(ap => {
        const pt = getAirportPricingType(ap);
        let catKey = 'FREEWARE';
        if (pt === 'Payware') catKey = 'PAYWARE';
        else if (pt === 'Asobo') catKey = 'ASOBO';
        else if (pt === 'Default' || ap.pricing_type === 'Default' || ap.package_name === 'Default MSFS Base Airport') catKey = 'DEFAULT';

        if (!selectedCountryPricingFilters.has(catKey)) return false;

        const typeStr = (ap.english_type || ap.type || '').toLowerCase();
        let typeKey = 'REG';
        if (typeStr.includes('international')) typeKey = 'INT';
        else if (typeStr.includes('regional')) typeKey = 'REG';
        else if (typeStr.includes('general') || typeStr.includes('ga')) typeKey = 'GA';
        else if (typeStr.includes('heli') || typeStr.includes('water')) typeKey = 'HW';

        return selectedCountryTypeFilters.has(typeKey);
    });

    // Populate Sceneries List
    const sceneryBadgeEl = document.getElementById('country-scenery-count-badge');
    if (sceneryBadgeEl) sceneryBadgeEl.innerText = `${filteredCountryAirports.length} ${t('country.airports_count', 'Airports')}`;

    const listEl = document.getElementById('country-airports-list');
    if (listEl) {
        if (filteredCountryAirports.length === 0) {
            listEl.innerHTML = `
                <div class="p-4 rounded-xl bg-slate-900/60 border border-slate-800 text-center space-y-1">
                    <p class="text-xs font-semibold text-slate-400">${t('country.no_match', 'No Airports Matching Filter')}</p>
                    <p class="text-[10px] text-slate-500">${t('country.no_match_sub', 'Try enabling more pricing or airport type filter buttons above.')}</p>
                </div>
            `;
        } else {
            const airportsByCat = {
                'Payware': [],
                'Freeware': [],
                'Asobo': [],
                'Default': []
            };

            filteredCountryAirports.forEach(ap => {
                const cat = getNormalizedPricingCategory(ap);
                if (airportsByCat[cat]) {
                    airportsByCat[cat].push(ap);
                } else {
                    airportsByCat['Default'].push(ap);
                }
            });

            // Sort airports within each category alphabetically by ICAO
            Object.values(airportsByCat).forEach(list => {
                list.sort((a, b) => (a.icao || '').localeCompare(b.icao || ''));
            });

            const categoryKeys = ['Payware', 'Freeware', 'Asobo', 'Default'];

            const categoriesHtml = categoryKeys.map(catKey => {
                const items = airportsByCat[catKey];
                if (!items || items.length === 0) return '';

                const cfg = COUNTRY_CATEGORY_CONFIG[catKey];
                const containsExpanded = Boolean(expandedCountryIcao && items.some(a => a.icao === expandedCountryIcao));
                const isOpen = containsExpanded || getCountryAccordionState(catKey);

                return `
                    <div class="rounded-2xl bg-slate-900/90 border ${cfg.borderClass} shadow-lg overflow-hidden transition-all">
                        <button type="button" onclick="toggleCountryCategoryAccordion('${catKey}')"
                                class="w-full px-3.5 py-2.5 flex items-center justify-between gap-3 text-left ${cfg.headerHover} transition-colors cursor-pointer select-none bg-slate-900/95 border-0">
                            <div class="flex items-center gap-2.5 min-w-0">
                                ${cfg.icon}
                                <span class="text-xs font-bold ${cfg.textColor} uppercase tracking-wider">${t(cfg.titleKey, cfg.defaultTitle)}</span>
                                <span class="min-w-[20px] text-center px-1.5 py-0.5 rounded-sm text-[10px] font-mono font-bold ${cfg.badgeClass}">${items.length}</span>
                            </div>
                            <i id="country-category-icon-${catKey}" class="fa-solid fa-chevron-down text-slate-500 text-xs transition-transform duration-200 shrink-0 ${isOpen ? 'rotate-0' : '-rotate-90'}"></i>
                        </button>
                        <div id="country-category-content-${catKey}" class="p-2 space-y-2 border-t border-slate-800/60 ${isOpen ? '' : 'hidden'}">
                            ${items.map(ap => renderCountryAirportCard(ap)).join('')}
                        </div>
                    </div>
                `;
            }).filter(Boolean).join('');

            listEl.innerHTML = categoriesHtml;
        }
    }

    // 4. Slide Drawer Track to Country Pane and Open Drawer
    const backBtn = document.getElementById('btn-country-back-prev');
    const backText = document.getElementById('btn-country-back-prev-text');
    const backIcao = document.getElementById('btn-country-back-prev-icao');
    if (backBtn) {
        if (previousActiveAirport && previousActiveAirport.icao) {
            const safeName = previousActiveAirport.name ? ` - ${getCleanAirportName(previousActiveAirport.name, previousActiveAirport.city)}` : '';
            if (backText) backText.innerText = `Back to ${previousActiveAirport.icao}${safeName}`;
            if (backIcao) backIcao.innerText = previousActiveAirport.icao;
            backBtn.classList.remove('hidden');
            backBtn.classList.add('flex');
        } else {
            backBtn.classList.add('hidden');
            backBtn.classList.remove('flex');
        }
    }

    setDrawerSlidePosition('COUNTRY');
}

