function extractIcaoFromDroppedFile(filename, contentStr = '') {
    const fn = (filename || '').toUpperCase();
    const cleanFn = fn.replace(/\.DISABLED$/, '').replace(/\.INI$/, '').replace(/\.ZIP$/, '');
    
    // Check afcad_path in content if provided
    if (contentStr) {
        const afcadMatch = contentStr.match(/afcad_path\s*=\s*([^\r\n]+)/i);
        if (afcadMatch) {
            const afcadVal = afcadMatch[1].toUpperCase();
            const bglMatch = afcadVal.match(/([A-Z]{4})(?:-[A-Z0-9]+)?(?:-SCENE)?\.BGL/i) || afcadVal.match(/[-_\\/]([A-Z]{4})[-_\\/]/i);
            if (bglMatch && bglMatch[1]) {
                const cand = bglMatch[1].toUpperCase();
                if (typeof getAirportByIcao === 'function' && getAirportByIcao(cand)) return cand;
                if (typeof WORLD_CAPITAL_AIRPORTS !== 'undefined' && WORLD_CAPITAL_AIRPORTS[cand]) return cand;
                return cand;
            }
        }
    }

    // Direct 4-letter token in filename
    const tokens = cleanFn.split(/[-_ .]+/);
    for (const tok of tokens) {
        if (tok.length === 4 && /^[A-Z]{4}$/.test(tok)) {
            if (typeof getAirportByIcao === 'function' && getAirportByIcao(tok)) return tok;
            return tok;
        }
    }
    return null;
}

async function checkGsxDropConflictAndInstall(icao, installPayload, rawContent = '') {
    let targetIcao = (icao || '').toUpperCase();
    let newFilename = installPayload.filename || (installPayload.filePath ? installPayload.filePath.split(/[\\/]/).pop() : 'new_profile.ini');

    let evalRes = null;
    if (window.pywebview && window.pywebview.api && window.pywebview.api.evaluate_incoming_gsx_profile) {
        try {
            const raw = await window.pywebview.api.evaluate_incoming_gsx_profile(
                targetIcao,
                installPayload.filePath || '',
                installPayload.base64Data || '',
                installPayload.filename || newFilename
            );
            evalRes = typeof raw === 'string' ? JSON.parse(raw) : raw;
        } catch (e) {
            console.error("Evaluation error:", e);
        }
    }

    const detectedIcao = (evalRes && evalRes.detected_icao) || extractIcaoFromDroppedFile(newFilename, rawContent);
    if (!targetIcao && detectedIcao) {
        targetIcao = detectedIcao;
    }

    // 1. ICAO Mismatch check
    if (detectedIcao && targetIcao && detectedIcao !== targetIcao) {
        showCustomModal({
            title: t('gsx.drop_mismatch_title', '⚠️ ICAO Mismatch Detected'),
            message: `
                <div class="space-y-3">
                    <p class="text-xs text-slate-300 leading-relaxed">
                        ${t('gsx.drop_mismatch_msg', `The dropped profile (<strong>${escapeHtml(newFilename)}</strong>) appears to be for airport <strong>${detectedIcao}</strong>, but you are currently viewing <strong>${targetIcao}</strong>.<br><br>Where would you like to install it?`, { filename: newFilename, detected: detectedIcao, target: targetIcao })}
                    </p>
                </div>
            `,
            type: 'warning',
            confirmText: t('gsx.install_for_detected', `Install for ${detectedIcao} (Recommended)`, { detected: detectedIcao }),
            cancelText: t('gsx.install_for_target', `Force for ${targetIcao}`, { target: targetIcao }),
            showCancel: true,
            confirmClass: 'px-5 py-2.5 rounded-xl bg-cyan-600 hover:bg-cyan-500 text-white font-bold text-xs transition-colors border-0 cursor-pointer shadow-md shadow-cyan-950/40',
            onConfirm: () => {
                checkGsxDropConflictAndInstall(detectedIcao, installPayload, rawContent);
            },
            onCancel: () => {
                proceedWithGsxDropInstallation(targetIcao, installPayload, evalRes);
            }
        });
        return;
    }

    proceedWithGsxDropInstallation(targetIcao || 'GSX', installPayload, evalRes);
}

function proceedWithGsxDropInstallation(targetIcao, installPayload, evalRes) {
    const incoming = (evalRes && evalRes.incoming) || {};
    const existingActive = (evalRes && evalRes.existing_active) || [];
    const activeScenery = (evalRes && evalRes.active_scenery) || null;
    const newFilename = installPayload.filename || (installPayload.filePath ? installPayload.filePath.split(/[\\/]/).pop() : (incoming.filename || 'new_profile.ini'));

    const isIncomingMismatch = (incoming.status || '').startsWith('MISMATCH');
    const isIncomingMatched = incoming.status === 'MATCHED';
    const hasExistingActive = existingActive.length > 0;
    const existingBest = existingActive[0] || null;
    const isExistingMatched = existingBest && existingBest.status === 'MATCHED';

    if (isIncomingMismatch) {
        showCustomModal({
            title: t('gsx.drop_incompatible_title', `Incompatible GSX Profile (${targetIcao})`, { icao: targetIcao }),
            message: `
                <div class="space-y-3 text-left">
                    <div class="p-3.5 rounded-2xl bg-rose-950/60 border border-rose-800/70 space-y-1.5">
                        <div class="flex items-center gap-2 text-xs font-mono font-bold text-rose-300">
                            <i class="fa-solid fa-triangle-exclamation text-rose-400"></i>
                            <span>${t('gsx.drop_mismatch_warning_title', 'Incompatible Profile Warning')}</span>
                        </div>
                        <p class="text-xs font-mono text-rose-200/90 leading-relaxed">
                            ${escapeHtml(incoming.reason || 'This GSX profile is not compatible with your installed scenery version.')}
                        </p>
                    </div>

                    <div class="p-2.5 rounded-xl bg-slate-950 border border-slate-800 flex items-center justify-between gap-2">
                        <div class="min-w-0 flex-1">
                            <div class="flex items-center gap-2">
                                <span class="text-xs font-mono font-bold text-slate-200 truncate">${escapeHtml(newFilename)}</span>
                                <span class="text-[9px] font-mono font-bold px-1.5 py-0.5 rounded leading-tight bg-rose-600 text-white">
                                    MISMATCH VERSION
                                </span>
                            </div>
                            ${(incoming.gates_count || incoming.creator || incoming.target_pkg) ? `
                                <div class="text-[10px] font-mono text-slate-400 truncate mt-0.5">
                                    ${[incoming.gates_count ? `${incoming.gates_count} gates` : '', incoming.creator ? `By ${incoming.creator}` : '', incoming.target_pkg || ''].filter(Boolean).join(' • ')}
                                </div>
                            ` : ''}
                        </div>
                    </div>

                    ${hasExistingActive ? `
                        <div class="text-[11px] font-mono text-slate-400 px-0.5">
                            ${t('gsx.drop_existing_preserved_note', 'Current active profile will be preserved if you cancel.')}
                        </div>
                    ` : ''}
                </div>
            `,
            type: 'warning',
            confirmText: t('gsx.btn_force_install', 'Install (Not Recommended)'),
            cancelText: t('common.cancel', 'Cancel'),
            showCancel: true,
            confirmClass: 'px-5 py-2.5 rounded-xl bg-amber-700/90 hover:bg-amber-600 text-white font-bold text-xs transition-colors border-0 cursor-pointer shadow-md shadow-amber-950/40',
            cancelClass: 'px-5 py-2.5 rounded-xl bg-slate-800 hover:bg-slate-700 text-slate-200 hover:text-white font-bold text-xs border border-slate-700 cursor-pointer transition-colors',
            onCancel: () => {
                if (typeof refreshAirportGsxStatus === 'function') {
                    refreshAirportGsxStatus(targetIcao);
                }
                if (typeof resetRadialGsxDropzoneUI === 'function') {
                    resetRadialGsxDropzoneUI();
                }
            },
            onConfirm: async () => {
                await executeGsxInstallationForIcao(targetIcao, { ...installPayload, replaceExisting: true });
            }
        });
        return;
    }

    if (hasExistingActive) {
        let alertBoxHtml = '';
        if (isIncomingMatched) {
            alertBoxHtml = `
                <div class="p-3 rounded-xl bg-emerald-950/60 border border-emerald-800/70 space-y-1">
                    <div class="flex items-center gap-1.5 text-xs font-mono font-bold text-emerald-300">
                        <i class="fa-solid fa-circle-check text-emerald-400"></i>
                        <span>${t('gsx.drop_compatible_title', 'Compatible Profile')}</span>
                    </div>
                    <p class="text-[11px] font-mono text-emerald-200/90 leading-relaxed">
                        ${escapeHtml(incoming.reason || 'Profile matches your installed scenery.')}
                    </p>
                </div>
            `;
        }

        let existingListHtml = `
            <div class="space-y-1.5 pt-1">
                <div class="text-[11px] font-mono text-slate-400">
                    ${t('gsx.drop_current_active', 'Current active profile (will be replaced):')}
                </div>
                ${existingActive.map(f => `
                    <div class="p-2.5 rounded-xl bg-slate-950 border border-slate-800 flex items-center justify-between gap-2">
                        <div class="min-w-0 flex-1">
                            <div class="flex items-center gap-2">
                                <span class="text-xs font-mono font-bold text-slate-200 truncate">${escapeHtml(f.filename)}</span>
                                <span class="text-[9px] font-mono font-bold px-1.5 py-0.5 rounded leading-tight ${f.status === 'MATCHED' ? 'bg-emerald-600 text-white' : 'bg-slate-700 text-slate-300'}">
                                    ${escapeHtml(f.status || 'ACTIVE')}
                                </span>
                            </div>
                            <div class="text-[10px] font-mono text-slate-400 truncate mt-0.5">
                                ${[f.gates_count ? `${f.gates_count} gates` : '', f.creator ? `By ${f.creator}` : '', f.target_pkg || ''].filter(Boolean).join(' • ')}
                            </div>
                        </div>
                    </div>
                `).join('')}
            </div>
        `;

        let incomingHtml = `
            <div class="space-y-1.5 pt-1">
                <div class="text-[11px] font-mono text-slate-400">
                    ${t('gsx.drop_incoming_title', 'Incoming new profile:')}
                </div>
                <div class="p-2.5 rounded-xl bg-slate-950 border border-cyan-800/80 flex items-center justify-between gap-2">
                    <div class="min-w-0 flex-1">
                        <div class="flex items-center gap-2">
                            <span class="text-xs font-mono font-bold text-cyan-200 truncate">${escapeHtml(newFilename)}</span>
                            <span class="text-[9px] font-mono font-bold px-1.5 py-0.5 rounded leading-tight bg-emerald-600 text-white">
                                ${escapeHtml(incoming.status || 'NEW')}
                            </span>
                        </div>
                        <div class="text-[10px] font-mono text-slate-400 truncate mt-0.5">
                            ${[incoming.gates_count ? `${incoming.gates_count} gates` : '', incoming.creator ? `By ${incoming.creator}` : '', incoming.target_pkg || ''].filter(Boolean).join(' • ')}
                        </div>
                    </div>
                </div>
            </div>
        `;

        showCustomModal({
            title: t('gsx.drop_conflict_title', `Install GSX Profile (${targetIcao})`, { icao: targetIcao }),
            message: `
                <div class="space-y-2.5 text-left">
                    ${alertBoxHtml}
                    ${existingListHtml}
                    ${incomingHtml}
                    <p class="text-[11px] font-mono text-slate-400 pt-1">
                        ${t('gsx.drop_replace_notice', 'Installing this profile will automatically replace and disable previous profiles for this airport.')}
                    </p>
                </div>
            `,
            type: 'info',
            confirmText: t('gsx.btn_replace_current', 'Install & Replace (Recommended)'),
            cancelText: t('common.cancel', 'Cancel'),
            showCancel: true,
            confirmClass: 'px-5 py-2.5 rounded-xl bg-cyan-600 hover:bg-cyan-500 text-white font-bold text-xs transition-colors border-0 cursor-pointer shadow-md shadow-cyan-950/40',
            cancelClass: 'px-5 py-2.5 rounded-xl bg-slate-800 hover:bg-slate-700 text-slate-200 hover:text-white font-bold text-xs border border-slate-700 cursor-pointer transition-colors',
            onCancel: () => {
                if (typeof refreshAirportGsxStatus === 'function') {
                    refreshAirportGsxStatus(targetIcao);
                }
                if (typeof resetRadialGsxDropzoneUI === 'function') {
                    resetRadialGsxDropzoneUI();
                }
            },
            onConfirm: async () => {
                await executeGsxInstallationForIcao(targetIcao, { ...installPayload, replaceExisting: true });
            }
        });
        return;
    }

    executeGsxInstallationForIcao(targetIcao, { ...installPayload, replaceExisting: true });
}
window.checkGsxDropConflictAndInstall = checkGsxDropConflictAndInstall;
async function executeGsxInstallationForIcao(icao, { filePath = '', base64Data = '', filename = '', replaceExisting = false } = {}) {
    if (!window.pywebview || !window.pywebview.api || !window.pywebview.api.install_gsx_profile) {
        if (typeof resetRadialGsxDropzoneUI === 'function') resetRadialGsxDropzoneUI();
        return;
    }
    try {
        const raw = await window.pywebview.api.install_gsx_profile(
            icao || '',
            filePath || '',
            base64Data || '',
            filename || '',
            replaceExisting
        );
        const parsed = typeof raw === 'string' ? JSON.parse(raw) : raw;
        if (parsed && parsed.status === 'ok') {
            const targetIcao = (parsed.target_icao || icao || '').toUpperCase();
            if (parsed.airports && Array.isArray(parsed.airports)) {
                allAirportsData = parsed.airports;
            }

            if (parsed.audit) {
                window.gsxAuditData = parsed.audit;
            } else if (window.pywebview.api.scan_gsx_audit) {
                const auditRaw = await window.pywebview.api.scan_gsx_audit();
                const auditParsed = typeof auditRaw === 'string' ? JSON.parse(auditRaw) : auditRaw;
                if (auditParsed && auditParsed.status === 'ok') {
                    window.gsxAuditData = auditParsed.data;
                }
            }

            const auditEntry = (window.gsxAuditData && window.gsxAuditData.by_icao) ? window.gsxAuditData.by_icao[targetIcao] : null;
            let iniF = null;
            let filePath = null;
            if (parsed.installed_files && parsed.installed_files.length > 0) {
                iniF = parsed.installed_files.find(f => f.toLowerCase().endsWith('.ini')) || parsed.installed_files[0];
            } else if (auditEntry && auditEntry.files) {
                const actF = auditEntry.files.find(f => !f.is_disabled);
                if (actF) {
                    iniF = actF.filename;
                    filePath = actF.path;
                }
            }

            syncAirportGsxState(targetIcao, {
                hasProfile: true,
                filename: iniF || filename,
                path: filePath,
                auditEntry: auditEntry
            });

            if (parsed.airport) {
                const ap = (typeof getAirportByIcao === 'function') ? getAirportByIcao(targetIcao) : null;
                if (ap) Object.assign(ap, parsed.airport);
                if (typeof currentRadialAirport !== 'undefined' && currentRadialAirport && currentRadialAirport.icao === targetIcao) {
                    Object.assign(currentRadialAirport, parsed.airport);
                }
                if (typeof selectedAirport !== 'undefined' && selectedAirport && selectedAirport.icao === targetIcao) {
                    Object.assign(selectedAirport, parsed.airport);
                }
            }

            // Explicitly re-render details modal if open for targetIcao
            const detailsModal = document.getElementById('radial-details-modal');
            if (detailsModal && !detailsModal.classList.contains('hidden')) {
                const modalIcao = detailsModal.dataset.icao || (currentRadialAirport ? currentRadialAirport.icao : null);
                if (modalIcao === targetIcao) {
                    const renderTarget = currentRadialAirport || ((typeof getAirportByIcao === 'function') ? getAirportByIcao(targetIcao) : null);
                    if (renderTarget && typeof renderRadialGsx === 'function') {
                        renderRadialGsx(renderTarget);
                    }
                }
            }

            if (typeof renderGsxAuditModal === 'function' && window.isGsxAuditOpen) {
                renderGsxAuditModal();
            }
            if (typeof updateGsxHeaderAndTabBadges === 'function') {
                updateGsxHeaderAndTabBadges();
            }

            const fileCount = (parsed.installed_files || []).length;
            const fileMsg = fileCount > 0 ? `: ${parsed.installed_files.join(', ')}` : '';
            if (typeof showToast === 'function') {
                showToast(`✓ GSX profile installed for ${targetIcao}${fileMsg}`, 'success');
            }
        } else if (parsed && parsed.status === 'error') {
            if (typeof showToast === 'function') {
                showToast(parsed.message || 'Failed to install GSX profile', 'error');
            }
        }
    } catch (e) {
        console.error("Error installing GSX profile for icao:", e);
        if (typeof showToast === 'function') {
            showToast(`Installation error: ${e.message || String(e)}`, 'error');
        }
    } finally {
        if (typeof resetRadialGsxDropzoneUI === 'function') {
            resetRadialGsxDropzoneUI();
        }
    }
}
async function installGsxProfileFromModal(icao) {
    if (isFlightPlanningMode) {
        showToast('GSX profile installation is locked during Flight Planning mode.', 'warning');
        return;
    }
    await executeGsxInstallationForIcao(icao, { filePath: '' });
}

async function installBundledGsxProfile(icao) {
    if (isFlightPlanningMode) {
        showToast('GSX profile installation is locked during Flight Planning mode.', 'warning');
        return;
    }
    if (!window.pywebview || !window.pywebview.api || !window.pywebview.api.install_bundled_gsx_profile) return;
    try {
        if (typeof showToast === 'function') {
            showToast(t('gsx.installing_bundled', 'Installing official GSX profile...'), 'info');
        }
        const raw = await window.pywebview.api.install_bundled_gsx_profile(icao);
        const parsed = typeof raw === 'string' ? JSON.parse(raw) : raw;
        if (parsed && parsed.status === 'ok') {
            if (parsed.airports && Array.isArray(parsed.airports)) {
                allAirportsData = parsed.airports;
            }
            const targetIcao = (icao || '').toUpperCase();

            if (window.pywebview.api.scan_gsx_audit) {
                const auditRaw = await window.pywebview.api.scan_gsx_audit();
                const auditParsed = typeof auditRaw === 'string' ? JSON.parse(auditRaw) : auditRaw;
                if (auditParsed && auditParsed.status === 'ok') {
                    window.gsxAuditData = auditParsed.data;
                }
            }

            const auditEntry = (window.gsxAuditData && window.gsxAuditData.by_icao) ? window.gsxAuditData.by_icao[targetIcao] : null;
            let iniF = null;
            let filePath = null;
            if (parsed.installed_files && parsed.installed_files.length > 0) {
                iniF = parsed.installed_files.find(f => f.toLowerCase().endsWith('.ini')) || parsed.installed_files[0];
            } else if (auditEntry && auditEntry.files) {
                const actF = auditEntry.files.find(f => !f.is_disabled);
                if (actF) {
                    iniF = actF.filename;
                    filePath = actF.path;
                }
            }

            syncAirportGsxState(targetIcao, {
                hasProfile: true,
                filename: iniF,
                path: filePath,
                auditEntry: auditEntry
            });

            const ap = (typeof getAirportByIcao === 'function') ? getAirportByIcao(targetIcao) : null;
            if (ap && ap.bundled_gsx_profile) {
                ap.bundled_gsx_profile.is_installed = true;
            }
            if (currentRadialAirport && currentRadialAirport.icao === targetIcao && currentRadialAirport.bundled_gsx_profile) {
                currentRadialAirport.bundled_gsx_profile.is_installed = true;
            }

            // Explicitly re-render details modal if open for targetIcao
            const detailsModal = document.getElementById('radial-details-modal');
            if (detailsModal && !detailsModal.classList.contains('hidden')) {
                const modalIcao = detailsModal.dataset.icao || (currentRadialAirport ? currentRadialAirport.icao : null);
                if (modalIcao === targetIcao) {
                    const renderTarget = currentRadialAirport || ap;
                    if (renderTarget && typeof renderRadialGsx === 'function') {
                        renderRadialGsx(renderTarget);
                    }
                }
            }

            if (typeof renderGsxAuditModal === 'function' && window.isGsxAuditOpen) {
                renderGsxAuditModal();
            }
            if (typeof updateGsxHeaderAndTabBadges === 'function') {
                updateGsxHeaderAndTabBadges();
            }

            if (typeof showToast === 'function') {
                showToast(t('gsx.bundled_installed_success', 'Official GSX profile installed successfully'), 'success');
            }
        } else {
            if (typeof showToast === 'function') {
                showToast((parsed && parsed.message) || 'Failed to install official GSX profile', 'error');
            }
        }
    } catch (e) {
        console.error("Error installing bundled GSX profile:", e);
        if (typeof showToast === 'function') {
            showToast(`Error: ${e.message || String(e)}`, 'error');
        }
    }
}
window.installBundledGsxProfile = installBundledGsxProfile;

function handleGsxAuditDragOver(e, icao) {
    e.preventDefault();
    e.stopPropagation();
    if (e.dataTransfer) {
        e.dataTransfer.dropEffect = 'copy';
    }
    const zone = document.getElementById(`gsx-dropzone-${icao}`);
    if (zone) {
        zone.classList.add('border-cyan-400', 'bg-cyan-950/80', 'scale-[1.03]', 'shadow-lg', 'shadow-cyan-500/25');
        zone.classList.remove('border-slate-700', 'border-slate-800', 'bg-slate-950');
    }
}

function handleGsxAuditDragLeave(e, icao) {
    e.preventDefault();
    e.stopPropagation();
    const zone = document.getElementById(`gsx-dropzone-${icao}`);
    if (zone) {
        zone.classList.remove('border-cyan-400', 'bg-cyan-950/80', 'scale-[1.03]', 'shadow-lg', 'shadow-cyan-500/25');
        zone.classList.add('border-slate-700', 'bg-slate-950');
    }
}

async function handleGsxAuditDrop(e, icao) {
    e.preventDefault();
    e.stopPropagation();
    const zone = document.getElementById(`gsx-dropzone-${icao}`);
    if (zone) {
        zone.classList.remove('border-cyan-400', 'bg-cyan-950/40');
        zone.classList.add('border-slate-800', 'bg-slate-950/60');
    }

    if (!e.dataTransfer || !e.dataTransfer.files || e.dataTransfer.files.length === 0) return;
    const file = e.dataTransfer.files[0];
    const ext = (file.name || '').split('.').pop().toLowerCase();
    const validExts = ['ini', 'py', 'zip', 'rar', '7z', 'tar', 'gz'];
    if (!validExts.includes(ext)) {
        if (typeof showToast === 'function') {
            showToast('Please drop a GSX profile (.ini) or archive (.zip, .rar)', 'warning');
        }
        return;
    }

        const path = file.path || '';
    if (path) {
        checkGsxDropConflictAndInstall(icao, { filePath: path });
    } else {
        const reader = new FileReader();
        reader.onload = function(event) {
            const base64Data = event.target.result;
            checkGsxDropConflictAndInstall(icao, { base64Data: base64Data, filename: file.name });
        };
        reader.onerror = function() {
            if (typeof showToast === 'function') {
                showToast('Unable to read dropped file', 'error');
            }
        };
        reader.readAsDataURL(file);
    }
}

