function triggerGsxStudioSearch(icao) {
    const cleanIcao = (icao || '').toUpperCase().trim();
    if (window.pywebview && window.pywebview.api && window.pywebview.api.search_gsx_profile) {
        window.pywebview.api.search_gsx_profile(cleanIcao);
    } else {
        window.open(`https://flightsim.to/miscellaneous/gsx-pro?q=${encodeURIComponent(cleanIcao)}`, '_blank');
    }
}

function resetRadialGsxDropzoneUI() {
    const zone = document.getElementById('radial-gsx-dropzone') || document.getElementById('radial-gsx-drop-zone');
    if (zone) {
        zone.classList.remove('border-cyan-400', 'bg-cyan-950/80', 'scale-[1.02]', 'shadow-lg', 'shadow-cyan-500/25');
        zone.classList.add('border-slate-700/80', 'bg-slate-950/60');
        const textSpan = zone.querySelector('#radial-gsx-drop-text span');
        if (textSpan) {
            textSpan.innerHTML = zone.dataset.origText || 'DROP .ZIP OR .INI HERE TO INSTALL';
        }
        delete zone.dataset.origText;
    }
}
window.resetRadialGsxDropzoneUI = resetRadialGsxDropzoneUI;

function handleRadialGsxDragOver(e) {
    e.preventDefault();
    e.stopPropagation();
    if (e.dataTransfer) {
        e.dataTransfer.dropEffect = 'copy';
    }
    const zone = document.getElementById('radial-gsx-dropzone') || document.getElementById('radial-gsx-drop-zone');
    if (zone) {
        zone.classList.remove('border-slate-700/80', 'bg-slate-950/60', 'hover:border-cyan-400', 'hover:bg-cyan-950/30');
        zone.classList.add('border-cyan-400', 'bg-cyan-950/80', 'scale-[1.02]', 'shadow-lg', 'shadow-cyan-500/25');
        const textSpan = zone.querySelector('#radial-gsx-drop-text span');
        if (textSpan && !zone.dataset.origText) {
            zone.dataset.origText = textSpan.innerText;
            textSpan.innerText = 'DROP PROFILE HERE TO INSTALL';
        }
    }
}

function handleRadialGsxDragLeave(e) {
    e.preventDefault();
    e.stopPropagation();
    const zone = document.getElementById('radial-gsx-dropzone') || document.getElementById('radial-gsx-drop-zone');
    if (zone) {
        zone.classList.remove('border-cyan-400', 'bg-cyan-950/80', 'scale-[1.02]', 'shadow-lg', 'shadow-cyan-500/25');
        zone.classList.add('border-slate-700/80', 'bg-slate-950/60');
        const textSpan = zone.querySelector('#radial-gsx-drop-text span');
        if (textSpan && zone.dataset.origText) {
            textSpan.innerText = zone.dataset.origText;
            delete zone.dataset.origText;
        }
    }
}

async function handleRadialGsxDrop(e, icao) {
    e.preventDefault();
    e.stopPropagation();

    if (!e.dataTransfer || !e.dataTransfer.files || e.dataTransfer.files.length === 0) {
        resetRadialGsxDropzoneUI();
        return;
    }

    const file = e.dataTransfer.files[0];
    const ext = (file.name || '').split('.').pop().toLowerCase();
    const validExts = ['ini', 'py', 'zip', 'rar', '7z', 'tar', 'gz'];
    if (!validExts.includes(ext)) {
        resetRadialGsxDropzoneUI();
        if (typeof showToast === 'function') {
            showToast('Please drop a GSX profile (.ini) or archive (.zip, .rar, .7z)', 'warning');
        }
        return;
    }

    const zone = document.getElementById('radial-gsx-dropzone') || document.getElementById('radial-gsx-drop-zone');
    if (zone) {
        zone.classList.remove('border-cyan-400', 'bg-cyan-950/80', 'scale-[1.02]', 'shadow-lg', 'shadow-cyan-500/25');
        zone.classList.add('border-slate-700/80', 'bg-slate-950/60');
        const textSpan = zone.querySelector('#radial-gsx-drop-text span');
        if (textSpan) {
            textSpan.innerHTML = '<i class="fa-solid fa-spinner fa-spin mr-1"></i> Installing profile...';
        }
    }

    const path = file.path || '';
    const targetIcao = icao || (currentRadialAirport ? currentRadialAirport.icao : '') || (selectedAirport ? selectedAirport.icao : '');

    if (currentRadialAirport) {
        selectedAirport = currentRadialAirport;
    }

    if (path) {
        checkGsxDropConflictAndInstall(targetIcao, { filePath: path });
    } else {
        const reader = new FileReader();
        reader.onload = function(event) {
            const base64Data = event.target.result;
            checkGsxDropConflictAndInstall(targetIcao, { base64Data: base64Data, filename: file.name });
        };
        reader.onerror = function() {
            resetRadialGsxDropzoneUI();
            showCustomModal({ title: 'File Read Error', message: 'Unable to read the dropped file.', type: 'error' });
        };
        reader.readAsDataURL(file);
    }
}

function triggerRadialGsxFileBrowse(icao) {
    const targetIcao = icao || (currentRadialAirport ? currentRadialAirport.icao : '') || (selectedAirport ? selectedAirport.icao : '');
    executeGsxInstallationForIcao(targetIcao, { filePath: '' });
}
window.triggerRadialGsxFileBrowse = triggerRadialGsxFileBrowse;

async function triggerRadialInstallGsxProfile() {
    if (currentRadialAirport) {
        selectedAirport = currentRadialAirport;
    }
    await executeGsxInstallation({ filePath: '' });
    if (currentRadialAirport) {
        const updatedAp = getAirportByIcao(currentRadialAirport.icao);
        if (updatedAp) {
            currentRadialAirport = updatedAp;
            renderRadialGsx(currentRadialAirport);
        }
    }
}

async function triggerRadialSearchGsxProfile() {
    if (!currentRadialAirport) return;
    const cleanIcao = (currentRadialAirport.icao || '').toUpperCase().trim();
    try {
        if (window.pywebview && window.pywebview.api && window.pywebview.api.search_gsx_profile) {
            await window.pywebview.api.search_gsx_profile(cleanIcao);
        } else {
            window.open(`https://flightsim.to/miscellaneous/gsx-pro?q=${encodeURIComponent(cleanIcao)}`, '_blank');
        }
    } catch (e) {
        console.error("Failed to search GSX profile:", e);
    }
}

function renderRadialStarRating(rating) {
    const container = document.getElementById('radial-interactive-star-widget');
    const scoreDisplay = document.getElementById('radial-rating-score-display');
    if (!container || !scoreDisplay) return;

    container.innerHTML = '';

    if (rating > 0) {
        scoreDisplay.innerText = `★ ${rating.toFixed(1)} / 5.0`;
        scoreDisplay.className = "text-xs font-mono font-black text-amber-400";
    } else {
        scoreDisplay.innerText = "Unrated";
        scoreDisplay.className = "text-xs font-mono font-bold text-slate-500";
    }

    for (let starIdx = 1; starIdx <= 5; starIdx++) {
        const starEl = document.createElement('i');

        if (rating >= starIdx) {
            starEl.className = 'fa-solid fa-star radial-star-item full';
        } else if (rating >= starIdx - 0.5) {
            starEl.className = 'fa-solid fa-star-half-stroke radial-star-item full';
        } else {
            starEl.className = 'fa-regular fa-star radial-star-item';
        }

        starEl.addEventListener('mousemove', (e) => handleRadialStarMouseMove(e, starIdx));
        starEl.addEventListener('click', (e) => handleRadialStarClick(e, starIdx));

        container.appendChild(starEl);
    }
}

function handleRadialStarMouseMove(e, starIdx) {
    const rect = e.target.getBoundingClientRect();
    const isLeftHalf = (e.clientX - rect.left) < (rect.width / 2);
    const hoverVal = isLeftHalf ? (starIdx - 0.5) : starIdx;

    renderRadialStarRatingPreview(hoverVal);
}

function renderRadialStarRatingPreview(val) {
    const container = document.getElementById('radial-interactive-star-widget');
    const scoreDisplay = document.getElementById('radial-rating-score-display');
    if (!container || !scoreDisplay) return;

    const stars = container.querySelectorAll('.radial-star-item');

    scoreDisplay.innerText = `★ ${val.toFixed(1)}+`;
    scoreDisplay.className = "text-xs font-mono font-black text-amber-300";

    stars.forEach((starEl, index) => {
        const starIdx = index + 1;
        if (val >= starIdx) {
            starEl.className = 'fa-solid fa-star radial-star-item full';
        } else if (val >= starIdx - 0.5) {
            starEl.className = 'fa-solid fa-star-half-stroke radial-star-item full';
        } else {
            starEl.className = 'fa-regular fa-star radial-star-item';
        }
    });
}

function resetRadialStarHover() {
    if (currentRadialAirport) {
        renderRadialStarRating(currentRadialAirport.rating || 0);
    } else {
        renderRadialStarRating(0);
    }
}

async function handleRadialStarClick(e, starIdx) {
    if (!currentRadialAirport) return;

    const rect = e.target.getBoundingClientRect();
    const isLeftHalf = (e.clientX - rect.left) < (rect.width / 2);
    const ratingVal = isLeftHalf ? (starIdx - 0.5) : starIdx;

    currentRadialAirport.rating = ratingVal;
    userRatingsMap[currentRadialAirport.icao] = ratingVal;
    const apInAll = getAirportByIcao(currentRadialAirport.icao);
    if (apInAll) apInAll.rating = ratingVal;

    renderRadialStarRating(ratingVal);

    try {
        if (window.pywebview && window.pywebview.api && window.pywebview.api.set_rating) {
            await window.pywebview.api.set_rating(currentRadialAirport.icao, ratingVal);
        }
    } catch (err) {
        console.error("Failed to save rating:", err);
    }

    filterAirports();
}

async function clearRadialRating() {
    if (!currentRadialAirport) return;

    currentRadialAirport.rating = 0;
    delete userRatingsMap[currentRadialAirport.icao];
    const apInAll = getAirportByIcao(currentRadialAirport.icao);
    if (apInAll) apInAll.rating = 0;

    renderRadialStarRating(0);

    try {
        if (window.pywebview && window.pywebview.api && window.pywebview.api.set_rating) {
            await window.pywebview.api.set_rating(currentRadialAirport.icao, 0);
        }
    } catch (err) {
        console.error("Failed to clear rating:", err);
    }

    filterAirports();
}

function renderRadialPrice(ap) {
    if (!ap) return;
    const currSymEl = document.getElementById('radial-price-curr-symbol');
    const priceInputEl = document.getElementById('radial-price-input');
    const priceTagEl = document.getElementById('radial-price-tag');

    const currSymbols = { 'USD': '$', 'EUR': '€', 'GBP': '£', 'JPY': '¥', 'CAD': 'CA$', 'AUD': 'A$' };
    const curSymbol = currSymbols[selectedCurrency] || CURRENCY_SYMBOLS[selectedCurrency] || '€';
    if (currSymEl) currSymEl.innerText = curSymbol;

    const pValEur = ap.price_eur || 0;
    const formattedP = formatCurrency(pValEur);

    let tagText = "";
    if (ap.is_custom_price) {
        tagText = `Paid: ${formattedP}`;
    } else if (ap.is_bundle || ap.bundle_total_price) {
        const bTotalFormatted = formatCurrency(ap.bundle_total_price || 39.00);
        tagText = `Bundle: ${bTotalFormatted}`;
    } else {
        tagText = `Est: ${formattedP}`;
    }
    if (priceTagEl) {
        priceTagEl.innerText = tagText;
        priceTagEl.className = "flex-1 text-center text-xs font-sans font-bold text-[#CBD5E1] bg-[#0E121A] border border-[#2D3A54] px-2 py-1 rounded-md truncate whitespace-nowrap";
    }

    const rate = CURRENCY_RATES[selectedCurrency] || 1.0;
    const valConverted = pValEur * rate;
    if (priceInputEl) {
        priceInputEl.value = ap.is_custom_price ? valConverted.toFixed(2) : '';
    }
}

async function saveRadialCustomPrice() {
    if (!currentRadialAirport) return;
    const inputEl = document.getElementById('radial-price-input');
    if (!inputEl) return;
    const inputVal = inputEl.value;
    const rate = CURRENCY_RATES[selectedCurrency] || 1.0;

    let valInEur = null;
    if (inputVal !== '' && !isNaN(inputVal)) {
        valInEur = parseFloat(inputVal) / rate;
    }

    try {
        if (window.pywebview && window.pywebview.api && window.pywebview.api.set_custom_price) {
            const resStr = await window.pywebview.api.set_custom_price(currentRadialAirport.icao, valInEur);
            const res = JSON.parse(resStr);
            if (res.status === 'ok') {
                allAirportsData = res.airports;
                allAirportsData.forEach(ap => {
                    if (userRatingsMap[ap.icao] !== undefined) {
                        ap.rating = userRatingsMap[ap.icao];
                    }
                });
                updateStats(allAirportsData);
                filterAirports();
                const updatedAp = getAirportByIcao(currentRadialAirport.icao);
                if (updatedAp) {
                    currentRadialAirport = updatedAp;
                    renderRadialPrice(currentRadialAirport);
                }
                showToast("✓ Custom price saved", "success");
            }
        }
    } catch (e) {
        console.error("Failed to save custom price:", e);
    }
}

async function resetRadialCustomPrice() {
    if (!currentRadialAirport) return;
    const inputEl = document.getElementById('radial-price-input');
    if (inputEl) inputEl.value = '';
    await saveRadialCustomPrice();
}

// Dismiss radial menu ONLY on clean left-click outside on map background
window.addEventListener('click', function (e) {
    if (e.button !== 0) return; // Strict Left-Click ONLY
    if (isMapDragging) return; // Do NOT dismiss on drag / pan release
    if (!currentRadialAirport) return;

    // 1. Never dismiss if clicking outside the Leaflet map container (e.g. sidebars, headers, floating modals, tools)
    if (!e.target.closest('#map')) return;

    // 2. Never dismiss if clicking on any UI elements, modals, panels, markers, or controls inside the viewport
    if (e.target.closest && (
        e.target.closest('.custom-map-marker') ||
        e.target.closest('#airport-radial-menu') ||
        e.target.closest('#filter-radial-menu') ||
        e.target.closest('#radial-details-modal') ||
        e.target.closest('#radial-airlines-modal') ||
        e.target.closest('#radial-sceneries-extension') ||
        e.target.closest('#settings-modal') ||
        e.target.closest('#gsx-audit-modal') ||
        e.target.closest('#conflict-modal') ||
        e.target.closest('#flight-optimizer-modal') ||
        e.target.closest('#bottom-map-toolbar') ||
        e.target.closest('#flight-planning-banner') ||
        e.target.closest('#classic-flight-ops-panel') ||
        e.target.closest('#classic-nav-panel') ||
        e.target.closest('#sidebar-panel') ||
        e.target.closest('#app-header') ||
        e.target.closest('.window-manager-window') ||
        e.target.closest('.glass-panel') ||
        e.target.closest('.leaflet-control')
    )) return;

    const radialEl = document.getElementById('airport-radial-menu');
    const airlinesModal = document.getElementById('radial-airlines-modal');
    const detailsModal = document.getElementById('radial-details-modal');
    const sceneriesExt = document.getElementById('radial-sceneries-extension');
    const drawerEl = document.getElementById('detail-drawer');
    const settingsModal = document.getElementById('settings-modal');
    const bottomToolbar = document.getElementById('bottom-map-toolbar');
    const rescanModal = document.getElementById('rescan-modal');
    const exportModal = document.getElementById('export-modal');
    const bannerEl = document.getElementById('flight-planning-banner');

    if (radialEl && radialEl.contains(e.target)) return;
    if (airlinesModal && airlinesModal.contains(e.target)) return;
    if (detailsModal && detailsModal.contains(e.target)) return;
    if (sceneriesExt && sceneriesExt.contains(e.target)) return;
    if (drawerEl && drawerEl.contains(e.target)) return;
    if (settingsModal && settingsModal.contains(e.target)) return;
    if (bottomToolbar && bottomToolbar.contains(e.target)) return;
    if (rescanModal && rescanModal.contains(e.target)) return;
    if (exportModal && exportModal.contains(e.target)) return;
    if (bannerEl && bannerEl.contains(e.target)) return;

    // When in any of the radial inspection sub-modes (Details, Airlines, Sceneries),
    // clicking outside on the map should NEVER dismiss the radial menu nor the window!
    // The radial menu stays visible and anchored.
    if (isAirlinesModalOpen() || isDetailsModalOpen() || isSceneriesExtensionOpen() || (typeof isGsxAuditOpen !== 'undefined' && isGsxAuditOpen)) {
        return;
    }

    // In classic mode, clicking outside on the map is handled by Leaflet map click (calls closeClassicAirportView)
    if (isClassicNavMode()) {
        if (typeof closeClassicAirportView === 'function') {
            closeClassicAirportView();
        }
        return;
    }

    if (radialEl && !radialEl.classList.contains('hidden')) {
        closeAirportRadialMenu();
        selectedAirport = null;
    }
});

// Forward wheel events over radial menu to map container so zooming works smoothly everywhere
const radialContainerEl = document.getElementById('airport-radial-menu');
if (radialContainerEl) {
    radialContainerEl.addEventListener('wheel', function (e) {
        if (map && map.getContainer()) {
            map.getContainer().dispatchEvent(new WheelEvent('wheel', e));
        }
    }, { passive: true });
}

// Forward wheel events over route airport circles to map container so zooming works smoothly everywhere
document.addEventListener('wheel', function (e) {
    if (e.target && e.target.closest && e.target.closest('.route-airport-circle')) {
        if (map && typeof map.getContainer === 'function') {
            const container = map.getContainer();
            if (container) {
                container.dispatchEvent(new WheelEvent('wheel', e));
            }
        }
    }
}, { passive: true });

