function isExternalAutoFpsActive() {
    if (window.smartLodAxisState && window.smartLodAxisState.external_autofps) return true;
    if (typeof currentSettings !== 'undefined' && (currentSettings.external_autofps || currentSettings.dynamic_lod_engine === 'external_autofps')) return true;
    if (typeof currentBgToolsData !== 'undefined' && currentBgToolsData && currentBgToolsData.autofps_running) {
        if (typeof modalAutoFpsChoice !== 'undefined' && modalAutoFpsChoice === 'kill') {
            return false;
        }
        return true;
    }
    return false;
}

const FLIGHT_OPT_SECTORS = [
    { key: 'my_rig', label: 'MY RIG' },
    { key: 'graphics', label: 'MSFS GRAPHIC<br>SETTINGS' },
    { key: 'smart_lod', label: 'SMART LOD' },
    { key: 'telemetry', label: 'TELEMETRY' },
    { key: 'route', label: 'ROUTE<br>OPTIMIZATION' }
];

function isFloatingWindowOpen(winKey) {
    const elId = (typeof FLOATING_WINDOW_MAP !== 'undefined' && FLOATING_WINDOW_MAP[winKey]) ? FLOATING_WINDOW_MAP[winKey] : winKey;
    const winEl = document.getElementById(elId);
    return !!(winEl && !winEl.classList.contains('hidden'));
}

function updateFlightOptimizerRadialSectors() {
    const isExtAutoFps = isExternalAutoFpsActive();
    FLIGHT_OPT_SECTORS.forEach(item => {
        const gEl = document.getElementById(`radial-opt-sector-${item.key}`);
        if (!gEl) return;
        const isWinOpen = isFloatingWindowOpen(item.key);
        const isSmartLodLocked = (!window.IS_LITE && item.key === 'smart_lod' && isExtAutoFps);
        const isDisabled = isWinOpen || isSmartLodLocked;

        gEl.classList.toggle('is-sector-disabled', isDisabled);
        gEl.classList.toggle('is-sector-locked-autofps', isSmartLodLocked);

        const spanEl = gEl.querySelector('.radial-sector-label-text');
        if (spanEl) {
            let labelHtml = item.label;
            if (isSmartLodLocked) {
                labelHtml = `SMART LOD<br><span class="text-amber-400 text-[9px] font-sans font-semibold">(AUTOFPS)</span>`;
            }
            spanEl.innerHTML = labelHtml;
            spanEl.className = `radial-sector-label-text text-[10.5px] font-sans font-bold tracking-wider uppercase ${isDisabled ? 'text-slate-500' : 'text-slate-200 group-hover:text-white'}`;
        }
    });
}

function renderFlightOptimizerRadialWheel() {
    const hubEl = document.getElementById('filter-radial-center-hub');
    const svgEl = document.getElementById('filter-radial-svg');
    const backdropEl = document.getElementById('filter-radial-inner-backdrop');
    if (!hubEl || !svgEl) return;

    if (backdropEl) backdropEl.classList.add('hidden'); // Point 13: Hide inner backdrop in flight optimizer!
    renderContextualRadialHub();

    const cx = 310;
    const cy = 310;
    const r_in = 115;  // Point 9: fits around 216px diameter hub (radius 108px + 7px gap)
    const r_out = 255; // Point 9: fits inside 620px viewBox
    const midR = (r_in + r_out) / 2;

    const sectorCount = FLIGHT_OPT_SECTORS.length;
    const sectorAngle = 360 / sectorCount;

    let svgHtml = '';
    FLIGHT_OPT_SECTORS.forEach((item, idx) => {
        const startAngle = -90 - (sectorAngle / 2) + (idx * sectorAngle);
        const endAngle = startAngle + sectorAngle;
        const midAngle = (startAngle + endAngle) / 2;
        const pathD = getAnnularSectorPath(cx, cy, r_in, r_out, startAngle, endAngle, 8.0);

        const rad = (midAngle - 90) * Math.PI / 180;
        const tx = cx + midR * Math.cos(rad);
        const ty = cy + midR * Math.sin(rad);

        // Point 11: Check if window is currently open or locked by external AutoFPS
        const isWinOpen = isFloatingWindowOpen(item.key);
        const isExtAutoFps = isExternalAutoFpsActive();
        const isSmartLodLocked = (!window.IS_LITE && item.key === 'smart_lod' && isExtAutoFps);
        const disabledClass = (isWinOpen || isSmartLodLocked) ? 'is-sector-disabled' : '';
        const lockedClass = isSmartLodLocked ? 'is-sector-locked-autofps' : '';

        let labelHtml = item.label;
        if (isSmartLodLocked) {
            labelHtml = `SMART LOD<br><span class="text-amber-400 text-[9px] font-sans font-semibold">(AUTOFPS)</span>`;
        }
        const proBadgeHtml = window.IS_LITE
            ? `<span class="mt-1 ${LITE_PRO_BADGE_CLASS}">${LITE_PRO_BADGE_INNER}</span>`
            : '';

        svgHtml += `
            <g class="radial-flight-sector animate-sector-bounce ${disabledClass} ${lockedClass} pointer-events-auto cursor-pointer group"
               id="radial-opt-sector-${item.key}"
               style="animation-delay: ${(idx * 0.04).toFixed(2)}s;"
               onclick="handleFlightOptimizerSectorClick('${item.key}')"
               role="button" aria-label="${item.label.replace(/<br>/gi, ' ')}">
                <path class="radial-flight-sector-path" d="${pathD}" />
                <foreignObject x="${(tx - 65).toFixed(1)}" y="${(ty - 32).toFixed(1)}" width="130" height="64" class="pointer-events-none">
                    <div class="w-full h-full flex flex-col items-center justify-center text-center leading-tight px-1">
                        <span class="radial-sector-label-text text-[10.5px] font-sans font-bold tracking-wider uppercase ${(isWinOpen || isSmartLodLocked) ? 'text-slate-500' : 'text-slate-200 group-hover:text-white'}">${labelHtml}</span>
                        ${proBadgeHtml}
                    </div>
                </foreignObject>
            </g>
        `;
    });

    svgEl.innerHTML = svgHtml;
}

function handleFlightOptimizerSectorClick(key) {
    if (window.IS_LITE) {
        if (typeof closeFilterRadialMenu === 'function') closeFilterRadialMenu();
        if (typeof closeAirportRadialMenu === 'function') closeAirportRadialMenu(false);
        showUnlockProModal();
        return;
    }
    const isExtAutoFps = isExternalAutoFpsActive();
    if (key === 'smart_lod' && isExtAutoFps) {
        showToastNotification("Smart LOD locked: MSFS AutoFPS is active in background.", "warning");
        return;
    }
    if (key === 'route') {
        if (typeof closeFilterRadialMenu === 'function') closeFilterRadialMenu();
        if (typeof closeAirportRadialMenu === 'function') closeAirportRadialMenu(false);
    }
    openFloatingWindow(key);
    updateFlightOptimizerRadialSectors();
}

function toggleFilterRadialMenuAtCenter() {
    if (isClassicNavMode()) return;
    if (isFilterRadialOpen) {
        closeFilterRadialMenu();
    } else {
        openFilterRadialMenu(window.innerWidth / 2, (window.innerHeight / 2) - 20);
    }
}

function closeFilterRadialMenu() {
    const menuEl = document.getElementById('filter-radial-menu');
    if (menuEl) {
        menuEl.classList.add('hidden');
        menuEl.classList.remove('animate-filter-radial-open');
    }
    if (filterRadialHoverTimer) {
        clearTimeout(filterRadialHoverTimer);
        filterRadialHoverTimer = null;
    }
    filterRadialTier2Hovered = false;
    isFilterRadialOpen = false;
    filterRadialLastAnimatedCategory = null;
}

function handleFilterRadialCenterClick() {
    if (filterRadialContextMode !== 'hub') {
        selectContextualRadialMode('hub');
    }
}

/**
 * Computes SVG path for an annular sector (pie slice with inner and outer radius)
 * Calculates constant linear gap (gapPx) at both inner and outer edges for perfectly parallel seams
 */
function getAnnularSectorPath(cx, cy, rIn, rOut, startAngleDeg, endAngleDeg, gapPx = 8.0) {
    const halfGapRadIn = (gapPx / 2) / rIn;
    const halfGapRadOut = (gapPx / 2) / rOut;

    const halfGapDegIn = halfGapRadIn * 180 / Math.PI;
    const halfGapDegOut = halfGapRadOut * 180 / Math.PI;

    const startDegIn = startAngleDeg + halfGapDegIn;
    const endDegIn = endAngleDeg - halfGapDegIn;
    const startDegOut = startAngleDeg + halfGapDegOut;
    const endDegOut = endAngleDeg - halfGapDegOut;

    // Convert degrees to radians (0 deg = 12 o'clock / top)
    const a1 = (startDegOut - 90) * Math.PI / 180;
    const a2 = (endDegOut - 90) * Math.PI / 180;
    const a3 = (endDegIn - 90) * Math.PI / 180;
    const a4 = (startDegIn - 90) * Math.PI / 180;

    const x1 = cx + rOut * Math.cos(a1);
    const y1 = cy + rOut * Math.sin(a1);
    const x2 = cx + rOut * Math.cos(a2);
    const y2 = cy + rOut * Math.sin(a2);
    const x3 = cx + rIn * Math.cos(a3);
    const y3 = cy + rIn * Math.sin(a3);
    const x4 = cx + rIn * Math.cos(a4);
    const y4 = cy + rIn * Math.sin(a4);

    const angleDiff = endAngleDeg - startAngleDeg;
    const largeArc = angleDiff > 180 ? 1 : 0;

    return `M ${x1.toFixed(2)} ${y1.toFixed(2)} ` +
           `A ${rOut} ${rOut} 0 ${largeArc} 1 ${x2.toFixed(2)} ${y2.toFixed(2)} ` +
           `L ${x3.toFixed(2)} ${y3.toFixed(2)} ` +
           `A ${rIn} ${rIn} 0 ${largeArc} 0 ${x4.toFixed(2)} ${y4.toFixed(2)} ` +
           `Z`;
}

/**
 * Returns the sub-items for a given category key
 */
function getFilterRadialCategoryItems(categoryKey) {
    if (categoryKey === 'pricing') {
        return [
            { id: 'all', label: t('radial.all_models', 'All Models'), isActive: selectedPricing.size === ALL_PRICING_LIST.length },
            { id: 'Payware', label: t('pricing.payware_plural', 'Payware'), isActive: selectedPricing.has('Payware') },
            { id: 'Freeware / Flightsim.to', label: t('pricing.freeware_plural', 'Freeware'), isActive: selectedPricing.has('Freeware / Flightsim.to') },
            { id: 'Asobo', label: t('pricing.asobo_caps', 'Asobo'), isActive: selectedPricing.has('Asobo') },
            { id: 'Default', label: t('pricing.default_caps', 'Default MSFS'), isActive: selectedPricing.has('Default') }
        ];
    } else if (categoryKey === 'source') {
        return [
            { id: 'all', label: t('radial.all_sources', 'All Sources'), isActive: selectedSources.size === ALL_SOURCES_LIST.length },
            { id: 'Community', label: t('filter.source_community', 'Community'), isActive: selectedSources.has('Community') },
            { id: 'Marketplace', label: t('filter.source_marketplace', 'Marketplace'), isActive: selectedSources.has('Marketplace') },
            { id: 'Official', label: t('filter.source_official', 'Official'), isActive: selectedSources.has('Official') }
        ];
    } else if (categoryKey === 'region') {
        const isAllRegions = (selectedRegions.size === 0 || selectedRegions.size === ALL_REGIONS_LIST.length);
        return [
            { id: 'all', label: t('radial.all_regions', 'All Regions'), isActive: isAllRegions },
            { id: 'weurope', label: t('radial.region_weurope', 'West Europe'), isActive: isAllRegions || selectedRegions.has('weurope') },
            { id: 'eeurope', label: t('radial.region_eeurope', 'East Europe'), isActive: isAllRegions || selectedRegions.has('eeurope') },
            { id: 'namerica', label: t('radial.region_namerica', 'North America'), isActive: isAllRegions || selectedRegions.has('namerica') },
            { id: 'camerica_caribbean', label: t('radial.region_camerica', 'Central America'), isActive: isAllRegions || selectedRegions.has('camerica_caribbean') },
            { id: 'samerica', label: t('radial.region_samerica', 'South America'), isActive: isAllRegions || selectedRegions.has('samerica') },
            { id: 'asia', label: t('radial.region_asia', 'Asia'), isActive: isAllRegions || selectedRegions.has('asia') },
            { id: 'middleeast', label: t('radial.region_middleeast', 'Middle East'), isActive: isAllRegions || selectedRegions.has('middleeast') },
            { id: 'nafrica', label: t('radial.region_nafrica', 'North Africa'), isActive: isAllRegions || selectedRegions.has('nafrica') },
            { id: 'ssafrica', label: t('radial.region_ssafrica', 'Sub-Sahara Africa'), isActive: isAllRegions || selectedRegions.has('ssafrica') },
            { id: 'oceania', label: t('radial.region_oceania', 'Oceania'), isActive: isAllRegions || selectedRegions.has('oceania') },
            { id: 'pacific', label: t('radial.region_pacific', 'Pacific'), isActive: isAllRegions || selectedRegions.has('pacific') }
        ];
    } else if (categoryKey === 'type') {
        return [
            { id: 'all', label: t('radial.all_types', 'All Types'), isActive: selectedTypes.size === ALL_TYPES_LIST.length },
            { id: 'International', label: t('radial.type_intl', 'International'), isActive: selectedTypes.has('International') },
            { id: 'Regional', label: t('radial.type_regional', 'Regional'), isActive: selectedTypes.has('Regional') },
            { id: 'General Aviation', label: t('radial.type_ga', 'General Aviation'), isActive: selectedTypes.has('General Aviation') },
            { id: 'Heli / Water', label: t('radial.type_heli', 'Heli / Water'), isActive: selectedTypes.has('Heli / Water') }
        ];
    } else if (categoryKey === 'gsx') {
        const isAllProfiles = (selectedGsxFilter === 'all');
        return [
            { id: 'all', label: t('radial.all_profiles', 'All Profiles'), isActive: isAllProfiles },
            { id: 'with', label: t('radial.with_gsx', 'With GSX'), isActive: isAllProfiles || selectedGsxFilter === 'with' },
            { id: 'none', label: t('radial.no_profile', 'No Profile'), isActive: isAllProfiles || selectedGsxFilter === 'none' },
            { id: 'audit', label: t('radial.profiles_details', 'Profiles Details'), isActive: isAllProfiles }
        ];
    } else if (categoryKey === 'rating') {
        const createStarHtml = (ratingVal) => {
            const full = Math.floor(ratingVal);
            const hasHalf = (ratingVal % 1 !== 0);
            let s = '<span class="inline-flex items-center justify-center pointer-events-none select-none" style="color: #fbbf24 !important; gap: 2px;">';
            for (let i = 0; i < full; i++) {
                s += '<i class="fa-solid fa-star" style="color: #fbbf24 !important; font-size: 14.5px !important; filter: drop-shadow(0 1.5px 3px rgba(0,0,0,0.85));"></i>';
            }
            if (hasHalf) {
                s += '<i class="fa-solid fa-star-half-stroke" style="color: #fbbf24 !important; font-size: 14.5px !important; filter: drop-shadow(0 1.5px 3px rgba(0,0,0,0.85));"></i>';
            }
            s += '</span>';
            return s;
        };

        const isAllRatings = (!selectedMinRating || selectedMinRating === 0);
        const ratingSteps = [1.0, 1.5, 2.0, 2.5, 3.0, 3.5, 4.0, 4.5, 5.0];

        const ratingItems = [
            {
                id: '0',
                label: t('radial.all_ratings', 'All Ratings'),
                htmlLabel: `<span class="text-[10.5px] font-black tracking-wider uppercase">${t('radial.all_ratings', 'ALL RATINGS')}</span>`,
                isActive: isAllRatings
            }
        ];

        ratingSteps.forEach(val => {
            ratingItems.push({
                id: val.toFixed(1),
                label: `${val.toFixed(1)}★`,
                htmlLabel: createStarHtml(val),
                isActive: isAllRatings || selectedMinRating === val
            });
        });

        return ratingItems;
    }
    return [];
}

/**
 * Formats radial labels on a single line
 */
function formatFilterRadialLabel(label) {
    if (!label) return '';
    if (label.includes('<br>') || label.includes('<span') || label.includes('<b')) {
        return label;
    }
    return escapeHtml(label.trim());
}

/**
 * Computes colors for Tier 2 radial sectors:
 * - When INACTIVE (OFF / éteint): Identical dark gray as the inner wheel sectors.
 * - When ACTIVE (ON / allumé): Proportional blue gradient from dark navy blue (ALL items) to light sky blue (last item).
 */
function getFilterRadialSectorGradientColor(index, totalCount, isActive = false) {
    if (!isActive) {
        return {
            fill: 'rgba(38, 46, 60, 0.82)',
            stroke: 'rgba(148, 163, 184, 0.40)',
            strokeWidth: '1.75px',
            filter: 'drop-shadow(0 4px 12px rgba(0, 0, 0, 0.60))'
        };
    }

    if (totalCount <= 1) {
        return {
            fill: 'rgba(18, 30, 52, 0.95)',
            stroke: 'rgba(56, 189, 248, 0.95)',
            strokeWidth: '2.5px',
            filter: 'drop-shadow(0 0 14px rgba(56, 189, 248, 0.60))'
        };
    }

    const t = Math.max(0, Math.min(1, index / (totalCount - 1)));

    // Start color (t=0): Dark navy blue of "ALL" items (rgb(15, 23, 42))
    // End color (t=1): Luminous light sky blue (rgb(14, 165, 233))
    const rStart = 15, gStart = 23, bStart = 42;
    const rEnd = 14, gEnd = 165, bEnd = 233;

    let r = Math.round(rStart + t * (rEnd - rStart));
    let g = Math.round(gStart + t * (gEnd - gStart));
    let b = Math.round(bStart + t * (bEnd - bStart));

    // Boost vibrancy for active illuminated items
    r = Math.min(255, Math.round(r * 1.10 + 6));
    g = Math.min(255, Math.round(g * 1.10 + 8));
    b = Math.min(255, Math.round(b * 1.08 + 12));

    const fill = `rgba(${r}, ${g}, ${b}, 0.95)`;
    const stroke = 'rgba(56, 189, 248, 0.95)';
    const strokeWidth = '2.5px';
    const filter = 'drop-shadow(0 0 14px rgba(56, 189, 248, 0.60))';

    return { fill, stroke, strokeWidth, filter };
}

/**
 * Renders concentric annular wheel matching Screen 1 (No icons, high readability)
 */
function renderFilterRadialWheel(forceAnimateOuter = false) {
    const hubEl = document.getElementById('filter-radial-center-hub');
    const svgEl = document.getElementById('filter-radial-svg');
    if (!hubEl || !svgEl) return;

    if (!filterRadialActiveCategory) {
        filterRadialActiveCategory = 'pricing';
    }

    const shouldAnimateOuter = forceAnimateOuter || (filterRadialActiveCategory !== filterRadialLastAnimatedCategory);
    filterRadialLastAnimatedCategory = filterRadialActiveCategory;

    renderContextualRadialHub();

    const cx = 310;
    const cy = 310;
    const r1_in = 115;
    const r1_out = 195;
    const r2_in = 203;
    const r2_out = 300;

    // --- TIER 1: INNER ANNULAR RING (6 MAIN CATEGORIES) ---
    let innerSvgHtml = '';
    FILTER_RADIAL_CATEGORIES.forEach((cat, idx) => {
        const startAngle = -120 + (idx * 60);
        const endAngle = startAngle + 60;
        const midAngle = (startAngle + endAngle) / 2;
        const pathD = getAnnularSectorPath(cx, cy, r1_in, r1_out, startAngle, endAngle, 8.0);

        const midR = (r1_in + r1_out) / 2;
        const rad = (midAngle - 90) * Math.PI / 180;
        const tx = cx + midR * Math.cos(rad);
        const ty = cy + midR * Math.sin(rad);

        const isCatActive = (cat.key === filterRadialActiveCategory);
        const summary = cat.getSummary();
        const summaryHtml = cat.getHtmlSummary ? cat.getHtmlSummary() : escapeHtml(summary);
        const formattedCatLabel = formatFilterRadialLabel(cat.label);
        const catAriaLabel = escapeHtml((cat.label || '').replace(/<br\s*\/?>/gi, ' '));

        innerSvgHtml += `
            <g class="radial-filter-sector ${isCatActive ? 'is-category-active' : ''} pointer-events-auto cursor-pointer group"
               onclick="handleFilterRadialCategoryClick('${cat.key}')"
               onmouseenter="handleFilterRadialCategoryHover('${cat.key}')"
               onmouseleave="handleFilterRadialCategoryMouseLeave()"
               role="button" aria-label="${catAriaLabel}">
                <path class="radial-filter-sector-path" d="${pathD}" />
                <foreignObject x="${(tx - 58).toFixed(1)}" y="${(ty - 26).toFixed(1)}" width="116" height="52" class="pointer-events-none">
                    <div class="w-full h-full flex flex-col items-center justify-center text-center leading-none px-1">
                        <span class="text-[9.5px] font-black tracking-wider uppercase leading-tight text-center ${isCatActive ? 'text-white font-extrabold' : 'text-slate-200 group-hover:text-white'}">${formattedCatLabel}</span>
                        <span class="text-[10px] font-sans font-bold ${isCatActive ? 'text-white' : 'text-sky-400'} truncate max-w-[108px] mt-1">${summaryHtml}</span>
                    </div>
                </foreignObject>
            </g>
        `;
    });

    // --- TIER 2: OUTER ANNULAR ARC (SUB-FILTER ITEMS OF ACTIVE CATEGORY) ---
    let outerSvgHtml = '';
    const items = getFilterRadialCategoryItems(filterRadialActiveCategory);
    if (items && items.length > 0) {
        const catIdx = FILTER_RADIAL_CATEGORIES.findIndex(c => c.key === filterRadialActiveCategory);
        const catMidAngle = -90 + (catIdx * 60);

        const itemCount = items.length;
        let itemSpan = 360 / itemCount;
        let startAngle = -90;

        if (filterRadialActiveCategory !== 'region') {
            // Fan out symmetrically centered on the active category (Screen 1 style)
            itemSpan = itemCount <= 4 ? 42 : (itemCount === 5 ? 38 : (itemCount <= 6 ? 34 : 29.5));
            const totalSpan = itemCount * itemSpan;
            startAngle = catMidAngle - (totalSpan / 2);
        }

        const animClass = shouldAnimateOuter ? 'animate-sector-bounce' : '';
        const step = itemCount > 8 ? 0.022 : 0.035;

        items.forEach((item, idx) => {
            const aStart = startAngle + (idx * itemSpan);
            const aEnd = aStart + itemSpan;
            const midAngle = (aStart + aEnd) / 2;
            const pathD = getAnnularSectorPath(cx, cy, r2_in, r2_out, aStart, aEnd, 8.0);

            const midR2 = (r2_in + r2_out) / 2;
            const rad = (midAngle - 90) * Math.PI / 180;
            const tx = cx + midR2 * Math.cos(rad);
            const ty = cy + midR2 * Math.sin(rad);

            const isActive = !!item.isActive;
            const delayStyle = shouldAnimateOuter ? `style="animation-delay: ${(idx * step).toFixed(3)}s;"` : '';

            const isAll = (item.id === 'all' || item.id === '0' || (item.label && item.label.toLowerCase().startsWith('all')));
            let specificClass = '';
            let inlinePathStyle = '';

            if (filterRadialActiveCategory === 'pricing') {
                if (isAll) specificClass = 'radial-sector-all';
                else if (item.id === 'Payware') specificClass = 'radial-sector-payware';
                else if (item.id === 'Freeware / Flightsim.to' || item.id === 'Freeware') specificClass = 'radial-sector-freeware';
                else if (item.id === 'Asobo') specificClass = 'radial-sector-asobo';
                else if (item.id === 'Default') specificClass = 'radial-sector-default';
            } else {
                // Proportional Blue Gradient from dark navy blue (ALL) to light sky blue
                const grad = getFilterRadialSectorGradientColor(idx, itemCount, isActive);
                inlinePathStyle = `style="fill: ${grad.fill}; stroke: ${grad.stroke}; stroke-width: ${grad.strokeWidth}; ${grad.filter ? `filter: ${grad.filter};` : ''}"`;
            }

            const formattedItemLabel = item.htmlLabel || formatFilterRadialLabel(item.label);
            const isRatingCategory = (filterRadialActiveCategory === 'rating');
            const foW = isRatingCategory ? 122 : 112;
            const foH = isRatingCategory ? 46 : 40;
            const foX = (tx - (foW / 2)).toFixed(1);
            const foY = (ty - (foH / 2)).toFixed(1);

            const itemTip = isAll ? t('radial.click_all_tip', 'Click to show all') : t('radial.click_solo_tip', 'Click: Solo | Shift+Click: Multi-select');

            outerSvgHtml += `
                <g class="radial-filter-sector radial-filter-tier2-sector ${animClass} ${specificClass} ${isActive ? 'is-item-active' : ''} pointer-events-auto cursor-pointer group"
                   ${delayStyle}
                   onmouseenter="handleFilterRadialTier2MouseEnter()"
                   onmouseleave="handleFilterRadialTier2MouseLeave()"
                   onclick="handleFilterRadialSubItemClick('${filterRadialActiveCategory}', '${escapeJsStr(item.id)}', event)"
                   title="${escapeHtml(item.label)} (${itemTip})"
                   role="button" aria-label="${escapeHtml(item.label)}">
                    <path class="radial-filter-sector-path" ${inlinePathStyle} d="${pathD}" />
                    <foreignObject x="${foX}" y="${foY}" width="${foW}" height="${foH}" class="pointer-events-none">
                        <div class="w-full h-full flex items-center justify-center text-center px-1">
                            <span class="${isRatingCategory ? '' : 'text-[9.5px] font-bold tracking-tight uppercase leading-tight'} inline-flex items-center justify-center text-center ${isActive ? 'text-white font-extrabold' : 'text-slate-200 group-hover:text-white'}">${formattedItemLabel}</span>
                        </div>
                    </foreignObject>
                </g>
            `;
        });
    }

    svgEl.innerHTML = innerSvgHtml + outerSvgHtml;
}

function handleFilterRadialTier2MouseEnter() {
    filterRadialTier2Hovered = true;
    if (filterRadialHoverTimer) {
        clearTimeout(filterRadialHoverTimer);
        filterRadialHoverTimer = null;
    }
}

function handleFilterRadialTier2MouseLeave() {
    filterRadialTier2Hovered = false;
}

function handleFilterRadialCategoryClick(categoryKey) {
    if (filterRadialHoverTimer) {
        clearTimeout(filterRadialHoverTimer);
        filterRadialHoverTimer = null;
    }
    filterRadialTier2Hovered = false;
    if (filterRadialActiveCategory !== categoryKey) {
        filterRadialActiveCategory = categoryKey;
        renderFilterRadialWheel(true);
    }
}

function handleFilterRadialCategoryHover(categoryKey) {
    if (filterRadialTier2Hovered) return;
    if (filterRadialActiveCategory === categoryKey) {
        if (filterRadialHoverTimer) {
            clearTimeout(filterRadialHoverTimer);
            filterRadialHoverTimer = null;
        }
        return;
    }

    if (filterRadialHoverTimer) {
        clearTimeout(filterRadialHoverTimer);
        filterRadialHoverTimer = null;
    }

    // Dwell delay: prevents switching category when cursor simply brushes across an option
    filterRadialHoverTimer = setTimeout(() => {
        filterRadialHoverTimer = null;
        if (!filterRadialTier2Hovered && filterRadialActiveCategory !== categoryKey) {
            filterRadialActiveCategory = categoryKey;
            renderFilterRadialWheel(true);
        }
    }, 180);
}

function handleFilterRadialCategoryMouseLeave() {
    if (filterRadialHoverTimer) {
        clearTimeout(filterRadialHoverTimer);
        filterRadialHoverTimer = null;
    }
}

function handleFilterRadialSubItemClick(categoryKey, itemId, event) {
    const isCumulative = !!(event && (event.shiftKey || event.ctrlKey || event.metaKey));
    if (categoryKey === 'pricing') {
        togglePricingFilter(itemId, isCumulative);
    } else if (categoryKey === 'source') {
        toggleSourceFilter(itemId, isCumulative);
    } else if (categoryKey === 'region') {
        toggleRegionFilter(itemId, isCumulative);
    } else if (categoryKey === 'type') {
        toggleTypeFilter(itemId, isCumulative);
    } else if (categoryKey === 'gsx') {
        if (itemId === 'audit') {
            closeFilterRadialMenu();
            if (typeof openGsxAuditModal === 'function') openGsxAuditModal();
            return;
        }
        toggleGsxFilter(itemId);
    } else if (categoryKey === 'rating') {
        const val = parseFloat(itemId);
        if (val === 0 || isNaN(val)) {
            resetMinRatingFilter();
        } else {
            if (selectedMinRating === val) {
                selectedMinRating = 0;
            } else {
                selectedMinRating = val;
            }
            renderFilterStarWidget(selectedMinRating);
            filterAirports();
        }
    }

    if (isFilterRadialOpen) {
        renderFilterRadialWheel(false);
    }
}

function updateFilterRadialUI() {
    if (!isFilterRadialOpen) return;
    renderFilterRadialWheel(false);
}

async function checkStartupChanges() {
    if (!window.pywebview || !window.pywebview.api) return;
    try {
        let delta = null;
        if (window.pywebview.api.get_startup_delta) {
            const resStr = await window.pywebview.api.get_startup_delta();
            if (resStr) {
                try {
                    delta = JSON.parse(resStr);
                } catch (e) {}
            }
        }
        console.log("Startup delta check:", delta);

        pendingScanDelta = delta;
        pendingScanIsStartup = true;

        // PRIORITY 1: Check if any scenery conflicts exist!
        const conflictAirports = allAirportsData.filter(a => a.has_conflict);
        if (conflictAirports.length > 0) {
            let hasSeenOnboarding = false;
            if (window.onboardingTour && typeof window.onboardingTour.isOnboardingCompleted === 'function') {
                hasSeenOnboarding = await window.onboardingTour.isOnboardingCompleted();
            } else if (window.pywebview && window.pywebview.api && window.pywebview.api.is_onboarding_completed) {
                try {
                    const res = JSON.parse(await window.pywebview.api.is_onboarding_completed());
                    hasSeenOnboarding = Boolean(res && res.completed);
                } catch (e) {}
            } else {
                hasSeenOnboarding = (localStorage.getItem('sceneryx_has_seen_onboarding') === 'true');
            }

            const isTourRunning = (document.body && document.body.classList.contains('tour-active')) ||
                                  (window.onboardingTour && window.onboardingTour.isOpen);

            if (!hasSeenOnboarding || isTourRunning) {
                console.log("[ConflictModal] Postponing startup conflict modal until onboarding tour completes or is skipped.");
                pendingConflictModal = true;
                pendingConflictModalIndex = 0;
                return;
            }

            openConflictModal(0);
            return;
        }

        // Check if startup delta detected new or modified sceneries (GSX audit already done on splash screen!)
        if (pendingScanDelta && (pendingScanDelta.total_changes || 0) > 0) {
            const d = pendingScanDelta;
            pendingScanDelta = null;
            pendingScanIsStartup = false;
            displayScanResults(d, true);
        }
    } catch (e) {
        console.warn("Could not check startup delta:", e);
    }
}

async function startGsxScanPhase(isStartup = false) {
    const modal = document.getElementById('rescan-modal');
    const phaseScanning = document.getElementById('rescan-phase-scanning');
    const phaseGsx = document.getElementById('rescan-phase-gsx');
    const phaseResult = document.getElementById('rescan-phase-result');
    const bar = document.getElementById('rescan-gsx-progress-bar');
    const pct = document.getElementById('rescan-gsx-percent-text');
    const detail = document.getElementById('rescan-gsx-detail-text');

    if (modal && phaseGsx) {
        const backdrop = document.getElementById('rescan-backdrop');
        if (backdrop) backdrop.classList.remove('hidden');
        if (phaseScanning) phaseScanning.classList.add('hidden');
        if (phaseResult) phaseResult.classList.add('hidden');
        phaseGsx.classList.remove('hidden');
        if (bar) bar.style.width = '20%';
        if (pct) pct.innerText = '20%';
        if (detail) detail.innerText = 'Scanning GSX profile files in %APPDATA%\\Virtuali\\GSX\\MSFS...';
        modal.classList.remove('hidden');
        if (window.windowManager) {
            window.windowManager.centerModal(modal);
        } else {
            modal.style.left = '50%';
            modal.style.top = '50%';
            modal.style.transform = 'translate(-50%, -50%)';
        }
    }

    try {
        if (bar) bar.style.width = '55%';
        if (pct) pct.innerText = '55%';

        let auditData = null;
        if (window.pywebview && window.pywebview.api && window.pywebview.api.scan_gsx_audit) {
            const raw = await window.pywebview.api.scan_gsx_audit();
            const parsed = typeof raw === 'string' ? JSON.parse(raw) : raw;
            if (parsed && parsed.status === 'ok') {
                auditData = parsed.data;
            }
        }

        window.gsxAuditData = auditData;
        const s = auditData && auditData.summary ? auditData.summary : null;
        const totalIssues = s ? ((s.duplicate || 0) + (s.mismatch || 0) + (s.orphan || 0)) : 0;
        updateGsxSidebarBadge();

        if (bar) bar.style.width = '100%';
        if (pct) pct.innerText = '100%';
        if (detail && s) {
            detail.innerText = `Scan complete: ${s.total_files} profiles (${s.matched} matched, ${s.duplicate} duplicates, ${s.mismatch} mismatches, ${s.orphan} orphans).`;
        } else {
            if (detail) detail.innerText = 'GSX profiles scan complete.';
        }

        // Brief smooth display of the completed GSX scan
        await new Promise(r => setTimeout(r, 650));

        if (totalIssues > 0) {
            closeRescanModal();
            openGsxAuditModal('ALL');
        } else if (pendingScanDelta && (pendingScanDelta.total_changes || 0) > 0) {
            const d = pendingScanDelta;
            const startup = pendingScanIsStartup;
            pendingScanDelta = null;
            pendingScanIsStartup = false;
            displayScanResults(d, startup);
        } else {
            closeRescanModal();
        }
    } catch (err) {
        console.error("GSX scan phase error:", err);
        closeRescanModal();
    }
}

function getScanItemCategoryColor(item) {
    if (!item) return 'text-cyan-400';
    const rawType = (item.type || item.pricing_type || '').toLowerCase();
    if (rawType.includes('payware')) return 'text-purple-400';
    if (rawType.includes('asobo')) return 'text-amber-400';
    if (rawType.includes('default')) return 'text-sky-400';
    if (rawType.includes('freeware')) return 'text-cyan-400';

    const apMatch = item.icao ? getAirportByIcao(item.icao) : null;
    if (apMatch) {
        const cat = getAirportCategory(apMatch);
        if (cat === 'PAYWARE') return 'text-purple-400';
        if (cat === 'ASOBO') return 'text-amber-400';
        if (cat === 'DEFAULT') return 'text-sky-400';
        if (cat === 'FREEWARE') return 'text-cyan-400';
    }

    const vendor = (item.vendor || '').toLowerCase();
    if (vendor && !['unknown', 'flightsim.to', 'freeware'].includes(vendor)) {
        return 'text-purple-400';
    }

    return 'text-cyan-400';
}

function displayScanResults(delta, isStartup = false) {
    if (!delta) return;

    // PRIORITY 1: Check if any scenery conflicts exist!
    // The user wants conflicts to be resolved FIRST before showing newly detected addons!
    const conflictAirports = allAirportsData.filter(a => a.has_conflict);
    if (conflictAirports.length > 0) {
        pendingScanDelta = delta;
        pendingScanIsStartup = isStartup;
        closeRescanModal();
        openConflictModal(0);
        return;
    }

    const totalChanges = delta.total_changes || 0;
    const addedList = delta.added || [];
    const removedList = delta.removed || [];

    // On startup, if no changes were detected, DO NOT show the modal
    if (isStartup && totalChanges === 0) {
        return;
    }

    const modal = document.getElementById('rescan-modal');
    const phaseScanning = document.getElementById('rescan-phase-scanning');
    const phaseGsx = document.getElementById('rescan-phase-gsx');
    const phaseResult = document.getElementById('rescan-phase-result');
    const titleEl = document.getElementById('rescan-result-title');
    const msgEl = document.getElementById('rescan-result-message');
    const listCont = document.getElementById('rescan-new-items-container');

    if (modal) {
        const backdrop = document.getElementById('rescan-backdrop');
        if (backdrop) backdrop.classList.remove('hidden');
        if (phaseScanning) phaseScanning.classList.add('hidden');
        if (phaseGsx) phaseGsx.classList.add('hidden');
        if (phaseResult) phaseResult.classList.remove('hidden');
        modal.classList.remove('hidden');
        if (window.windowManager) {
            window.windowManager.centerModal(modal);
        } else {
            modal.style.left = '50%';
            modal.style.top = '50%';
            modal.style.transform = 'translate(-50%, -50%)';
        }
    }

    if (totalChanges > 0) {
        if (titleEl) {
            titleEl.innerHTML = `<span>${t('rescan.changes_detected', 'Library Changes Detected')}</span>`;
        }

        if (msgEl) {
            msgEl.innerText = t('rescan.changes_summary', 'SceneryX detected changes in your library folders:');
        }

        if (listCont) {
            const htmlItems = [];

            const addedSceneries = addedList.filter(item => item.kind !== 'gsx');
            const addedGsx = addedList.filter(item => item.kind === 'gsx');
            const removedSceneries = removedList.filter(item => item.kind !== 'gsx');
            const removedGsx = removedList.filter(item => item.kind === 'gsx');

            const totalSceneries = addedSceneries.length + removedSceneries.length;
            const totalGsx = addedGsx.length + removedGsx.length;

            const renderSceneryCard = (item, isAdded) => {
                const displayName = item.name || item.icao;
                const pkgName = item.folder_name || '';
                const icaoColor = getScanItemCategoryColor(item);
                const statusBadge = isAdded
                    ? `<span class="text-xs font-bold px-3 py-1 rounded-full bg-emerald-600 text-white">${t('rescan.status_added', 'Added')}</span>`
                    : `<span class="text-xs font-bold px-3 py-1 rounded-full bg-rose-600 text-white">${t('rescan.status_removed', 'Removed')}</span>`;
                const clickAttr = isAdded
                    ? `onclick="closeRescanModal(); selectAirport('${item.icao}')" title="${t('general.view_on_map', 'Click to view on map')}" class="p-3 rounded-xl bg-slate-900 border border-slate-800 hover:bg-slate-800/80 flex items-center justify-between gap-4 transition-colors cursor-pointer"`
                    : `class="p-3 rounded-xl bg-slate-900 border border-slate-800 flex items-center justify-between gap-4"`;

                return `
                    <div ${clickAttr}>
                        <div class="flex items-center gap-3.5 min-w-0 flex-1">
                            <span class="font-mono font-black text-lg sm:text-xl tracking-tight shrink-0 ${icaoColor}">
                                ${item.icao}
                            </span>
                            <div class="min-w-0 flex-1">
                                <div class="text-sm font-bold text-white truncate">
                                    ${displayName}
                                </div>
                                <div class="text-xs font-mono text-slate-400 truncate mt-0.5">
                                    ${pkgName}
                                </div>
                            </div>
                        </div>
                        <div class="flex items-center gap-2 shrink-0">
                            ${statusBadge}
                        </div>
                    </div>
                `;
            };

            const renderGsxCard = (item, isAdded) => {
                const displayName = item.name || item.icao;
                const iniName = item.folder_name || '';
                const statusBadge = isAdded
                    ? `<span class="text-xs font-bold px-3 py-1 rounded-full bg-emerald-600 text-white">${t('rescan.status_added', 'Added')}</span>`
                    : `<span class="text-xs font-bold px-3 py-1 rounded-full bg-rose-600 text-white">${t('rescan.status_removed', 'Removed')}</span>`;
                const clickAttr = isAdded
                    ? `onclick="closeRescanModal(); selectAirport('${item.icao}')" title="${t('general.view_on_map', 'Click to view on map')}" class="p-3 rounded-xl bg-slate-900 border border-purple-900/40 hover:bg-slate-800/80 hover:border-purple-700/60 flex items-center justify-between gap-4 transition-colors cursor-pointer"`
                    : `class="p-3 rounded-xl bg-slate-900 border border-slate-800 flex items-center justify-between gap-4"`;

                return `
                    <div ${clickAttr}>
                        <div class="flex items-center gap-3.5 min-w-0 flex-1">
                            <span class="font-mono font-black text-lg sm:text-xl tracking-tight shrink-0 text-purple-400">
                                ${item.icao}
                            </span>
                            <div class="min-w-0 flex-1">
                                <div class="text-sm font-bold text-white truncate">
                                    ${displayName}
                                </div>
                                <div class="text-xs font-mono text-slate-400 truncate mt-0.5">
                                    ${iniName}
                                </div>
                            </div>
                        </div>
                        <div class="flex items-center gap-2 shrink-0">
                            <span class="text-xs font-bold px-3 py-1 rounded-full bg-purple-900 text-purple-200 border border-purple-700">${t('rescan.gsx_profile_pill', 'GSX Profile')}</span>
                            ${statusBadge}
                        </div>
                    </div>
                `;
            };

            // 1. Scenery Packages Section
            if (totalSceneries > 0) {
                htmlItems.push(`
                    <div class="flex items-center justify-between pb-1.5 pt-1 border-b border-slate-800/80 mb-2">
                        <div class="text-xs font-bold uppercase tracking-wider text-slate-300">
                            <span>${t('rescan.section_sceneries', 'Scenery Packages')}</span>
                        </div>
                        <span class="text-xs font-mono font-bold text-slate-400">${totalSceneries}</span>
                    </div>
                    <div class="space-y-2 mb-4">
                        ${addedSceneries.map(item => renderSceneryCard(item, true)).join('')}
                        ${removedSceneries.map(item => renderSceneryCard(item, false)).join('')}
                    </div>
                `);
            }

            // 2. GSX Profiles Section
            if (totalGsx > 0) {
                htmlItems.push(`
                    <div class="flex items-center justify-between pb-1.5 pt-1 border-b border-slate-800/80 mb-2">
                        <div class="text-xs font-bold uppercase tracking-wider text-purple-300">
                            <span>${t('rescan.section_gsx', 'GSX Profiles')}</span>
                        </div>
                        <span class="text-xs font-mono font-bold text-slate-400">${totalGsx}</span>
                    </div>
                    <div class="space-y-2">
                        ${addedGsx.map(item => renderGsxCard(item, true)).join('')}
                        ${removedGsx.map(item => renderGsxCard(item, false)).join('')}
                    </div>
                `);
            }

            listCont.innerHTML = htmlItems.join('');
            listCont.classList.remove('hidden');
        }
    } else {
        // No changes detected (manual rescan)
        if (titleEl) {
            titleEl.innerHTML = `<span>${t('rescan.completed_title', 'Scan Completed')}</span>`;
        }
        if (msgEl) {
            msgEl.innerText = t('rescan.no_changes', 'No changes detected. Your library is up to date.');
        }
        if (listCont) {
            listCont.classList.add('hidden');
            listCont.innerHTML = '';
        }
    }
}

async function rescanMSFS() {
    const icon = document.getElementById('rescan-icon');
    if (icon) icon.classList.add('fa-spin');

    const backdrop = document.getElementById('rescan-backdrop');
    if (backdrop) backdrop.classList.remove('hidden');

    const modal = document.getElementById('rescan-modal');
    const phaseScanning = document.getElementById('rescan-phase-scanning');
    const phaseResult = document.getElementById('rescan-phase-result');
    const progressBar = document.getElementById('rescan-progress-bar');
    const percentText = document.getElementById('rescan-percent-text');
    const detailText = document.getElementById('rescan-detail-text');

    if (modal) {
        if (phaseScanning) phaseScanning.classList.remove('hidden');
        if (phaseResult) phaseResult.classList.add('hidden');
        if (progressBar) progressBar.style.width = '10%';
        if (percentText) percentText.innerText = '10%';
        if (detailText) detailText.innerText = t('rescan.sub_checking', 'Checking Community & OneStore folders...');
        modal.classList.remove('hidden');
        if (window.windowManager) {
            window.windowManager.centerModal(modal);
            window.windowManager.bringToFront(modal);
        } else {
            modal.style.left = '50%';
            modal.style.top = '50%';
            modal.style.transform = 'translate(-50%, -50%)';
        }
    }

    // Force browser repaint
    await new Promise(r => setTimeout(r, 60));

    let currentProgress = 10;
    const progressTimer = setInterval(() => {
        if (!progressBar) return;
        if (currentProgress < 85) {
            currentProgress += 10;
            progressBar.style.width = currentProgress + '%';
            if (percentText) percentText.innerText = currentProgress + '%';
            if (currentProgress === 30 && detailText) detailText.innerText = t('rescan.step_manifests', 'Scanning package manifests & sceneries...');
            if (currentProgress === 60 && detailText) detailText.innerText = t('rescan.step_bgl', 'Analyzing runway & airport BGL files...');
            if (currentProgress === 80 && detailText) detailText.innerText = t('rescan.step_indexing', 'Indexing custom addons & GSX profiles...');
        }
    }, 100);

    try {
        let scanResult;
        if (window.pywebview) {
            const dataStr = await window.pywebview.api.rescan();
            scanResult = JSON.parse(dataStr);
        } else {
            const resp = await fetch('/api/rescan', { method: 'POST' });
            scanResult = await resp.json();
        }

        clearInterval(progressTimer);

        let newAirports = [];
        let delta = null;

        if (Array.isArray(scanResult)) {
            newAirports = scanResult;
        } else if (scanResult && scanResult.airports) {
            newAirports = scanResult.airports;
            delta = scanResult.delta;
        }

        allAirportsData = newAirports;

        // Advance to 100% smoothly
        if (progressBar) progressBar.style.width = '100%';
        if (percentText) percentText.innerText = '100%';
        if (detailText) detailText.innerText = t('rescan.complete', 'Scan Complete');

        // Apply ratings & search index
        allAirportsData.forEach(ap => {
            if (userRatingsMap[ap.icao] !== undefined) {
                ap.rating = userRatingsMap[ap.icao];
            } else {
                ap.rating = ap.rating || 0;
            }
            ap._searchKey = buildAirportSearchKey(ap);
        });

        updateStats(allAirportsData);
        filterAirports();

        if (selectedAirport) {
            const updatedAp = getAirportByIcao(selectedAirport.icao);
            if (updatedAp) showAirportDetails(updatedAp);
        }

        // Brief pause at 100% before displaying result
        await new Promise(r => setTimeout(r, 350));

        // Check conflicts or proceed to GSX phase
        const conflictAirports = allAirportsData.filter(a => a.has_conflict);
        if (conflictAirports.length > 0) {
            pendingScanDelta = delta;
            pendingScanIsStartup = false;
            closeRescanModal();
            openConflictModal(0);
        } else {
            pendingScanDelta = delta;
            pendingScanIsStartup = false;
            await startGsxScanPhase(false);
        }

    } catch (err) {
        console.error("Rescan error:", err);
        closeRescanModal();
    } finally {
        clearInterval(progressTimer);
        if (icon) icon.classList.remove('fa-spin');
    }
}

async function runInitialFirstLaunchScan() {
    const backdrop = document.getElementById('rescan-backdrop');
    if (backdrop) backdrop.classList.remove('hidden');

    const modal = document.getElementById('rescan-modal');
    const phaseScanning = document.getElementById('rescan-phase-scanning');
    const phaseResult = document.getElementById('rescan-phase-result');
    const progressBar = document.getElementById('rescan-progress-bar');
    const percentText = document.getElementById('rescan-percent-text');
    const detailText = document.getElementById('rescan-detail-text');
    const statusSub = document.getElementById('rescan-status-sub');
    const titleEl = document.querySelector('#rescan-phase-scanning h4') || document.querySelector('#rescan-phase-scanning h3');

    if (modal) {
        if (titleEl) titleEl.innerText = t('rescan.first_launch_title', 'First Launch - Indexing Library');
        if (statusSub) statusSub.innerText = t('rescan.first_launch_sub', 'Building your initial scenery index from MSFS packages...');
        if (phaseScanning) phaseScanning.classList.remove('hidden');
        if (phaseResult) phaseResult.classList.add('hidden');
        if (progressBar) progressBar.style.width = '15%';
        if (percentText) percentText.innerText = '15%';
        if (detailText) detailText.innerText = t('rescan.sub_checking', 'Checking Community & OneStore folders...');
        modal.classList.remove('hidden');
        if (window.windowManager) {
            window.windowManager.centerModal(modal);
            window.windowManager.bringToFront(modal);
        } else {
            modal.style.left = '50%';
            modal.style.top = '50%';
            modal.style.transform = 'translate(-50%, -50%)';
        }
    }

    // Force browser repaint
    await new Promise(r => setTimeout(r, 60));

    let currentProgress = 15;
    const progressTimer = setInterval(() => {
        if (!progressBar) return;
        if (currentProgress < 85) {
            currentProgress += 10;
            progressBar.style.width = currentProgress + '%';
            if (percentText) percentText.innerText = currentProgress + '%';
            if (currentProgress === 35 && detailText) detailText.innerText = t('rescan.step_manifests', 'Scanning package manifests & sceneries...');
            if (currentProgress === 65 && detailText) detailText.innerText = t('rescan.step_bgl', 'Analyzing runway & airport BGL files...');
            if (currentProgress === 85 && detailText) detailText.innerText = t('rescan.step_indexing', 'Indexing custom addons & GSX profiles...');
        }
    }, 120);

    try {
        let scanResult;
        if (window.pywebview && window.pywebview.api && window.pywebview.api.initial_scan) {
            const dataStr = await window.pywebview.api.initial_scan();
            scanResult = JSON.parse(dataStr);
        } else if (window.pywebview && window.pywebview.api && window.pywebview.api.rescan) {
            const dataStr = await window.pywebview.api.rescan();
            scanResult = JSON.parse(dataStr);
        } else {
            const resp = await fetch('/api/rescan', { method: 'POST' });
            scanResult = await resp.json();
        }

        clearInterval(progressTimer);

        let newAirports = [];
        if (Array.isArray(scanResult)) {
            newAirports = scanResult;
        } else if (scanResult && scanResult.airports) {
            newAirports = scanResult.airports;
        }

        allAirportsData = newAirports;

        // Guarantee historic airports (such as Berlin-Tegel EDDT) exist natively in allAirportsData
        if (typeof HISTORIC_AIRPORTS !== 'undefined' && Array.isArray(allAirportsData) && allAirportsData.length > 0) {
            for (const [hIcao, h] of Object.entries(HISTORIC_AIRPORTS)) {
                if (!allAirportsData.some(a => a.icao === hIcao)) {
                    allAirportsData.push({
                        icao: hIcao,
                        ident: hIcao,
                        name: h.name,
                        city: h.city,
                        country: h.country || 'DE',
                        lat: h.lat,
                        lon: h.lon,
                        elevation: h.elevation || 122,
                        type: h.type || 'large_airport',
                        english_type: h.english_type || 'International',
                        iata: h.iata || '',
                        pricing_type: 'Default',
                        is_default: true,
                        vendor: 'Microsoft Flight Simulator (Default)',
                        package_name: `msfs-default-${hIcao.toLowerCase()}`,
                        source_folder: 'MSFS - Default Procedural',
                        match_source: 'Default MSFS Procedural',
                        all_sources: [{
                            folder_name: `msfs-default-${hIcao.toLowerCase()}`,
                            package_path: '',
                            source_folder: 'MSFS - Default Procedural',
                            match_source: 'Default MSFS Procedural',
                            vendor: 'Microsoft Flight Simulator (Default)',
                            pricing_type: 'Default',
                            is_payware: false,
                            is_asobo_official: false,
                            is_default: true,
                            is_disabled: false,
                            is_addon: false,
                            is_fix_patch: false,
                            version: '',
                            size_str: 'Default'
                        }],
                        is_disabled: false,
                        has_conflict: false,
                        conflict_count: 1,
                        rating: 0.0,
                        operating_airlines: ['Air Berlin', 'Lufthansa', 'Eurowings', 'Germania', 'EasyJet'],
                        routes: {},
                        runways: [
                            { id: '08L/26R', length_ft: 7966, length_m: 2428, width_ft: 151, width_m: 46, surface: 'Asphalt', lighted: true, closed: false },
                            { id: '08R/26L', length_ft: 9918, length_m: 3023, width_ft: 151, width_m: 46, surface: 'Asphalt', lighted: true, closed: false }
                        ]
                    });
                }
            }
            isAirportsIndexDirty = true;
        }

        if (progressBar) progressBar.style.width = '100%';
        if (percentText) percentText.innerText = '100%';
        if (detailText) detailText.innerText = t('rescan.complete', 'Scan Complete');

        // Apply ratings & search index
        allAirportsData.forEach(ap => {
            if (userRatingsMap[ap.icao] !== undefined) {
                ap.rating = userRatingsMap[ap.icao];
            } else {
                ap.rating = ap.rating || 0;
            }
            ap._searchKey = buildAirportSearchKey(ap);
        });

        if (window.pywebview && window.pywebview.api && window.pywebview.api.scan_gsx_audit) {
            try {
                const raw = await window.pywebview.api.scan_gsx_audit();
                const parsed = typeof raw === 'string' ? JSON.parse(raw) : raw;
                if (parsed && parsed.status === 'ok') {
                    window.gsxAuditData = parsed.data;
                }
            } catch (ge) {
                console.warn("GSX initial audit error:", ge);
            }
            updateGsxSidebarBadge();
        }

        rebuildAirportsByIcaoIndex();
        updateStats(allAirportsData);
        updateFilterUI();
        filterAirports();
        applyStartupCameraSettings();

        // Brief pause at 100%
        await new Promise(r => setTimeout(r, 600));

        // Switch to result phase to welcome user
        if (phaseScanning) phaseScanning.classList.add('hidden');
        if (phaseResult) phaseResult.classList.remove('hidden');

        const resultTitle = document.getElementById('rescan-result-title');
        const resultMsg = document.getElementById('rescan-result-message');
        const listCont = document.getElementById('rescan-new-items-container');

        if (resultTitle) {
            resultTitle.innerHTML = `<span class="font-bold text-slate-100 text-sm">${t('rescan.first_launch_complete', 'Library Initialized!')}</span>`;
        }
        if (resultMsg) {
            const customCount = allAirportsData.filter(a => a.pricing_type !== 'Default').length;
            resultMsg.innerHTML = `<span class="text-slate-100 font-bold">${allAirportsData.length}</span> ${t('general.airports', 'airports indexed')} (<span class="text-slate-100 font-bold">${customCount}</span> ${t('general.custom_addons', 'custom add-ons & GSX profiles')}). ${t('general.welcome', 'Welcome to SceneryX!')}`;
        }
        if (listCont) {
            listCont.classList.add('hidden');
            listCont.innerHTML = '';
        }

    } catch (err) {
        console.error("Initial scan error:", err);
        closeRescanModal();
    } finally {
        clearInterval(progressTimer);
    }
}

