function handleGsxDragOver(e) {
    e.preventDefault();
    e.stopPropagation();
    const container = document.getElementById('drawer-gsx-card');
    if (container) {
        container.classList.add('border-cyan-500', 'bg-cyan-500/10');
    }
}

function handleGsxDragLeave(e) {
    e.preventDefault();
    e.stopPropagation();
    const container = document.getElementById('drawer-gsx-card');
    if (container) {
        container.classList.remove('border-cyan-500', 'bg-cyan-500/10');
    }
}

async function handleGsxDrop(e) {
    e.preventDefault();
    e.stopPropagation();

    const container = document.getElementById('drawer-gsx-card');
    if (container) {
        container.classList.remove('border-cyan-500', 'bg-cyan-500/10');
    }

    if (!e.dataTransfer || !e.dataTransfer.files || e.dataTransfer.files.length === 0) return;

    const file = e.dataTransfer.files[0];
    const ext = (file.name || '').split('.').pop().toLowerCase();
    const validExts = ['ini', 'py', 'zip', 'rar', '7z', 'tar', 'gz'];
    if (!validExts.includes(ext)) {
        if (typeof showToast === 'function') {
            showToast('Please drop a GSX profile (.ini) or archive (.zip, .rar, .7z)', 'warning');
        }
        return;
    }

    const path = file.path || '';
    const targetIcao = selectedAirport ? (selectedAirport.icao || '') : (currentRadialAirport ? currentRadialAirport.icao : '');
    if (path) {
        checkGsxDropConflictAndInstall(targetIcao, { filePath: path });
    } else {
        const reader = new FileReader();
        reader.onload = function(event) {
            const base64Data = event.target.result;
            checkGsxDropConflictAndInstall(targetIcao, { base64Data: base64Data, filename: file.name });
        };
        reader.onerror = function() {
            showCustomModal({ title: 'File Read Error', message: 'Unable to read the dropped file.', type: 'error' });
        };
        reader.readAsDataURL(file);
    }
}

async function triggerInstallGsxProfile() {
    const targetIcao = selectedAirport ? (selectedAirport.icao || '') : (currentRadialAirport ? currentRadialAirport.icao : '');
    await executeGsxInstallationForIcao(targetIcao, { filePath: '' });
}

async function executeGsxInstallation({ filePath = '', base64Data = '', filename = '', replaceExisting = false } = {}) {
    if (!selectedAirport && !currentRadialAirport) return;
    const targetIcao = selectedAirport ? (selectedAirport.icao || '') : (currentRadialAirport ? currentRadialAirport.icao : '');
    try {
        if (window.pywebview) {
            const resStr = await window.pywebview.api.install_gsx_profile(
                targetIcao,
                filePath || '',
                base64Data || '',
                filename || '',
                replaceExisting
            );
            const res = typeof resStr === 'string' ? JSON.parse(resStr) : resStr;
            if (res.status === 'ok') {
                if (res.airports && Array.isArray(res.airports)) {
                    allAirportsData = res.airports;
                }
                const actualIcao = (res.target_icao || targetIcao).toUpperCase();
                const ap = (typeof getAirportByIcao === 'function') ? getAirportByIcao(actualIcao) : null;
                if (ap) {
                    ap.has_gsx_profile = true;
                    if (res.installed_files && res.installed_files.length > 0) {
                        const iniF = res.installed_files.find(f => f.toLowerCase().endsWith('.ini')) || res.installed_files[0];
                        ap.gsx_ini_file = iniF;
                        ap.gsx_profile_filename = iniF;
                    }
                    if (res.airport) {
                        Object.assign(ap, res.airport);
                    }
                }
                updateStats(allAirportsData);
                filterAirports();

                if (window.pywebview.api.scan_gsx_audit) {
                    try {
                        const auditRes = await window.pywebview.api.scan_gsx_audit();
                        const parsedAudit = typeof auditRes === 'string' ? JSON.parse(auditRes) : auditRes;
                        if (parsedAudit && parsedAudit.status === 'ok') {
                            window.gsxAuditData = parsedAudit.data;
                        }
                    } catch (err) {}
                }

                const updatedAp = getAirportByIcao(selectedAirport.icao);
                if (updatedAp) {
                    if (currentRadialAirport && currentRadialAirport.icao === updatedAp.icao) {
                        currentRadialAirport = updatedAp;
                        renderRadialAirportDetails(currentRadialAirport);
                    }
                }
                const targetAp = (selectedAirport && selectedAirport.icao) ? selectedAirport : (currentRadialAirport || null);
                const icao = targetAp ? targetAp.icao.toUpperCase() : 'GSX';
                const apName = targetAp ? (targetAp.name || targetAp.icao) : 'GSX Profile';
                const files = (res.installed_files && res.installed_files.length > 0) ? res.installed_files : ['profile.ini'];

                const installedCardsHtml = files.map(fileName => `
                    <div class="p-3 rounded-xl bg-slate-900 border border-slate-800 flex items-center justify-between gap-4">
                        <div class="flex items-center gap-3.5 min-w-0 flex-1">
                            <span class="font-mono font-black text-lg sm:text-xl tracking-tight shrink-0 text-cyan-400">
                                ${icao}
                            </span>
                            <div class="min-w-0 flex-1 text-left">
                                <div class="text-sm font-bold text-white truncate">
                                    ${apName}
                                </div>
                                <div class="text-xs font-mono text-slate-400 truncate mt-0.5">
                                    ${fileName}
                                </div>
                            </div>
                        </div>
                        <div class="shrink-0">
                            <span class="text-xs font-bold px-3 py-1 rounded-full bg-emerald-600 text-white">${t('rescan.status_added', 'Added')}</span>
                        </div>
                    </div>
                `).join('');

                showCustomModal({
                    title: t('modal.gsx_installed', 'GSX Profile Installed'),
                    message: installedCardsHtml,
                    messageBoxClass: 'max-h-72 overflow-y-auto space-y-2 p-2 rounded-2xl bg-slate-950 border border-slate-800',
                    type: 'success',
                    confirmText: t('modal.continue', 'Continue')
                });
            } else {
                showCustomModal({
                    title: t('modal.gsx_info', 'GSX Profile Information'),
                    message: res.message,
                    type: 'info',
                    confirmText: t('modal.ok', 'OK')
                });
            }
        }
    } catch (e) {
        console.error("GSX Installation error:", e);
        showCustomModal({
            title: t('modal.gsx_error', 'GSX Installation Error'),
            message: e.message || String(e),
            type: 'error'
        });
    }
}

