async function openSettingsModal() {
    try {
        if (window.pywebview && window.pywebview.api && typeof window.pywebview.api.get_settings === 'function') {
            const cfgStr = await window.pywebview.api.get_settings();
            if (cfgStr) {
                currentSettings = (typeof cfgStr === 'string') ? JSON.parse(cfgStr) : cfgStr;
            }
        } else if (typeof fetch === 'function') {
            try {
                const resp = await fetch('/api/settings');
                if (resp.ok) {
                    currentSettings = await resp.json();
                }
            } catch (err) {}
        }
    } catch (e) {
        console.error("Failed to load settings:", e);
    }

    if (!currentSettings || typeof currentSettings !== 'object') {
        currentSettings = {
            auto_scan_on_startup: true,
            scan_paths: [],
            camera_airport_zoom: 8.0,
            camera_pan_duration: 1.1,
            navigation_style: 'classic',
            theme: 'dark'
        };
    }

    const autoScanEl = document.getElementById('cfg-auto-scan');
    if (autoScanEl) {
        autoScanEl.checked = !!currentSettings.auto_scan_on_startup;
    }
    const gsxInput = document.getElementById('cfg-gsx-path');
    if (gsxInput) {
        gsxInput.value = currentSettings.gsx_profile_path || '';
    }

    const regSelect = document.getElementById('cfg-camera-region');
    if (regSelect) {
        regSelect.value = currentSettings.camera_startup_region || 'world';
    }

    const zoomSlider = document.getElementById('cfg-camera-zoom');
    if (zoomSlider) {
        const zVal = (currentSettings.camera_airport_zoom !== undefined) ? parseFloat(currentSettings.camera_airport_zoom) : 8.0;
        zoomSlider.value = zVal;
        const zDisp = document.getElementById('cfg-zoom-display');
        if (zDisp) zDisp.innerText = zVal.toFixed(1);
    }

    const durSlider = document.getElementById('cfg-camera-duration');
    if (durSlider) {
        const dVal = (currentSettings.camera_pan_duration !== undefined) ? parseFloat(currentSettings.camera_pan_duration) : 1.1;
        durSlider.value = dVal;
        const dDisp = document.getElementById('cfg-duration-display');
        if (dDisp) dDisp.innerText = `${dVal.toFixed(1)}s`;
    }

    const navStyleSelect = document.getElementById('cfg-nav-style');
    if (navStyleSelect) {
        navStyleSelect.value = currentSettings.navigation_style || 'classic';
    }

    const langSelect = document.getElementById('cfg-app-language');
    if (langSelect) {
        langSelect.value = currentSettings.language || (typeof currentLang !== 'undefined' ? currentLang : 'en');
    }

    const currSelect = document.getElementById('cfg-app-currency');
    if (currSelect) {
        currSelect.value = selectedCurrency || currentSettings.currency || 'EUR';
    }

    const chkIcao = document.getElementById('cfg-label-icao');
    if (chkIcao) chkIcao.checked = currentSettings.show_label_icao !== false;
    const chkName = document.getElementById('cfg-label-name');
    if (chkName) chkName.checked = currentSettings.show_label_name !== false;
    const chkCity = document.getElementById('cfg-label-city');
    if (chkCity) chkCity.checked = currentSettings.show_label_city !== false;

    const isExtAutoFps = !!(currentSettings.external_autofps || currentSettings.dynamic_lod_engine === 'external_autofps');
    currentSettings.external_autofps = isExtAutoFps;
    updateExternalAutoFpsSwitchUI(isExtAutoFps);

    const closeActionSelect = document.getElementById('cfg-close-action');
    if (closeActionSelect) {
        closeActionSelect.value = currentSettings.close_action || 'quit';
    }

    const chkPrivacyCrash = document.getElementById('cfg-privacy-crash-reports');
    if (chkPrivacyCrash) {
        chkPrivacyCrash.checked = currentSettings.auto_send_crash_reports !== false;
    }
    const chkPrivacyTelem = document.getElementById('cfg-privacy-telemetry-stats');
    if (chkPrivacyTelem) {
        chkPrivacyTelem.checked = currentSettings.send_anonymous_telemetry !== false;
    }

    if (currentSettings.is_lite !== undefined) {
        window.IS_LITE = !!currentSettings.is_lite;
    }
    if (typeof applyLiteEditionLocks === 'function') {
        applyLiteEditionLocks();
    }
    loadSimBriefSettingsUI();
    renderSettingsPathsList();
    if (typeof refreshIngamePanelStatus === 'function') {
        refreshIngamePanelStatus();
    }
    const backdrop = document.getElementById('settings-modal-backdrop');
    if (backdrop) {
        backdrop.classList.remove('hidden');
        backdrop.style.zIndex = '4999';
    }

    const modal = document.getElementById('settings-modal');
    if (modal) {
        modal.classList.remove('hidden');
        modal.classList.add('flex');
        modal._hasBeenDragged = false;
        modal.style.left = '50%';
        modal.style.top = '50%';
        modal.style.transform = 'translate(-50%, -50%)';
        modal.style.right = 'auto';
        modal.style.bottom = 'auto';
        modal.style.zIndex = '5000';
        if (window.windowManager) {
            window.windowManager.bringToFront(modal);
        }
    }
}

function updateExternalAutoFpsSwitchUI(isActive) {
    const track = document.getElementById('cfg-external-autofps-track');
    const thumb = document.getElementById('cfg-external-autofps-thumb');
    if (track && thumb) {
        if (isActive) {
            track.className = 'w-10 h-5 rounded-full transition-colors duration-200 ease-in-out p-0.5 bg-sky-500 shadow-sm';
            thumb.className = 'w-4 h-4 rounded-full bg-white shadow-md transform transition-transform duration-200 ease-in-out translate-x-5';
        } else {
            track.className = 'w-10 h-5 rounded-full transition-colors duration-200 ease-in-out p-0.5 bg-slate-700';
            thumb.className = 'w-4 h-4 rounded-full bg-white shadow-md transform transition-transform duration-200 ease-in-out translate-x-0';
        }
    }
}

function toggleExternalAutoFpsSettingSwitch() {
    if (window.IS_LITE) {
        showUnlockProModal();
        return;
    }
    currentSettings.external_autofps = !currentSettings.external_autofps;
    currentSettings.dynamic_lod_engine = currentSettings.external_autofps ? 'external_autofps' : 'smart_lod';
    updateExternalAutoFpsSwitchUI(currentSettings.external_autofps);
    if (window.smartLodAxisState) {
        window.smartLodAxisState.external_autofps = currentSettings.external_autofps;
    }
    if (window.pywebview && window.pywebview.api && window.pywebview.api.set_external_autofps) {
        window.pywebview.api.set_external_autofps(currentSettings.external_autofps);
    }
    if (typeof renderMsfsSettingsMatrix === 'function') {
        renderMsfsSettingsMatrix();
    }
    if (typeof updateFlightOptimizerRadialSectors === 'function') {
        updateFlightOptimizerRadialSectors();
    }
}

function closeSettingsModal() {
    const backdrop = document.getElementById('settings-modal-backdrop');
    if (backdrop) backdrop.classList.add('hidden');

    const modal = document.getElementById('settings-modal');
    if (modal) {
        modal.classList.add('hidden');
        modal.classList.remove('flex');
        modal._hasBeenDragged = false;
    }
    // Revert navigation style dropdown and active mode if cancelled without saving
    const navStyleSelect = document.getElementById('cfg-nav-style');
    if (navStyleSelect && typeof currentSettings !== 'undefined') {
        const savedStyle = currentSettings.navigation_style || 'classic';
        if (navStyleSelect.value !== savedStyle) {
            navStyleSelect.value = savedStyle;
            if (typeof applyNavigationStyle === 'function') {
                applyNavigationStyle(savedStyle);
            }
        }
    }
    if (isClassicNavMode()) {
        const radialEl = document.getElementById('airport-radial-menu');
        if (radialEl) {
            radialEl.classList.add('hidden');
            radialEl.style.display = 'none';
        }
        const filterEl = document.getElementById('filter-radial-menu');
        if (filterEl) {
            filterEl.classList.add('hidden');
            filterEl.style.display = 'none';
        }
    } else {
        const radialEl = document.getElementById('airport-radial-menu');
        if (radialEl) {
            radialEl.style.display = '';
            radialEl.classList.remove('radial-only-core');
        }
        const filterEl = document.getElementById('filter-radial-menu');
        if (filterEl) {
            filterEl.style.display = '';
        }
        const targetAp = currentRadialAirport || currentClassicAirport || selectedAirport;
        currentClassicAirport = null;
        if (targetAp) {
            const targetMarker = (typeof airportMarkerCache !== 'undefined' && airportMarkerCache.get(targetAp.icao)) || currentRadialMarker || null;
            openAirportRadialMenu(targetAp, targetMarker);
        }
    }
}

function renderSettingsPathsList() {
    const container = document.getElementById('settings-paths-list');
    container.innerHTML = '';

    const paths = currentSettings.scan_paths || [];

    paths.forEach((item, index) => {
        const row = document.createElement('div');
        row.className = "p-3 rounded-lg bg-slate-950/80 border border-slate-700/60 flex items-center justify-between gap-3";

        row.innerHTML = `
            <div class="space-y-1.5 flex-1">
                <div class="flex items-center justify-between pb-0.5 select-none">
                    <span class="text-xs font-semibold text-slate-200 tracking-wide truncate" title="${escapeHtml(item.name || 'MSFS Scenery Path')}">
                        ${escapeHtml(item.name || 'MSFS Scenery Path')}
                    </span>
                </div>

                <div class="flex items-center gap-2">
                    <input type="text" value="${item.path || ''}" 
                           oninput="updatePathValue(${index}, this.value)"
                           class="w-full bg-slate-900 border border-slate-700/60 rounded-md px-3 py-1.5 text-xs font-mono text-slate-300 focus:outline-none focus:border-slate-400 focus:bg-slate-800">
                    <button onclick="browsePathFolder(${index})" class="px-2.5 py-1.5 rounded-md bg-slate-800 hover:bg-slate-700 border border-slate-700/60 text-slate-300 hover:text-white text-xs font-semibold transition-colors flex items-center shrink-0 cursor-pointer" title="Browse / Change Folder">
                        Browse
                    </button>
                    <button onclick="openPathInExplorer(${index})" class="px-2.5 py-1.5 rounded-md bg-slate-800 hover:bg-slate-700 border border-slate-700/60 text-slate-300 hover:text-white text-xs font-semibold transition-colors flex items-center justify-center shrink-0 cursor-pointer" title="Open in Windows Explorer">
                        Explorer
                    </button>
                </div>
            </div>

            <div class="flex items-center gap-3 self-center pl-2">
                <label class="relative inline-flex items-center cursor-pointer" title="Enable/Disable Path Scan">
                    <input type="checkbox" ${item.enabled ? 'checked' : ''} onchange="togglePathEnabled(${index}, this.checked)" class="sr-only peer">
                    <div class="w-9 h-5 bg-slate-800 peer-focus:outline-none rounded-full peer peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border-slate-300 after:border after:rounded-full after:h-4 after:w-4 after:transition-all peer-checked:bg-slate-400"></div>
                </label>

                <button onclick="removePathRow(${index})" class="w-7 h-7 rounded-md bg-slate-800 hover:bg-slate-700 border border-slate-700/60 text-slate-400 hover:text-red-400 transition-colors flex items-center justify-center cursor-pointer" title="Remove Path">
                    ✕
                </button>
            </div>
        `;

        container.appendChild(row);
    });
}

function updatePathValue(index, val) {
    if (currentSettings.scan_paths[index]) {
        currentSettings.scan_paths[index].path = val;
    }
}

function togglePathEnabled(index, checked) {
    if (currentSettings.scan_paths[index]) {
        currentSettings.scan_paths[index].enabled = checked;
    }
}

function openPathInExplorer(index) {
    const item = currentSettings.scan_paths && currentSettings.scan_paths[index];
    const p = (item && item.path) ? item.path.trim() : '';
    if (window.pywebview && window.pywebview.api && p) {
        window.pywebview.api.open_folder(p);
    }
}

async function browsePathFolder(index) {
    if (window.pywebview) {
        const item = currentSettings.scan_paths && currentSettings.scan_paths[index];
        const currentPath = (item && item.path) ? item.path.trim() : '';
        const folder = await window.pywebview.api.browse_folder(currentPath);
        if (folder) {
            currentSettings.scan_paths[index].path = folder;
            const isOfficialDefault = item.id && (item.id.includes('official') || item.id.includes('streamed') || item.id.includes('community'));
            if (!isOfficialDefault) {
                const folderName = folder.replace(/[/\\]+$/, '').split(/[/\\]/).pop() || 'Custom Scenery';
                currentSettings.scan_paths[index].name = folderName;
            }
            renderSettingsPathsList();
        }
    }
}

function removePathRow(index) {
    currentSettings.scan_paths.splice(index, 1);
    renderSettingsPathsList();
}

async function addCustomPathRow() {
    let selectedFolder = null;
    if (window.pywebview && window.pywebview.api) {
        let defaultDir = '';
        if (currentSettings.scan_paths && currentSettings.scan_paths.length > 0) {
            for (let i = currentSettings.scan_paths.length - 1; i >= 0; i--) {
                if (currentSettings.scan_paths[i] && currentSettings.scan_paths[i].path) {
                    const p = currentSettings.scan_paths[i].path.trim();
                    if (p) {
                        defaultDir = p;
                        break;
                    }
                }
            }
        }
        selectedFolder = await window.pywebview.api.browse_folder(defaultDir);
        if (!selectedFolder) {
            return; // User cancelled
        }
    } else {
        selectedFolder = "D:\\Custom_MSFS_Sceneries";
    }

    let folderName = selectedFolder.replace(/[/\\]+$/, '').split(/[/\\]/).pop() || 'Custom Scenery';
    const newId = String(Date.now());
    if (!currentSettings.scan_paths) {
        currentSettings.scan_paths = [];
    }
    currentSettings.scan_paths.push({
        id: newId,
        name: folderName,
        path: selectedFolder,
        enabled: true
    });
    renderSettingsPathsList();

    const container = document.getElementById('settings-paths-list');
    if (container) {
        container.scrollTo({ top: container.scrollHeight, behavior: 'smooth' });
        const lastRow = container.lastElementChild;
        if (lastRow) {
            lastRow.classList.add('ring-1', 'ring-slate-400', 'transition-all');
            setTimeout(() => {
                lastRow.classList.remove('ring-1', 'ring-slate-400');
            }, 2000);
        }
    }
}


async function saveSettings() {
    try {
        const autoScanEl = document.getElementById('cfg-auto-scan');
        if (autoScanEl) currentSettings.auto_scan_on_startup = autoScanEl.checked;

        const gsxInput = document.getElementById('cfg-gsx-path');
        if (gsxInput) {
            currentSettings.gsx_profile_path = gsxInput.value.trim();
        }

        const regSelect = document.getElementById('cfg-camera-region');
        if (regSelect) {
            currentSettings.camera_startup_region = regSelect.value;
        }
        const zoomSlider = document.getElementById('cfg-camera-zoom');
        if (zoomSlider) {
            currentSettings.camera_airport_zoom = parseFloat(zoomSlider.value);
        }
        const durSlider = document.getElementById('cfg-camera-duration');
        if (durSlider) {
            currentSettings.camera_pan_duration = parseFloat(durSlider.value);
        }

        const navStyleSelect = document.getElementById('cfg-nav-style');
        if (navStyleSelect) {
            currentSettings.navigation_style = navStyleSelect.value || 'classic';
            if (typeof applyNavigationStyle === 'function') {
                applyNavigationStyle(currentSettings.navigation_style);
            }
        }

        const langSelect = document.getElementById('cfg-app-language');
        if (langSelect) {
            currentSettings.language = langSelect.value;
            if (typeof setAppLanguage === 'function') {
                setAppLanguage(langSelect.value);
            }
        }

        const currSelect = document.getElementById('cfg-app-currency');
        if (currSelect) {
            currentSettings.currency = currSelect.value;
            setCurrency(currSelect.value);
        }

        const chkIcao = document.getElementById('cfg-label-icao');
        if (chkIcao) currentSettings.show_label_icao = chkIcao.checked;
        const chkName = document.getElementById('cfg-label-name');
        if (chkName) currentSettings.show_label_name = chkName.checked;
        const chkCity = document.getElementById('cfg-label-city');
        if (chkCity) currentSettings.show_label_city = chkCity.checked;

        const isExt = !!currentSettings.external_autofps;
        currentSettings.external_autofps = isExt;
        currentSettings.dynamic_lod_engine = isExt ? 'external_autofps' : 'smart_lod';
        if (window.pywebview && window.pywebview.api && window.pywebview.api.set_external_autofps) {
            window.pywebview.api.set_external_autofps(isExt);
        }
        const closeActionSelect = document.getElementById('cfg-close-action');
        if (closeActionSelect) {
            currentSettings.close_action = closeActionSelect.value;
        }

        const chkPrivacyCrash = document.getElementById('cfg-privacy-crash-reports');
        if (chkPrivacyCrash) {
            currentSettings.auto_send_crash_reports = chkPrivacyCrash.checked;
        }
        const chkPrivacyTelem = document.getElementById('cfg-privacy-telemetry-stats');
        if (chkPrivacyTelem) {
            currentSettings.send_anonymous_telemetry = chkPrivacyTelem.checked;
        }
        if (window.pywebview && window.pywebview.api && window.pywebview.api.save_bug_reporter_privacy) {
            window.pywebview.api.save_bug_reporter_privacy(JSON.stringify({
                auto_send_crash_reports: currentSettings.auto_send_crash_reports !== false,
                send_anonymous_telemetry: currentSettings.send_anonymous_telemetry !== false
            })).catch(() => {});
        }

        if (window.pywebview && window.pywebview.api && window.pywebview.api.save_smart_lod_config) {
            window.pywebview.api.save_smart_lod_config(JSON.stringify({
                "source": isExt ? 'external_autofps' : 'native',
                "auto_kill_autofps": false
            })).catch(() => {});
        }

        const sbInput = document.getElementById('cfg-simbrief-id');
        if (sbInput) {
            const val = sbInput.value.trim();
            if (val.match(/^\d+$/)) {
                currentSettings.simbrief_userid = val;
            } else {
                currentSettings.simbrief_username = val;
            }
        }

        // Only apply startup camera if no airport is currently focused and not in flight planning mode
        if (!currentRadialAirport && !selectedAirport && !isFlightPlanningMode) {
            applyStartupCameraSettings();
        }

        // Re-render map markers with updated label settings
        airportMarkerCache.clear();
        customDivIconCache.clear();
        if (map && currentlyFilteredAirports && currentlyFilteredAirports.length > 0) {
            renderAirportsOnMap(currentlyFilteredAirports);
        }

        if (isClassicNavMode()) {
            const radialEl = document.getElementById('airport-radial-menu');
            if (radialEl) {
                radialEl.classList.add('hidden');
                radialEl.style.display = 'none';
            }
            const filterEl = document.getElementById('filter-radial-menu');
            if (filterEl) {
                filterEl.classList.add('hidden');
                filterEl.style.display = 'none';
            }
        } else {
            const radialEl = document.getElementById('airport-radial-menu');
            if (radialEl) {
                radialEl.style.display = '';
                radialEl.classList.remove('radial-only-core');
            }
            const filterEl = document.getElementById('filter-radial-menu');
            if (filterEl) {
                filterEl.style.display = '';
            }
            const targetAp = currentRadialAirport || currentClassicAirport || selectedAirport;
            currentClassicAirport = null;
            if (targetAp) {
                const targetMarker = (typeof airportMarkerCache !== 'undefined' && airportMarkerCache.get(targetAp.icao)) || currentRadialMarker || null;
                openAirportRadialMenu(targetAp, targetMarker);
            }
        }

        if (window.pywebview && window.pywebview.api && window.pywebview.api.save_settings) {
            await window.pywebview.api.save_settings(JSON.stringify(currentSettings));
        }
        if (typeof showToast === 'function') {
            showToast('Settings saved successfully.', 'success');
        }
        const saveBtn = document.getElementById('settings-save-btn');
        const saveBtnText = document.getElementById('settings-save-btn-text');
        if (saveBtnText) {
            const origText = saveBtnText.textContent;
            saveBtnText.textContent = (typeof t === 'function') ? t('settings.saved', 'Saved') : 'Saved';
            if (saveBtn) saveBtn.classList.add('text-emerald-400', 'border-emerald-600/60');
            setTimeout(() => {
                if (saveBtnText) saveBtnText.textContent = origText;
                if (saveBtn) saveBtn.classList.remove('text-emerald-400', 'border-emerald-600/60');
            }, 1600);
        }
    } catch (e) {
        console.error("Failed to save settings:", e);
        if (typeof showToast === 'function') {
            showToast('Failed to save settings: ' + e, 'error');
        }
    }
}

function previewAppLanguage(lang) {
    if (typeof setAppLanguage === 'function') {
        setAppLanguage(lang);
    }
}

