/* ================= EXPORT COLLECTION FUNCTIONS ================= */

function openExportModal() {
    const modal = document.getElementById('export-modal');
    if (modal) {
        modal.classList.remove('hidden');
        if (window.windowManager) {
            window.windowManager.centerModal(modal);
            window.windowManager.bringToFront(modal);
        }
    }

    const txtEl = document.getElementById('export-scope-text');
    const scopeEl = document.querySelector('input[name="export-scope"]:checked');
    if (txtEl && scopeEl) {
        if (scopeEl.value === 'all') {
            txtEl.innerText = t('export.scope_all_desc', `Exports your entire scenery collection (physical sceneries & streamed Marketplace).`);
        } else {
            txtEl.innerText = t('export.scope_filtered_desc', `Exports only the sceneries currently matching your active sidebar filters.`);
        }
    }

    document.querySelectorAll('input[name="export-scope"]').forEach(radio => {
        radio.onclick = function() {
            if (!txtEl) return;
            if (this.value === 'all') {
                txtEl.innerText = t('export.scope_all_desc', `Exports your entire scenery collection (physical sceneries & streamed Marketplace).`);
            } else {
                txtEl.innerText = t('export.scope_filtered_desc', `Exports only the sceneries currently matching your active sidebar filters.`);
            }
        };
    });
}

function closeExportModal() {
    const modal = document.getElementById('export-modal');
    if (modal) modal.classList.add('hidden');
}

async function triggerExportCollection(format) {
    const scopeEl = document.querySelector('input[name="export-scope"]:checked');
    const scope = scopeEl ? scopeEl.value : 'all';

    const dataToExport = (scope === 'filtered') ? currentlyFilteredAirports : allAirportsData;

    if (!dataToExport || dataToExport.length === 0) {
        alert("No sceneries available to export.");
        return;
    }

    try {
        if (window.pywebview) {
            const dataJson = JSON.stringify(dataToExport);
            let resStr;
            if (format === 'csv') {
                resStr = await window.pywebview.api.export_collection_csv(dataJson);
            } else {
                resStr = await window.pywebview.api.export_collection_json(dataJson);
            }

            const res = JSON.parse(resStr);
            if (res.status === 'ok') {
                closeExportModal();
                showCustomModal({
                    title: "Collection Exported Successfully",
                    message: `Exported ${res.count} sceneries to:\n${res.path}`,
                    confirmText: "OK"
                });
            } else if (res.status !== 'cancelled') {
                showCustomModal({
                    title: "Export Failed",
                    message: res.message || "Could not export collection.",
                    confirmText: "OK"
                });
            }
        }
    } catch (e) {
        console.error("Export collection error:", e);
        showCustomModal({
            title: "Export Error",
            message: "Failed to export collection.",
            confirmText: "OK"
        });
    }
}

/* ================= SYSTEM NOTIFICATION MODAL FUNCTIONS ================= */

let customModalConfirmCallback = null;
let customModalCancelCallback = null;
let customModalSecondaryCallback = null;

function showCustomModal(titleOrObj, messageStr, typeStr = 'info') {
    const modal = document.getElementById('custom-modal');

    let title = 'Notification';
    let message = '';
    let type = 'info';
    let confirmText = 'OK';
    let cancelText = 'Cancel';
    let secondaryText = '';
    let showCancel = false;
    let showSecondary = false;

    if (typeof titleOrObj === 'object' && titleOrObj !== null) {
        title = titleOrObj.title !== undefined ? titleOrObj.title : '';
        message = titleOrObj.message || '';
        type = titleOrObj.type || 'info';
        confirmText = titleOrObj.confirmText || 'OK';
        cancelText = titleOrObj.cancelText || 'Cancel';
        secondaryText = titleOrObj.secondaryText || '';
        showCancel = titleOrObj.showCancel !== undefined ? !!titleOrObj.showCancel : (!!titleOrObj.cancelText || !!titleOrObj.onCancel);
        showSecondary = !!secondaryText;
        customModalConfirmCallback = titleOrObj.onConfirm || null;
        customModalCancelCallback = titleOrObj.onCancel || null;
        customModalSecondaryCallback = titleOrObj.onSecondary || null;
    } else {
        title = titleOrObj !== undefined && titleOrObj !== null ? titleOrObj : '';
        message = messageStr || '';
        type = typeStr || 'info';
        customModalConfirmCallback = null;
        customModalCancelCallback = null;
        customModalSecondaryCallback = null;
    }

    if (!modal) {
        alert(`${title}\n\n${message}`);
        return;
    }

    if (typeof titleOrObj === 'object' && titleOrObj && titleOrObj.width) {
        modal.style.width = titleOrObj.width;
    } else {
        modal.style.width = '540px';
    }

    const titleEl = document.getElementById('custom-modal-title');
    const msgEl = document.getElementById('custom-modal-message');
    const cancelBtn = document.getElementById('custom-modal-cancel-btn');
    const secondaryBtn = document.getElementById('custom-modal-secondary-btn');
    const confirmBtn = document.getElementById('custom-modal-confirm-btn');

    if (titleEl) {
        if (title && title.trim().length > 0) {
            titleEl.innerText = title;
            titleEl.classList.remove('hidden');
        } else {
            titleEl.innerText = '';
            titleEl.classList.add('hidden');
        }
    }
    if (msgEl) {
        if (typeof titleOrObj === 'object' && titleOrObj && titleOrObj.messageBoxClass) {
            msgEl.className = titleOrObj.messageBoxClass;
        } else {
            msgEl.className = "p-4 rounded-lg bg-slate-950 border border-slate-800 text-xs text-slate-300 leading-relaxed font-sans break-words max-h-80 overflow-y-auto space-y-2 text-left";
        }

        if (typeof message === 'string') {
            if (message.includes('<')) {
                msgEl.innerHTML = message;
            } else if (message.includes('\n')) {
                msgEl.innerHTML = message.replace(/\n/g, '<br>');
            } else {
                msgEl.innerText = message;
            }
        }
    }

    const loadingContainer = document.getElementById('custom-modal-loading-bar-container');
    if (type === 'loading') {
        if (confirmBtn) confirmBtn.classList.add('hidden');
        if (secondaryBtn) secondaryBtn.classList.add('hidden');
        if (cancelBtn) cancelBtn.classList.add('hidden');
        if (loadingContainer) loadingContainer.classList.remove('hidden');
    } else {
        if (loadingContainer) loadingContainer.classList.add('hidden');
        if (confirmBtn) {
            confirmBtn.innerText = confirmText;
            if (typeof titleOrObj === 'object' && titleOrObj && titleOrObj.confirmClass) {
                confirmBtn.className = titleOrObj.confirmClass;
            } else {
                confirmBtn.className = "px-5 py-2 text-center rounded-md bg-cyan-500 hover:bg-cyan-400 text-slate-950 typo-action-btn font-bold text-xs uppercase transition-colors border-0 cursor-pointer";
            }
            confirmBtn.classList.remove('hidden');
        }
        if (secondaryBtn) {
            if (showSecondary) {
                secondaryBtn.innerText = secondaryText;
                if (typeof titleOrObj === 'object' && titleOrObj && titleOrObj.secondaryClass) {
                    secondaryBtn.className = titleOrObj.secondaryClass;
                } else {
                    secondaryBtn.className = "px-4 py-2 text-center rounded-md bg-slate-800 hover:bg-slate-700 border border-slate-700 text-slate-300 hover:text-white typo-action-btn font-normal uppercase transition-colors cursor-pointer text-xs";
                }
                secondaryBtn.classList.remove('hidden');
            } else {
                secondaryBtn.classList.add('hidden');
            }
        }
        if (cancelBtn) {
            cancelBtn.innerText = cancelText;
            if (typeof titleOrObj === 'object' && titleOrObj && titleOrObj.cancelClass) {
                cancelBtn.className = titleOrObj.cancelClass;
            } else {
                cancelBtn.className = "px-4 py-2 text-center rounded-md bg-slate-800 hover:bg-slate-700 border border-slate-700 text-slate-300 hover:text-white typo-action-btn text-xs font-normal uppercase transition-colors cursor-pointer";
            }
            cancelBtn.classList.toggle('hidden', !showCancel);
        }
    }

    const iconBg = document.getElementById('custom-modal-icon-bg');
    const iconEl = document.getElementById('custom-modal-icon');

    if (iconBg && iconEl) {
        iconBg.className = "w-10 h-10 rounded-lg flex items-center justify-center shrink-0 bg-slate-950 border border-slate-800";
        iconEl.className = "fa-solid text-base text-slate-300";
        if (type === 'loading') {
            iconEl.className = "fa-solid fa-spinner fa-spin text-base text-cyan-400";
        } else if (type === 'success') {
            iconEl.classList.add('fa-circle-check');
        } else if (type === 'error') {
            iconEl.classList.add('fa-triangle-exclamation');
        } else {
            iconEl.classList.add('fa-circle-info');
        }
    }

    modal.classList.remove('hidden');
    modal.classList.add('flex');
    if (window.windowManager) {
        windowManager.bringToFront(modal);
        windowManager.centerModal(modal);
    }
}

function closeCustomModal() {
    const modal = document.getElementById('custom-modal');
    if (modal) {
        modal.classList.add('hidden');
        modal.classList.remove('flex');
    }
    customModalConfirmCallback = null;
    customModalCancelCallback = null;
    customModalSecondaryCallback = null;
}

function confirmCustomModal() {
    const cb = customModalConfirmCallback;
    closeCustomModal();
    if (cb && typeof cb === 'function') {
        cb();
    }
}

function secondaryCustomModal() {
    const cb = customModalSecondaryCallback;
    closeCustomModal();
    if (cb && typeof cb === 'function') {
        cb();
    }
}

function cancelCustomModal() {
    const cb = customModalCancelCallback;
    closeCustomModal();
    if (cb && typeof cb === 'function') {
        cb();
    }
}

