async function fetchAndRenderUserCfgBackups() {
    const listEl = document.getElementById('user-cfg-backup-list');
    if (!listEl) return;

    let userCfgBackupsList = [];
    if (window.pywebview && window.pywebview.api && window.pywebview.api.get_user_cfg_backups) {
        try {
            const resStr = await window.pywebview.api.get_user_cfg_backups();
            userCfgBackupsList = JSON.parse(resStr);
        } catch (e) {
            console.error("Error fetching backups:", e);
        }
    }

    if (!userCfgBackupsList || userCfgBackupsList.length === 0) {
        listEl.innerHTML = '<div class="p-6 text-center text-slate-500 font-mono text-xs">No backups found yet. Backups are created automatically when applying profile changes.</div>';
    } else {
        let html = '';
        userCfgBackupsList.slice(0, 20).forEach((b, index) => {
            const isLatest = (index === 0);
            html += `
                <div class="p-3 rounded-2xl bg-slate-950 border ${isLatest ? 'border-amber-500/60' : 'border-slate-800'} flex items-center justify-between gap-3">
                    <div class="flex items-center gap-2.5">
                        <div class="w-8 h-8 rounded-xl ${isLatest ? 'bg-amber-500 text-slate-950 font-black' : 'bg-slate-800 text-slate-400'} flex items-center justify-center shrink-0">
                            <span class="font-mono text-[9px] font-black">BAK</span>
                        </div>
                        <div class="flex items-center gap-2">
                            <span class="typo-input-val font-medium text-xs text-white tracking-wide tabular-nums">${b.timestamp}</span>
                            ${isLatest ? '<span class="px-2 py-0.5 rounded text-[9px] font-bold bg-amber-500 text-slate-950 uppercase shadow-sm whitespace-nowrap leading-none tracking-wider">MOST RECENT</span>' : ''}
                        </div>
                    </div>
                    <div class="flex items-center gap-2 shrink-0">
                        <button onclick="restoreUserCfgBackupTarget('${b.filename}')" class="px-3.5 py-1.5 rounded-xl bg-amber-500 hover:bg-amber-400 text-slate-950 typo-action-btn font-semibold text-xs transition-all cursor-pointer active:scale-95 uppercase tracking-[0.02em]">
                            Restore
                        </button>
                        <button onclick="deleteUserCfgBackupTarget('${b.filename}')" class="px-2.5 py-1.5 rounded-xl bg-rose-600 hover:bg-rose-500 text-white border-0 typo-action-btn font-semibold text-xs transition-all cursor-pointer active:scale-95 shadow-sm" title="Delete backup">
                            <i class="fa-solid fa-trash-can"></i>
                        </button>
                    </div>
                </div>
            `;
        });
        listEl.innerHTML = html;
    }
}

async function restoreUserCfgBackupTarget(filename) {
    if (!window.pywebview || !window.pywebview.api || !window.pywebview.api.restore_user_cfg_backup) return;
    try {
        const resStr = await window.pywebview.api.restore_user_cfg_backup(filename);
        const res = JSON.parse(resStr);
        if (res.status === 'success') {
            closeUnifiedUserCfgModal();
            if (typeof showToast === 'function') {
                showToast(`UserCfg.opt restored from ${filename}!`, 'success');
            }
            await loadRigDiagnostics();
        } else {
            if (typeof showToast === 'function') {
                showToast(`Rollback failed: ${res.message}`, 'error');
            }
        }
    } catch (e) {
        console.error("Error restoring backup:", e);
    }
}

// -------------------------------------------------------------------------
// CUSTOM PROFILES MANAGEMENT (UNIVERSAL FIELD, SAVE, ACTIVATE, DELETE, RESTORE)
// -------------------------------------------------------------------------

let currentCustomProfiles = [];
let selectedProfileId = '';
let multiSelectedProfileIds = new Set();
let lastClickedProfileIndex = -1;

function formatProfileDate(dateStr) {
    if (!dateStr) return '';
    try {
        const safeStr = dateStr.includes(' ') && !dateStr.includes('T') ? dateStr.replace(' ', 'T') : dateStr;
        const d = new Date(safeStr);
        if (isNaN(d.getTime())) {
            const parts = dateStr.split(' ');
            const datePart = (parts[0] || '').replace(/-/g, '/');
            const timeParts = (parts[1] || '').split(':');
            const timePart = timeParts.slice(0, 2).join(':');
            return `${datePart} ${timePart}`.trim();
        }
        const formatter = new Intl.DateTimeFormat(undefined, {
            year: 'numeric',
            month: '2-digit',
            day: '2-digit',
            hour: '2-digit',
            minute: '2-digit'
        });
        return formatter.format(d).replace(/-/g, '/').replace(/\./g, '/');
    } catch (e) {
        return dateStr;
    }
}

function detectProfileCategoryMode(profile) {
    if (!profile) return '2D';
    const name = String(profile.name || '').toLowerCase();
    const id = String(profile.id || '').toLowerCase();
    if (/\b(?:vr|3d)\b/i.test(name) || id.includes('vr') || id.includes('3d') || name.includes('vr') || name.includes('3d')) {
        return 'VR';
    }
    return '2D';
}

function sortCustomProfilesList() {
    let targetId = selectedProfileId;
    if (!targetId || !currentCustomProfiles.some(p => p.id === targetId)) {
        const active = currentCustomProfiles.find(p => p.is_active);
        targetId = active ? active.id : '';
    }
    currentCustomProfiles.sort((a, b) => {
        if (targetId) {
            if (a.id === targetId) return -1;
            if (b.id === targetId) return 1;
        }
        const timeA = a.created_at ? new Date(a.created_at.replace(' ', 'T')).getTime() : 0;
        const timeB = b.created_at ? new Date(b.created_at.replace(' ', 'T')).getTime() : 0;
        return timeB - timeA;
    });
}

async function openGraphicsSettingsModal() {
    try {
        selectedProfileId = null;
        if (window.pywebview && window.pywebview.api && window.pywebview.api.ensure_active_profile_applied) {
            await window.pywebview.api.ensure_active_profile_applied();
        }
        if (typeof fetchAndRenderCustomProfiles === 'function') {
            await fetchAndRenderCustomProfiles(true);
        }
        if (typeof loadRigDiagnostics === 'function') {
            await loadRigDiagnostics();
        }
        if (typeof renderMsfsSettingsMatrix === 'function') {
            renderMsfsSettingsMatrix();
        }
        if (typeof updateProfileActivateButtonState === 'function') {
            await updateProfileActivateButtonState();
        }
    } catch (e) {
        console.error("Error opening graphics settings modal:", e);
    }
}

async function updateProfileActivateButtonState() {
    const activeTag = document.getElementById('opt-profile-active-tag');
    const btn = document.getElementById('opt-profile-activate-btn');
    const input = document.getElementById('opt-profile-universal-input');
    const typedName = (input ? input.value : '').trim().toLowerCase();

    const activeProfile = (currentCustomProfiles || []).find(p => p.is_active);
    const selectedProfile = (currentCustomProfiles || []).find(p => p.id === selectedProfileId);

    const isMatch = Boolean(selectedProfile && activeProfile && selectedProfile.id === activeProfile.id && typedName === (selectedProfile.name || '').trim().toLowerCase());

    if (activeTag) {
        if (isMatch) {
            activeTag.classList.remove('hidden');
        } else {
            activeTag.classList.add('hidden');
        }
    }

    if (!btn) return;

    if (isMatch) {
        let hasChanges = false;
        if (window.pywebview && window.pywebview.api && window.pywebview.api.check_profile_changes) {
            try {
                const resStr = await window.pywebview.api.check_profile_changes(selectedProfile.id);
                const res = JSON.parse(resStr);
                if (res && res.status === 'success') {
                    hasChanges = Boolean(res.has_changes);
                }
            } catch (e) {
                console.warn("Error checking profile changes:", e);
            }
        }

        if (!hasChanges) {
            btn.innerHTML = `ACTIVE IN MSFS`;
            btn.className = "h-8 px-3 rounded-md bg-emerald-600 hover:bg-emerald-500 active:bg-emerald-700 text-white font-bold border border-emerald-500/50 typo-action-btn text-xs tracking-[0.02em] uppercase shrink-0 whitespace-nowrap inline-flex items-center justify-center leading-none transition-all cursor-pointer shadow-sm select-none";
            btn.title = `Profile "${selectedProfile.name}" is currently active in MSFS`;
            return;
        }
    }

    btn.innerHTML = `ACTIVATE IN MSFS`;
    btn.className = "h-8 px-3 rounded-md bg-slate-800 hover:bg-slate-700 active:bg-slate-600 border border-slate-700/80 text-slate-200 hover:text-white typo-action-btn text-xs font-semibold tracking-[0.02em] transition-all cursor-pointer uppercase shrink-0 whitespace-nowrap inline-flex items-center justify-center leading-none shadow-sm active:scale-[0.98]";
    btn.title = selectedProfile ? `Activate "${selectedProfile.name}" into MSFS` : "Activate profile into MSFS";
}

async function fetchAndRenderCustomProfiles(autoSwitchMode = false) {
    const dropdown = document.getElementById('opt-profiles-dropdown');
    const input = document.getElementById('opt-profile-universal-input');
    if (!window.pywebview || !window.pywebview.api || !window.pywebview.api.get_custom_profiles) return;

    try {
        const resStr = await window.pywebview.api.get_custom_profiles();
        currentCustomProfiles = JSON.parse(resStr) || [];
        
        // Sort: Selected profile at top, then active profile, then other profiles newest first
        sortCustomProfilesList();

        // Strictly prioritize active profile from state/disk
        let activeProfile = currentCustomProfiles.find(p => p.is_active);
        if (!activeProfile && selectedProfileId) {
            activeProfile = currentCustomProfiles.find(p => p.id === selectedProfileId);
        }
        if (!activeProfile && currentCustomProfiles.length > 0) {
            activeProfile = currentCustomProfiles[0];
        }
        if (activeProfile) {
            selectedProfileId = activeProfile.id;
        }

        if (autoSwitchMode && activeProfile) {
            const targetMode = detectProfileCategoryMode(activeProfile);
            if (typeof switchMsfsGraphicsMode === 'function') {
                switchMsfsGraphicsMode(targetMode, false);
            }
        }

        // Hidden select synchronization
        if (dropdown) {
            if (currentCustomProfiles.length === 0) {
                dropdown.innerHTML = '<option value="">No saved profiles yet</option>';
            } else {
                dropdown.innerHTML = currentCustomProfiles.map(p => `
                    <option value="${p.id}" ${p.id === (activeProfile ? activeProfile.id : '') ? 'selected' : ''}>${escapeHtml(p.name)}</option>
                `).join('');
            }
        }

        // Universal Input handling: show active/newest profile name or empty placeholder
        if (input) {
            if (currentCustomProfiles.length > 0 && activeProfile) {
                input.value = activeProfile.name;
                selectedProfileId = activeProfile.id;
                if (dropdown) dropdown.value = activeProfile.id;
            } else {
                input.value = '';
                selectedProfileId = '';
                if (dropdown) dropdown.value = '';
            }
        }

        // Render dropdown list
        renderCustomProfilesDropdownList();

        const activeTagEl = document.getElementById('opt-profile-active-tag');
        if (activeTagEl) {
            const sel = currentCustomProfiles.find(p => p.id === selectedProfileId);
            if (sel && sel.is_active) {
                activeTagEl.classList.remove('hidden');
            } else {
                activeTagEl.classList.add('hidden');
            }
        }

        if (typeof updateProfileActivateButtonState === 'function') {
            await updateProfileActivateButtonState();
        }
    } catch (e) {
        console.error("Error fetching custom profiles:", e);
    }
}

function clearProfileMultiSelection() {
    multiSelectedProfileIds.clear();
    lastClickedProfileIndex = -1;
    renderCustomProfilesDropdownList();
}

function renderCustomProfilesDropdownList() {
    const listEl = document.getElementById('opt-profile-dropdown-list');
    if (!listEl) return;

    sortCustomProfilesList();

    if (currentCustomProfiles.length === 0) {
        listEl.innerHTML = '<div class="p-3 text-slate-500 text-center italic text-xs">No saved profiles yet</div>';
        return;
    }

    let activeProfile = currentCustomProfiles.find(p => p.is_active);
    if (!activeProfile && currentCustomProfiles.length > 0) {
        activeProfile = currentCustomProfiles[0];
    }

    const hasMultiSelection = multiSelectedProfileIds.size > 0;

    let toolbarHtml = '';
    if (hasMultiSelection) {
        toolbarHtml = `
            <div class="sticky top-0 z-20 px-3 py-1.5 bg-[#0f172a] border-b border-[#334155] flex items-center justify-between text-xs">
                <div class="flex items-center gap-2">
                    <span class="text-blue-400 font-semibold text-[11px]">${multiSelectedProfileIds.size} selected</span>
                    <button onclick="event.stopPropagation(); clearProfileMultiSelection();" class="text-slate-400 hover:text-white underline text-[10px] cursor-pointer">Clear</button>
                </div>
                <button onclick="event.stopPropagation(); requestDeleteMultiSelectedProfiles();"
                        title="Delete selected profiles"
                        class="px-2.5 py-1 rounded-md bg-blue-600 hover:bg-blue-500 text-white font-semibold text-[11px] flex items-center gap-1.5 cursor-pointer shadow-sm uppercase tracking-wider transition-all">
                    <i class="fa-solid fa-trash-can text-[10px]"></i>
                    <span>Delete (${multiSelectedProfileIds.size})</span>
                </button>
            </div>
        `;
    }

    const itemsHtml = currentCustomProfiles.map((p, index) => {
        const isMultiSelected = multiSelectedProfileIds.has(p.id);
        const isCurrentActive = Boolean(p.is_active || (activeProfile && p.id === activeProfile.id));
        const dateFormatted = formatProfileDate(p.created_at);
        const activeBadge = isCurrentActive 
            ? `<span class="px-1.5 py-0.5 rounded text-[9px] font-bold bg-[#10b981] text-white uppercase tracking-wider whitespace-nowrap leading-none select-none">ACTIVE</span>`
            : '';

        let modeBadge = '';
        if (p.id === 'profile_vr_airliner_glass_cockpit' || (p.name && p.name.includes('Airliner'))) {
            modeBadge = `<span class="px-1.5 py-0.5 rounded text-[9px] font-bold bg-[#0284c7] text-white leading-none tracking-wider whitespace-nowrap select-none">TAA - LINER</span>`;
        } else if (p.id === 'profile_vr_bush_fast_vfr' || (p.name && p.name.includes('Bush'))) {
            modeBadge = `<span class="px-1.5 py-0.5 rounded text-[9px] font-bold bg-[#d97706] text-white leading-none tracking-wider whitespace-nowrap select-none">OFXR - BUSH</span>`;
        } else if (p.id === 'profile_vr_headset_standard' || (p.name && p.name.includes('VR Headset'))) {
            modeBadge = `<span class="px-1.5 py-0.5 rounded text-[9px] font-bold bg-[#7c3aed] text-white leading-none tracking-wider whitespace-nowrap select-none">VR</span>`;
        } else if (p.id === 'profile_2d_display_standard' || (p.name && p.name.includes('2D Display'))) {
            modeBadge = `<span class="px-1.5 py-0.5 rounded text-[9px] font-bold bg-[#475569] text-white leading-none tracking-wider whitespace-nowrap select-none">2D</span>`;
        } else if (p.tag) {
            const cleanTag = String(p.tag).replace(/\s*•\s*/g, ' - ').trim();
            modeBadge = `<span class="px-1.5 py-0.5 rounded text-[9px] font-semibold bg-[#475569] text-white leading-none whitespace-nowrap select-none">${escapeHtml(cleanTag)}</span>`;
        }

        let rowBgClass = 'bg-[#181E2B] hover:bg-[#20293A]';
        if (isMultiSelected) {
            rowBgClass = 'bg-[#1E293B] border-l-2 border-[#38BDF8] hover:bg-[#27354D]';
        } else if (isCurrentActive) {
            rowBgClass = 'bg-[#1E2638] border-l-2 border-[#10B981] hover:bg-[#253046]';
        } else if (p.id === selectedProfileId) {
            rowBgClass = 'bg-[#1C2333] border-l-2 border-[#64748B] hover:bg-[#232D42]';
        }

        const checkboxIcon = hasMultiSelection
            ? (isMultiSelected
                ? `<i class="fa-solid fa-square-check text-blue-400 text-sm shrink-0 mr-2"></i>`
                : `<i class="fa-regular fa-square text-slate-500 text-sm shrink-0 mr-2"></i>`)
            : '';

        return `
            <div onclick="handleProfileRowClick(event, '${p.id}', ${index})"
                 class="px-3.5 py-2 flex items-center justify-between cursor-pointer transition-colors group select-none ${rowBgClass}">
                <div class="flex items-center min-w-0 pr-2">
                    ${checkboxIcon}
                    <div class="flex flex-col min-w-0">
                        <div class="flex items-center gap-1.5">
                            <span class="typo-input-val font-semibold text-xs text-slate-100 truncate">${escapeHtml(p.name)}</span>
                            ${modeBadge}
                        </div>
                        <span class="typo-metadata tabular-nums text-[10px] text-slate-400">${dateFormatted}</span>
                    </div>
                </div>
                <div class="shrink-0 flex items-center gap-1.5">
                    ${activeBadge}
                    <button onclick="event.stopPropagation(); requestRenameCustomProfile('${p.id}')"
                            title="Rename '${escapeHtml(p.name)}'"
                            class="w-6 h-6 flex items-center justify-center rounded-md hover:bg-[#253046] text-slate-400 hover:text-[#38BDF8] transition-colors cursor-pointer border-0 bg-transparent">
                        <i class="fa-solid fa-pen text-[10px] pointer-events-none"></i>
                    </button>
                    <button onclick="event.stopPropagation(); requestDeleteCustomProfileById('${p.id}')"
                            title="Delete '${escapeHtml(p.name)}' (${dateFormatted})"
                            class="w-6 h-6 flex items-center justify-center rounded-md hover:bg-[#3B1824] text-slate-400 hover:text-rose-400 transition-colors cursor-pointer border-0 bg-transparent">
                        <i class="fa-solid fa-trash-can text-xs pointer-events-none"></i>
                    </button>
                </div>
            </div>
        `;
    }).join('');

    listEl.innerHTML = toolbarHtml + itemsHtml;
}

function handleProfileRowClick(event, profileId, index) {
    if (event.shiftKey) {
        event.preventDefault();
        event.stopPropagation();
        const start = lastClickedProfileIndex >= 0 ? lastClickedProfileIndex : index;
        const end = index;
        const min = Math.min(start, end);
        const max = Math.max(start, end);
        for (let i = min; i <= max; i++) {
            if (currentCustomProfiles[i]) {
                multiSelectedProfileIds.add(currentCustomProfiles[i].id);
            }
        }
        lastClickedProfileIndex = index;
        renderCustomProfilesDropdownList();
        return;
    }

    if (event.altKey || event.ctrlKey || event.metaKey) {
        event.preventDefault();
        event.stopPropagation();
        if (multiSelectedProfileIds.has(profileId)) {
            multiSelectedProfileIds.delete(profileId);
        } else {
            multiSelectedProfileIds.add(profileId);
        }
        lastClickedProfileIndex = index;
        renderCustomProfilesDropdownList();
        return;
    }

    // Normal click: clear any multi-selection and select single profile item
    if (multiSelectedProfileIds.size > 0) {
        multiSelectedProfileIds.clear();
        renderCustomProfilesDropdownList();
    }
    lastClickedProfileIndex = index;
    selectCustomProfileItem(profileId);
}

function toggleProfileDropdown(event) {
    if (event) {
        event.stopPropagation();
        event.preventDefault();
    }
    const listEl = document.getElementById('opt-profile-dropdown-list');
    const combobox = document.getElementById('opt-profile-universal-combobox');
    if (!listEl || !combobox) return;
    const isHidden = listEl.classList.contains('hidden');
    closeAllProfileDropdowns();
    if (isHidden) {
        // Move dropdown to body if not already there, ensuring it breaks out of the floating window overflow
        if (listEl.parentElement !== document.body) {
            document.body.appendChild(listEl);
        }
        const rect = combobox.getBoundingClientRect();
        const spaceBelow = window.innerHeight - rect.bottom;
        const spaceAbove = rect.top;

        listEl.style.position = 'fixed';
        listEl.style.left = `${rect.left}px`;
        listEl.style.width = `${rect.width}px`;
        listEl.style.zIndex = '99999';
        listEl.style.backgroundColor = '#181E2B';
        listEl.style.backdropFilter = 'none';
        listEl.style.webkitBackdropFilter = 'none';
        listEl.style.opacity = '1';

        // Check if opening downwards would be cramped (less than 220px) and there's more space above
        if (spaceBelow < 220 && spaceAbove > spaceBelow) {
            listEl.style.top = 'auto';
            listEl.style.bottom = `${window.innerHeight - rect.top + 6}px`;
            listEl.style.maxHeight = `${Math.max(100, Math.min(260, spaceAbove - 20))}px`;
        } else {
            listEl.style.bottom = 'auto';
            listEl.style.top = `${rect.bottom + 6}px`;
            listEl.style.maxHeight = `${Math.max(100, Math.min(260, spaceBelow - 20))}px`;
        }
        renderCustomProfilesDropdownList();
        listEl.classList.remove('hidden');
    }
}

function closeAllProfileDropdowns() {
    const listEl = document.getElementById('opt-profile-dropdown-list');
    if (listEl) {
        listEl.classList.add('hidden');
        const combobox = document.getElementById('opt-profile-universal-combobox');
        if (combobox && listEl.parentElement !== combobox) {
            combobox.appendChild(listEl);
        }
    }
    multiSelectedProfileIds.clear();
    lastClickedProfileIndex = -1;
}

async function selectCustomProfileItem(profileId) {
    const profile = currentCustomProfiles.find(p => p.id === profileId);
    if (!profile) return;

    selectedProfileId = profile.id;
    sortCustomProfilesList();
    const input = document.getElementById('opt-profile-universal-input');
    if (input) {
        input.value = profile.name;
    }
    const dropdown = document.getElementById('opt-profiles-dropdown');
    if (dropdown) {
        dropdown.value = profile.id;
    }
    closeAllProfileDropdowns();

    // Automatically switch to the matching category (2D or VR)
    const targetMode = detectProfileCategoryMode(profile);
    if (typeof switchMsfsGraphicsMode === 'function') {
        switchMsfsGraphicsMode(targetMode, false);
    }

    // 1-Click Profile Selection: Immediately activate profile into MSFS
    if (window.pywebview && window.pywebview.api && window.pywebview.api.activate_custom_profile) {
        try {
            const resStr = await window.pywebview.api.activate_custom_profile(profile.id);
            const res = JSON.parse(resStr);
            if (res.status === 'success') {
                if (typeof showToast === 'function') {
                    showToast(`Profile "${profile.name}" activated into MSFS!`, 'success');
                }
            } else {
                console.warn("Profile activation returned warning:", res.message);
            }
        } catch (e) {
            console.error("Error activating profile on 1-click selection:", e);
        }
    }

    // Refresh custom profiles list to display the ACTIVE tag on selected profile
    await fetchAndRenderCustomProfiles(false);
    await loadRigDiagnostics(profile.id);
    if (typeof updateProfileActivateButtonState === 'function') {
        await updateProfileActivateButtonState();
    }
}

function handleProfileInputFocus() {
    const input = document.getElementById('opt-profile-universal-input');
    if (!input) return;
    input.select();
    const tag = document.getElementById('opt-profile-active-tag');
    if (tag) tag.classList.add('hidden');
    closeAllProfileDropdowns();
}

function handleProfileInputBlur() {
    const input = document.getElementById('opt-profile-universal-input');
    if (!input) return;
    // If left empty and a profile was previously selected, restore its display name
    if (!input.value.trim() && selectedProfileId) {
        const prof = currentCustomProfiles.find(p => p.id === selectedProfileId);
        if (prof) {
            input.value = prof.name;
        }
    }
    if (typeof updateProfileActivateButtonState === 'function') {
        updateProfileActivateButtonState();
    }
}

function handleProfileInputChange() {
    if (typeof updateProfileActivateButtonState === 'function') {
        updateProfileActivateButtonState();
    }
}

let pendingConflictProfileName = null;

function openFrameLimiterConflictModal(fps2D, fpsVR, profileName) {
    pendingConflictProfileName = profileName;
    const modal = document.getElementById('opt-framelimiter-conflict-modal');
    if (!modal) return;

    const textEl = document.getElementById('opt-conflict-modal-text');
    if (textEl) {
        textEl.innerHTML = `Scenery X has detected that both your 2D Display (${fps2D} FPS) and VR Headset (${fpsVR} FPS) Max Frame Rates are active. MSFS 2024 uses a single global <code>FrameLimiter</code> in its rendering pipeline and cannot enforce two different caps simultaneously. We recommend maintaining dedicated profiles (e.g. "2D Desktop" and "VR Headset") rather than a shared configuration.`;
    }

    const lbl2D = document.getElementById('opt-conflict-lbl-2d');
    if (lbl2D) lbl2D.textContent = `Enforce 2D Target (${fps2D} FPS)`;

    const lblVR = document.getElementById('opt-conflict-lbl-vr');
    if (lblVR) lblVR.textContent = `Enforce VR Target (${fpsVR} FPS)`;

    modal.classList.remove('hidden');
    modal.classList.add('flex');
    if (window.windowManager) {
        windowManager.bringToFront(modal);
        windowManager.centerModal(modal);
    }
}

function closeFrameLimiterConflictModal() {
    const modal = document.getElementById('opt-framelimiter-conflict-modal');
    if (modal) {
        modal.classList.add('hidden');
        modal.classList.remove('flex');
    }
    pendingConflictProfileName = null;
}

async function resolveFrameLimiterConflict(choice) {
    const profName = pendingConflictProfileName;
    closeFrameLimiterConflictModal();
    if (!profName) return;

    if (choice === '2D') {
        // Enforce 2D target: Turn off VR limiter
        if (window.pywebview && window.pywebview.api && window.pywebview.api.update_msfs_setting) {
            await window.pywebview.api.update_msfs_setting('VR', 'max_frame_rate', 'OFF');
        }
        if (msfsSettingsMatrixData && msfsSettingsMatrixData.matrix_vr) {
            const itVR = msfsSettingsMatrixData.matrix_vr.find(x => x.key === 'max_frame_rate');
            if (itVR) {
                if (!itVR._lastActiveFps) itVR._lastActiveFps = parseInt(String(itVR.raw_value || itVR.value).replace(/[^0-9]/g, '')) || 45;
                itVR.value = 'OFF';
                itVR.raw_value = '0';
                itVR.is_active = false;
            }
        }
    } else if (choice === 'VR') {
        // Enforce VR target: Turn off 2D limiter
        if (window.pywebview && window.pywebview.api && window.pywebview.api.update_msfs_setting) {
            await window.pywebview.api.update_msfs_setting('2D', 'max_frame_rate', 'OFF');
        }
        if (msfsSettingsMatrixData && msfsSettingsMatrixData.matrix_2d) {
            const it2D = msfsSettingsMatrixData.matrix_2d.find(x => x.key === 'max_frame_rate');
            if (it2D) {
                if (!it2D._lastActiveFps) it2D._lastActiveFps = parseInt(String(it2D.raw_value || it2D.value).replace(/[^0-9]/g, '')) || 82;
                it2D.value = 'OFF';
                it2D.raw_value = '0';
                it2D.is_active = false;
            }
        }
    } else if (choice === 'OFF') {
        // Run Uncapped: Turn off both
        if (window.pywebview && window.pywebview.api && window.pywebview.api.update_msfs_setting) {
            await window.pywebview.api.update_msfs_setting('2D', 'max_frame_rate', 'OFF');
            await window.pywebview.api.update_msfs_setting('VR', 'max_frame_rate', 'OFF');
        }
        if (msfsSettingsMatrixData) {
            const it2D = (msfsSettingsMatrixData.matrix_2d || []).find(x => x.key === 'max_frame_rate');
            if (it2D) {
                if (!it2D._lastActiveFps) it2D._lastActiveFps = parseInt(String(it2D.raw_value || it2D.value).replace(/[^0-9]/g, '')) || 82;
                it2D.value = 'OFF';
                it2D.raw_value = '0';
                it2D.is_active = false;
            }
            const itVR = (msfsSettingsMatrixData.matrix_vr || []).find(x => x.key === 'max_frame_rate');
            if (itVR) {
                if (!itVR._lastActiveFps) itVR._lastActiveFps = parseInt(String(itVR.raw_value || itVR.value).replace(/[^0-9]/g, '')) || 45;
                itVR.value = 'OFF';
                itVR.raw_value = '0';
                itVR.is_active = false;
            }
        }
    }

    await executeSaveCurrentCustomProfile(profName);
    await loadRigDiagnostics();
}

/* ==============================================================================
   BACKGROUND TOOLS DETECTION & OFXR INTEGRATION
   ============================================================================== */

let currentBgToolsData = null;
let modalAutoFpsChoice = 'kill';
let modalOfxrMode = '3X';
let modalOfxrTargetFps = 36;

let pendingBackgroundToolsCheck = false;

async function checkBackgroundToolsOnStartup() {
    if (window.IS_LITE) return;
    if (!window.pywebview || !window.pywebview.api || !window.pywebview.api.check_background_tools) return;

    // If onboarding tour has not been seen yet, postpone background tools modal!
    let hasSeenOnboarding = false;
    if (window.onboardingTour && typeof window.onboardingTour.isOnboardingCompleted === 'function') {
        hasSeenOnboarding = await window.onboardingTour.isOnboardingCompleted();
    } else if (window.pywebview && window.pywebview.api && window.pywebview.api.is_onboarding_completed) {
        try {
            const res = JSON.parse(await window.pywebview.api.is_onboarding_completed());
            hasSeenOnboarding = Boolean(res && res.completed);
        } catch (e) {}
    } else {
        hasSeenOnboarding = (localStorage.getItem('sceneryx_has_seen_onboarding') === 'true');
    }

    const conflictModal = document.getElementById('conflict-resolution-modal');
    const isConflictOpen = conflictModal && !conflictModal.classList.contains('hidden');
    const rescanModal = document.getElementById('rescan-modal');
    const isRescanOpen = rescanModal && !rescanModal.classList.contains('hidden');
    if (!hasSeenOnboarding || pendingConflictModal || isConflictOpen || isRescanOpen) {
        pendingBackgroundToolsCheck = true;
        return;
    }

    try {
        const resStr = await window.pywebview.api.check_background_tools();
        if (!resStr) return;
        const data = JSON.parse(resStr);
        if (!data) return;

        // If user selected "Remember my choice", skip modal
        if (data.remember_choice) {
            if (typeof checkFirstSystemTuningScanOnStartup === 'function') {
                checkFirstSystemTuningScanOnStartup();
            }
            return;
        }

        // If neither AutoFPS nor OFXR is running, nothing to prompt
        if (!data.autofps_running && !data.ofxr_running) {
            if (typeof checkFirstSystemTuningScanOnStartup === 'function') {
                checkFirstSystemTuningScanOnStartup();
            }
            return;
        }

        openBackgroundToolsModal(data);
    } catch (e) {
        console.warn("Background tools startup check error:", e);
    }
}

function triggerPendingBackgroundToolsCheck() {
    if (pendingBackgroundToolsCheck) {
        pendingBackgroundToolsCheck = false;
        setTimeout(() => {
            checkBackgroundToolsOnStartup();
        }, 600);
    } else {
        if (typeof checkFirstSystemTuningScanOnStartup === 'function') {
            checkFirstSystemTuningScanOnStartup();
        }
    }
}
window.triggerPendingBackgroundToolsCheck = triggerPendingBackgroundToolsCheck;

function openBackgroundToolsModal(data) {
    currentBgToolsData = data;
    const modal = document.getElementById('background-tools-modal');
    if (!modal) return;

    // 1. AutoFPS Section
    const afSec = document.getElementById('bg-tools-autofps-section');
    if (afSec) {
        if (data.autofps_running) {
            afSec.classList.remove('hidden');
            const pidEl = document.getElementById('bg-tools-autofps-pid');
            if (pidEl) pidEl.textContent = `PID ${data.autofps_pid || '--'}`;
            selectModalAutoFpsAction('kill');
        } else {
            afSec.classList.add('hidden');
        }
    }

    // 2. OFXR Section
    const ofxrSec = document.getElementById('bg-tools-ofxr-section');
    if (ofxrSec) {
        if (data.ofxr_running) {
            ofxrSec.classList.remove('hidden');
            const ofxrPidEl = document.getElementById('bg-tools-ofxr-pid');
            if (ofxrPidEl) ofxrPidEl.textContent = `PID ${data.ofxr_pid || '--'}`;

            // Dynamic refresh rate calculation based on headset frequency
            const fps2x = data.fps_2x || 45;
            const fps3x = data.fps_3x || (data.vr_hz === 72 ? 24 : 30);
            const vrHz = data.vr_hz || 72;
            const is3xDisabled = (fps3x < 30 || vrHz <= 75);

            const btn2x = document.getElementById('bg-modal-ofxr-mode-2x');
            if (btn2x) btn2x.textContent = `2X (${fps2x} FPS)`;

            const btn3x = document.getElementById('bg-modal-ofxr-mode-3x');
            if (btn3x) {
                btn3x.textContent = `3X (${fps3x} FPS)`;
                if (is3xDisabled) {
                    btn3x.disabled = true;
                    btn3x.title = `3X mode unavailable at ${vrHz} Hz (base frame rate < 30 FPS unsuitable for VR)`;
                } else {
                    btn3x.disabled = false;
                    btn3x.removeAttribute('title');
                }
            }

            modalOfxrMode = data.ofxr_mode || (is3xDisabled ? '2X' : '3X');
            if (is3xDisabled && modalOfxrMode === '3X') {
                modalOfxrMode = '2X';
            }
            if (modalOfxrMode === '3X') {
                modalOfxrTargetFps = fps3x;
            } else if (modalOfxrMode === '2X') {
                modalOfxrTargetFps = fps2x;
            } else {
                modalOfxrTargetFps = data.ofxr_target_fps || (is3xDisabled ? fps2x : fps3x);
            }

            setModalOfxrMode(modalOfxrMode);
            const syncChk = document.getElementById('bg-modal-ofxr-sync');
            if (syncChk) syncChk.checked = (data.ofxr_sync_smart_lod !== false);
        } else {
            ofxrSec.classList.add('hidden');
        }
    }

    // Reset Remember checkbox
    const remChk = document.getElementById('bg-tools-remember');
    if (remChk) remChk.checked = false;

    modal.classList.remove('hidden');
    modal.classList.add('flex');
    if (window.windowManager) {
        windowManager.bringToFront(modal);
        windowManager.centerModal(modal);
    }
}

function closeBackgroundToolsModal() {
    const modal = document.getElementById('background-tools-modal');
    if (modal) {
        modal.classList.add('hidden');
        modal.classList.remove('flex');
    }
    if (pendingSystemTuningPopup || localStorage.getItem('sceneryx_has_seen_system_tuning') !== 'true') {
        if (typeof checkFirstSystemTuningScanOnStartup === 'function') {
            checkFirstSystemTuningScanOnStartup(true);
        }
    }
}

function selectModalAutoFpsAction(action) {
    modalAutoFpsChoice = action;
    const btnKill = document.getElementById('bg-tools-btn-kill-autofps');
    const btnKeep = document.getElementById('bg-tools-btn-keep-autofps');
    const syncChk = document.getElementById('bg-modal-ofxr-sync');
    const syncLabel = document.getElementById('bg-modal-ofxr-sync-label');
    const syncText = document.getElementById('bg-modal-ofxr-sync-text');

    if (action === 'kill') {
        if (btnKill) {
            btnKill.className = 'h-10 px-3 rounded-lg bg-emerald-600 text-white font-bold text-xs uppercase tracking-wider transition-colors cursor-pointer border-0 flex items-center justify-center text-center';
        }
        if (btnKeep) {
            btnKeep.className = 'h-10 px-3 rounded-lg bg-slate-800 hover:bg-slate-750 text-slate-300 font-bold text-xs uppercase tracking-wider transition-colors cursor-pointer border-0 flex items-center justify-center text-center';
        }
        if (syncChk) {
            syncChk.disabled = false;
            syncChk.checked = true;
        }
        if (syncLabel) {
            syncLabel.classList.remove('opacity-30', 'cursor-not-allowed', 'pointer-events-none');
        }
        if (syncText) {
            syncText.innerHTML = `Sync Smart LOD VR Target (<span id="bg-modal-ofxr-fps-label">${modalOfxrTargetFps}</span> FPS)`;
        }
    } else {
        if (btnKill) {
            btnKill.className = 'h-10 px-3 rounded-lg bg-slate-800 hover:bg-slate-750 text-slate-300 font-bold text-xs uppercase tracking-wider transition-colors cursor-pointer border-0 flex items-center justify-center text-center';
        }
        if (btnKeep) {
            btnKeep.className = 'h-10 px-3 rounded-lg bg-amber-600 text-white font-bold text-xs uppercase tracking-wider transition-colors cursor-pointer border-0 flex items-center justify-center text-center';
        }
        if (syncChk) {
            syncChk.checked = false;
            syncChk.disabled = true;
        }
        if (syncLabel) {
            syncLabel.classList.add('opacity-30', 'cursor-not-allowed', 'pointer-events-none');
        }
        if (syncText) {
            syncText.innerHTML = `Sync Smart LOD VR Target <span class="text-amber-400 font-semibold">(Locked: AutoFPS active)</span>`;
        }
    }
}

function setModalOfxrMode(mode) {
    const vrHz = (currentBgToolsData && currentBgToolsData.vr_hz) || 72;
    const fps2x = (currentBgToolsData && currentBgToolsData.fps_2x) || Math.max(20, Math.floor(vrHz / 2));
    const fps3x = (currentBgToolsData && currentBgToolsData.fps_3x) || Math.max(20, Math.round(vrHz / 3));
    const is3xDisabled = (fps3x < 30 || vrHz <= 75);

    if (is3xDisabled && mode === '3X') {
        mode = '2X';
    }
    modalOfxrMode = mode;

    ['off', '2x', '3x'].forEach(m => {
        const btn = document.getElementById(`bg-modal-ofxr-mode-${m}`);
        if (btn) {
            if (m === '3x' && is3xDisabled) {
                btn.className = 'px-3 py-2 rounded-lg text-center text-xs font-semibold uppercase text-slate-500 bg-slate-900 opacity-30 cursor-not-allowed pointer-events-none select-none border-0';
                btn.disabled = true;
                btn.title = `3X mode disabled at ${vrHz} Hz (${fps3x} FPS base frame rate too low for VR)`;
            } else if (m.toUpperCase() === mode.toUpperCase()) {
                btn.className = 'px-3 py-2 rounded-lg text-center text-xs font-bold uppercase text-slate-950 bg-cyan-500 transition-colors cursor-pointer border-0';
                btn.disabled = false;
            } else {
                btn.className = 'px-3 py-2 rounded-lg text-center text-xs font-semibold uppercase text-slate-300 bg-slate-800 hover:bg-slate-750 transition-colors cursor-pointer border-0';
                btn.disabled = false;
            }
        }
    });

    if (mode === '3X') {
        modalOfxrTargetFps = fps3x;
    } else if (mode === '2X') {
        modalOfxrTargetFps = fps2x;
    }
    const lbl = document.getElementById('bg-modal-ofxr-fps-label');
    if (lbl) lbl.textContent = modalOfxrTargetFps;

    // Contextual notice: Flat solid bg-slate-950, zero border/liseres, no icons, concise, yellow typo for warning
    const warnEl = document.getElementById('bg-modal-ofxr-warning');
    if (warnEl) {
        if (is3xDisabled) {
            warnEl.className = 'p-2.5 rounded-lg bg-slate-950 text-xs text-amber-400 select-none';
            warnEl.textContent = `2X mode (${fps2x} FPS) optimal for ${vrHz} Hz. 3X mode disabled (base frame rate ${fps3x} FPS < 30 FPS unsuitable for VR).`;
        } else if (mode === '2X') {
            warnEl.className = 'p-2.5 rounded-lg bg-slate-950 text-xs text-emerald-400 select-none';
            warnEl.textContent = `2X mode active (${fps2x} FPS base -> ${vrHz} FPS smooth).`;
        } else if (mode === '3X') {
            warnEl.className = 'p-2.5 rounded-lg bg-slate-950 text-xs text-emerald-400 select-none';
            warnEl.textContent = `3X mode active (${fps3x} FPS base -> ${vrHz} FPS smooth).`;
        } else {
            warnEl.className = 'hidden';
            warnEl.textContent = '';
        }
    }
}

async function confirmBackgroundToolsModal() {
    closeBackgroundToolsModal();
    if (!window.pywebview || !window.pywebview.api || !window.pywebview.api.resolve_background_tools) return;

    const remChk = document.getElementById('bg-tools-remember');
    const syncChk = document.getElementById('bg-modal-ofxr-sync');
    const remember = remChk ? remChk.checked : false;
    const syncSmartLod = syncChk ? syncChk.checked : true;

    const payload = {
        autofps_action: (currentBgToolsData && currentBgToolsData.autofps_running) ? modalAutoFpsChoice : 'ignore',
        remember: remember,
        ofxr_mode: modalOfxrMode,
        ofxr_target_fps: modalOfxrTargetFps,
        ofxr_sync_smart_lod: syncSmartLod
    };

    try {
        const resStr = await window.pywebview.api.resolve_background_tools(JSON.stringify(payload));
        const res = JSON.parse(resStr);
        if (res && res.success) {
            if (payload.autofps_action === 'kill') {
                showToastNotification("AutoFPS closed. SceneryX Smart LOD active.", "success");
                if (window.smartLodAxisState) {
                    window.smartLodAxisState.external_autofps = false;
                }
                if (typeof currentSettings !== 'undefined') {
                    currentSettings.external_autofps = false;
                    currentSettings.dynamic_lod_engine = 'smart_lod';
                }
                if (currentBgToolsData) {
                    currentBgToolsData.autofps_running = false;
                }
                if (typeof refreshSmartLodStatus === 'function') {
                    refreshSmartLodStatus();
                }
            } else if (payload.autofps_action === 'keep') {
                showToastNotification("AutoFPS kept: SceneryX Smart LOD locked and deactivated.", "info");
                if (window.smartLodAxisState) {
                    window.smartLodAxisState.external_autofps = true;
                }
                if (typeof currentSettings !== 'undefined') {
                    currentSettings.external_autofps = true;
                    currentSettings.dynamic_lod_engine = 'external_autofps';
                }
                window.smartLodActive = false;
                if (typeof updateSmartLodUIFromStatus === 'function') {
                    updateSmartLodUIFromStatus({
                        external_autofps: true,
                        enabled: false,
                        is_running: false
                    });
                }
                if (typeof closeFloatingWindow === 'function') {
                    closeFloatingWindow('smart_lod');
                }
            }
            if (currentBgToolsData && currentBgToolsData.ofxr_running) {
                showToastNotification(`OFXR configured: ${modalOfxrMode} @ ${modalOfxrTargetFps} FPS base.`, "info");
            }
            if (typeof updateFlightOptimizerRadialSectors === 'function') {
                updateFlightOptimizerRadialSectors();
            }
            if (typeof renderMsfsSettingsMatrix === 'function') {
                renderMsfsSettingsMatrix();
            }
            if (typeof loadRigDiagnostics === 'function' && document.getElementById('flight-optimizer-modal') && !document.getElementById('flight-optimizer-modal').classList.contains('hidden')) {
                loadRigDiagnostics();
            }
        }
    } catch (e) {
        console.error("Error resolving background tools:", e);
    }
}

/* ==============================================================================
   OFXR GRAPHICS SETTINGS CARD HANDLERS
   ============================================================================== */

async function setOfxrModeCard(mode) {
    if (!msfsSettingsMatrixData || !msfsSettingsMatrixData.matrix_vr) return;
    const it = msfsSettingsMatrixData.matrix_vr.find(x => x.key === 'ofxr_frame_gen');
    const vrHz = (msfsSettingsMatrixData.target_pacing_vr && msfsSettingsMatrixData.target_pacing_vr.vr_hz) || 72;
    const fps2x = Math.max(20, Math.floor(vrHz / 2));
    const fps3x = Math.max(20, Math.round(vrHz / 3));
    const is3xDisabled = (fps3x < 30 || vrHz <= 75);

    if (mode === '3X' && is3xDisabled) {
        showToastNotification(`3X Mode disabled at ${vrHz} Hz (base cadence < 30 FPS incompatible with VR).`, 'warning');
        return;
    }

    if (it) {
        it.value = mode;
        it.raw_value = mode;
        it.ofxr_mode = mode;
        if (mode === '2X' && vrHz <= 75) {
            it.tag_badge = 'SWEET SPOT';
            it.rating_color = 'emerald';
            it.rating_label = '2X SWEET SPOT';
        } else {
            it.tag_badge = (mode === 'OFF') ? 'OFF' : (mode + ' ACTIVE');
            it.rating_color = (mode === 'OFF') ? 'slate' : 'emerald';
            it.rating_label = (mode === 'OFF') ? 'OFF' : (mode + ' ACTIVE');
        }
        if (mode === '3X') it.ofxr_target_fps = fps3x;
        if (mode === '2X') it.ofxr_target_fps = fps2x;
    }

    const fps = (it && it.ofxr_target_fps) || (mode === '2X' ? fps2x : (mode === '3X' ? fps3x : fps2x));
    const sync = (it && it.ofxr_sync_smart_lod !== false);

    // Sync Max Frame Rate (VR) card in UI immediately
    const mfrItem = msfsSettingsMatrixData.matrix_vr.find(x => x.key === 'max_frame_rate');
    if (mfrItem && mode !== 'OFF') {
        mfrItem.value = `${fps} FPS`;
        mfrItem.raw_value = String(fps);
        mfrItem.is_active = true;
        mfrItem.rating_color = 'emerald';
        mfrItem.rating_label = 'OPTIMUM';
    }

    renderMsfsSettingsMatrix();

    if (window.pywebview && window.pywebview.api && window.pywebview.api.save_ofxr_settings) {
        try {
            const resStr = await window.pywebview.api.save_ofxr_settings(mode, fps, sync);
            const res = JSON.parse(resStr);
            if (mode === 'OFF' && res && res.restored_fps && mfrItem) {
                const rFps = parseInt(res.restored_fps);
                if (rFps > 0) {
                    mfrItem.value = `${rFps} FPS`;
                    mfrItem.raw_value = String(rFps);
                    mfrItem.is_active = true;
                    mfrItem.rating_color = 'emerald';
                    mfrItem.rating_label = 'OPTIMUM';
                } else {
                    mfrItem.value = 'OFF';
                    mfrItem.raw_value = '0';
                    mfrItem.is_active = false;
                    mfrItem.rating_color = 'slate';
                    mfrItem.rating_label = 'OFF';
                }
                renderMsfsSettingsMatrix();
            }
        } catch (e) {
            console.error("Error saving OFXR settings:", e);
        }
    }
    if (mode === '2X') {
        showToastNotification(`OFXR configured in 2X mode (${fps2x} FPS base -> ${vrHz} FPS smooth).`, 'info');
    } else if (mode === '3X') {
        showToastNotification(`OFXR configured in 3X mode (${fps3x} FPS base -> ${vrHz} FPS smooth).`, 'info');
    } else {
        showToastNotification(`OFXR Frame Gen disabled (OFF).`, 'info');
    }
}

async function setOfxrTargetFpsCard(fps) {
    if (!msfsSettingsMatrixData || !msfsSettingsMatrixData.matrix_vr) return;
    const it = msfsSettingsMatrixData.matrix_vr.find(x => x.key === 'ofxr_frame_gen');
    const vrHz = (msfsSettingsMatrixData.target_pacing_vr && msfsSettingsMatrixData.target_pacing_vr.vr_hz) || 72;
    const fps2x = Math.max(20, Math.floor(vrHz / 2));
    const fps3x = Math.max(20, Math.round(vrHz / 3));
    const ofxrMode = (it && it.ofxr_mode) || 'OFF';

    if (fps < 30) {
        showToastNotification("Cadences below 30 FPS are disabled in VR.", 'warning');
        return;
    }
    if (ofxrMode === '2X' && fps !== fps2x) {
        showToastNotification(`At ${vrHz} Hz in 2X mode, required cadence is ${fps2x} FPS.`, 'warning');
        return;
    }
    if (ofxrMode === '3X' && fps !== fps3x) {
        showToastNotification(`At ${vrHz} Hz in 3X mode, required cadence is ${fps3x} FPS.`, 'warning');
        return;
    }

    if (it) {
        it.ofxr_target_fps = fps;
        if (it.ofxr_mode === '2X' && vrHz <= 75) {
            it.tag_badge = 'SWEET SPOT';
            it.rating_color = 'emerald';
            it.rating_label = '2X SWEET SPOT';
        }
    }

    // Also update Max Frame Rate (VR) in UI
    const mfrItem = msfsSettingsMatrixData.matrix_vr.find(x => x.key === 'max_frame_rate');
    if (mfrItem && it && it.ofxr_mode !== 'OFF') {
        mfrItem.value = `${fps} FPS`;
        mfrItem.raw_value = String(fps);
        mfrItem.is_active = true;
        mfrItem.rating_color = 'emerald';
        mfrItem.rating_label = 'OPTIMUM';
    }
    renderMsfsSettingsMatrix();

    if (window.pywebview && window.pywebview.api && window.pywebview.api.save_ofxr_settings) {
        const mode = (it && it.ofxr_mode) || 'OFF';
        const sync = (it && it.ofxr_sync_smart_lod !== false);
        await window.pywebview.api.save_ofxr_settings(mode, fps, sync);
    }
    showToastNotification(`OFXR Base Target set to ${fps} FPS (Max Frame Rate synchronized)`, 'info');
}

async function toggleOfxrSyncCard(enabled) {
    if (!msfsSettingsMatrixData || !msfsSettingsMatrixData.matrix_vr) return;
    const it = msfsSettingsMatrixData.matrix_vr.find(x => x.key === 'ofxr_frame_gen');
    if (it) {
        it.ofxr_sync_smart_lod = enabled;
    }
    renderMsfsSettingsMatrix();

    if (window.pywebview && window.pywebview.api && window.pywebview.api.save_ofxr_settings) {
        const mode = (it && it.ofxr_mode) || 'OFF';
        const fps = (it && it.ofxr_target_fps) || 36;
        await window.pywebview.api.save_ofxr_settings(mode, fps, enabled);
    }
    showToastNotification(enabled ? 'Smart LOD VR target synced with OFXR' : 'Smart LOD VR target decoupled from OFXR', 'info');
}

async function handleOfxrRunningStateChange(isRunning) {
    if (!msfsSettingsMatrixData || !msfsSettingsMatrixData.matrix_vr) return;
    const it = msfsSettingsMatrixData.matrix_vr.find(x => x.key === 'ofxr_frame_gen');
    if (!it) return;

    it.ofxr_running = isRunning;

    if (!isRunning) {
        // User closed OFXR: disable mode, update card badges, and restore max frame rate
        it.value = 'OFF';
        it.raw_value = 'OFF';
        it.ofxr_mode = 'OFF';
        it.tag_badge = 'OFF';
        it.rating_color = 'slate';
        it.rating_label = 'OFF';

        if (window.pywebview && window.pywebview.api && window.pywebview.api.save_ofxr_settings) {
            try {
                const resStr = await window.pywebview.api.save_ofxr_settings('OFF', it.ofxr_target_fps || 36, it.ofxr_sync_smart_lod !== false);
                const res = JSON.parse(resStr);
                if (res && res.restored_fps) {
                    const mfrItem = msfsSettingsMatrixData.matrix_vr.find(x => x.key === 'max_frame_rate');
                    if (mfrItem) {
                        const rFps = parseInt(res.restored_fps);
                        if (rFps > 0) {
                            mfrItem.value = `${rFps} FPS`;
                            mfrItem.raw_value = String(rFps);
                            mfrItem.is_active = true;
                            mfrItem.rating_color = 'emerald';
                            mfrItem.rating_label = 'OPTIMUM';
                        } else {
                            mfrItem.value = 'OFF';
                            mfrItem.raw_value = '0';
                            mfrItem.is_active = false;
                            mfrItem.rating_color = 'slate';
                            mfrItem.rating_label = 'OFF';
                        }
                    }
                }
            } catch (e) {
                console.error("Error reverting OFXR on exit:", e);
            }
        }
        renderMsfsSettingsMatrix();
        showToastNotification("OFXR stopped: Frame Generation disabled, Max Frame Rate restored.", "info");
    } else {
        // OFXR started
        renderMsfsSettingsMatrix();
        showToastNotification("OFXR detected: Frame Generation available.", "info");
    }
}

function requestRenameCustomProfile(profileId) {
    const profile = currentCustomProfiles.find(p => p.id === profileId);
    if (!profile) return;

    showCustomModal({
        title: 'RENAME PROFILE',
        message: `
            <div class="flex flex-col items-center gap-2">
                <span class="text-slate-300">Enter a new name for this profile:</span>
                <input id="custom-modal-rename-input" type="text" value="${escapeHtml(profile.name)}"
                       class="w-full px-3 py-2 rounded-xl bg-slate-900 border border-slate-700 text-slate-100 text-xs text-center focus:outline-none focus:border-blue-500 font-sans tracking-wide">
            </div>
        `,
        type: 'info',
        showCancel: true,
        confirmText: 'RENAME',
        cancelText: 'CANCEL',
        confirmClass: 'px-5 py-1.5 text-center rounded-xl bg-blue-600 hover:bg-blue-500 text-white typo-action-btn font-semibold text-xs uppercase transition-all border-0 cursor-pointer shadow-md',
        cancelClass: 'px-5 py-1.5 text-center rounded-xl bg-slate-800/90 hover:bg-slate-700 border border-slate-700/80 text-slate-300 hover:text-white typo-action-btn text-xs font-semibold uppercase transition-all cursor-pointer',
        onConfirm: async () => {
            const inputEl = document.getElementById('custom-modal-rename-input');
            const newName = inputEl ? inputEl.value.trim() : '';
            if (!newName) {
                if (typeof showToast === 'function') showToast("Profile name cannot be empty", "warning");
                return;
            }
            if (newName.toLowerCase() === profile.name.trim().toLowerCase()) {
                return;
            }
            await executeRenameCustomProfile(profileId, newName);
        }
    });

    setTimeout(() => {
        const inputEl = document.getElementById('custom-modal-rename-input');
        if (inputEl) {
            inputEl.focus();
            inputEl.select();
            inputEl.addEventListener('keydown', (e) => {
                if (e.key === 'Enter') {
                    confirmCustomModal();
                }
            });
        }
    }, 50);
}

async function executeRenameCustomProfile(profileId, newName) {
    if (!window.pywebview || !window.pywebview.api || !window.pywebview.api.rename_custom_profile) return;
    try {
        const resStr = await window.pywebview.api.rename_custom_profile(profileId, newName);
        const res = JSON.parse(resStr);
        if (res.status === 'success') {
            if (typeof showToast === 'function') showToast(`Profile renamed to "${newName}"!`, 'success');
            await fetchAndRenderCustomProfiles();
            const input = document.getElementById('opt-profile-universal-input');
            if (selectedProfileId === profileId && input) {
                input.value = newName;
            }
        } else {
            showCustomModal({
                title: 'CANNOT RENAME PROFILE',
                message: res.message || 'A profile with this name already exists. Please choose another name.',
                type: 'info',
                showCancel: false,
                confirmText: 'OK',
                confirmClass: 'px-5 py-1.5 text-center rounded-xl bg-blue-600 hover:bg-blue-500 text-white typo-action-btn font-semibold text-xs uppercase transition-all border-0 cursor-pointer shadow-md'
            });
        }
    } catch (e) {
        console.error("Error renaming profile:", e);
        if (typeof showToast === 'function') showToast(`Error renaming profile: ${e}`, 'error');
    }
}

async function saveCurrentCustomProfile() {
    const input = document.getElementById('opt-profile-universal-input');
    let name = input ? input.value.trim() : '';
    if (!name) {
        const now = new Date();
        name = `Profile_${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}-${String(now.getDate()).padStart(2,'0')}_${String(now.getHours()).padStart(2,'0')}h${String(now.getMinutes()).padStart(2,'0')}`;
    }

    // 1. Check if name matches an EXISTING saved profile
    const matchingProfile = currentCustomProfiles.find(p => (p.name || '').trim().toLowerCase() === name.toLowerCase());

    if (matchingProfile) {
        // If this is the currently selected profile, save directly without modal interruption!
        if (selectedProfileId && matchingProfile.id === selectedProfileId) {
            await executeSaveCurrentCustomProfile(matchingProfile.name, matchingProfile.id);
            return;
        }

        // If it matches another profile name, prompt user to confirm overwrite
        showCustomModal({
            title: 'REPLACE PROFILE',
            message: `A profile named "<b>${escapeHtml(matchingProfile.name)}</b>" already exists.<br><br>Do you want to overwrite it with current settings?`,
            type: 'warning',
            showCancel: true,
            confirmText: 'YES',
            cancelText: 'NO',
            confirmClass: 'px-5 py-1.5 text-center rounded-xl bg-blue-600 hover:bg-blue-500 text-white typo-action-btn font-semibold text-xs uppercase transition-all border-0 cursor-pointer shadow-md',
            cancelClass: 'px-5 py-1.5 text-center rounded-xl bg-slate-800/90 hover:bg-slate-700 border border-slate-700/80 text-slate-300 hover:text-white typo-action-btn text-xs font-semibold uppercase transition-all cursor-pointer',
            onConfirm: async () => {
                await executeSaveCurrentCustomProfile(matchingProfile.name, matchingProfile.id);
            }
        });
        return;
    }

    // 2. Name does NOT match any existing profile.
    // Check if the user previously had a profile selected, and modified its name in the input.
    const currSelected = currentCustomProfiles.find(p => p.id === selectedProfileId);
    if (currSelected && currSelected.name.trim().toLowerCase() !== name.toLowerCase()) {
        showCustomModal({
            title: 'PROFILE SAVE / RENAME',
            message: `Profile name changed from "<b>${escapeHtml(currSelected.name)}</b>" to "<b>${escapeHtml(name)}</b>".<br><br>Would you like to rename the existing profile or save current settings as a new profile?`,
            type: 'info',
            showCancel: true,
            confirmText: 'RENAME',
            secondaryText: 'SAVE AS NEW',
            cancelText: 'CANCEL',
            confirmClass: 'px-4 py-1.5 text-center rounded-xl bg-blue-600 hover:bg-blue-500 text-white typo-action-btn font-semibold text-xs uppercase transition-all border-0 cursor-pointer shadow-md',
            secondaryClass: 'px-4 py-1.5 text-center rounded-xl bg-emerald-600 hover:bg-emerald-500 text-white typo-action-btn font-semibold uppercase transition-all cursor-pointer text-xs shadow-md',
            cancelClass: 'px-4 py-1.5 text-center rounded-xl bg-slate-800/90 hover:bg-slate-700 border border-slate-700/80 text-slate-300 hover:text-white typo-action-btn text-xs font-semibold uppercase transition-all cursor-pointer',
            onConfirm: async () => {
                await executeRenameCustomProfile(currSelected.id, name);
            },
            onSecondary: async () => {
                await executeSaveCurrentCustomProfile(name, null);
            }
        });
        return;
    }

    // 3. Normal save as new profile
    await executeSaveCurrentCustomProfile(name, null);
}

async function executeSaveCurrentCustomProfile(name, overwriteId = null) {
    const input = document.getElementById('opt-profile-universal-input');
    if (!window.pywebview || !window.pywebview.api || !window.pywebview.api.save_custom_profile) return;
    try {
        const resStr = await window.pywebview.api.save_custom_profile(name, overwriteId);
        const res = JSON.parse(resStr);
        if (res.status === 'success') {
            const actionText = overwriteId ? 'updated' : 'saved';
            if (typeof showToast === 'function') showToast(`Profile "${name}" ${actionText}!`, 'success');
            await fetchAndRenderCustomProfiles();
            if (res.profile && res.profile.id) {
                selectedProfileId = res.profile.id;
                if (input) input.value = res.profile.name || name;
            }
            if (typeof updateProfileActivateButtonState === 'function') {
                await updateProfileActivateButtonState();
            }
        } else {
            showCustomModal({
                title: 'CANNOT SAVE PROFILE',
                message: res.message || 'Profile already exists. Please choose another name.',
                type: 'info',
                showCancel: false,
                confirmText: 'OK',
                confirmClass: 'px-5 py-1.5 text-center rounded-xl bg-blue-600 hover:bg-blue-500 text-white typo-action-btn font-semibold text-xs uppercase transition-all border-0 cursor-pointer shadow-md',
                onConfirm: () => {
                    if (input) {
                        input.focus();
                        input.select();
                    }
                }
            });
        }
    } catch (e) {
        console.error("Error saving profile:", e);
        if (typeof showToast === 'function') showToast(`Error saving profile: ${e}`, 'error');
    }
}

async function activateSelectedCustomProfile() {
    let profileId = selectedProfileId;
    if (!profileId) {
        const dropdown = document.getElementById('opt-profiles-dropdown');
        profileId = dropdown ? dropdown.value : '';
    }
    if (!profileId) {
        const input = document.getElementById('opt-profile-universal-input');
        const typedName = input ? input.value.trim().toLowerCase() : '';
        if (typedName && currentCustomProfiles.length > 0) {
            const found = currentCustomProfiles.find(p => (p.name || '').toLowerCase() === typedName);
            if (found) profileId = found.id;
        }
    }

    if (!profileId) {
        if (typeof showToast === 'function') showToast("Please select a profile to activate.", "warning");
        return;
    }

    const profile = currentCustomProfiles.find(p => p.id === profileId);
    if (profile) {
        const targetMode = detectProfileCategoryMode(profile);
        if (typeof switchMsfsGraphicsMode === 'function') {
            switchMsfsGraphicsMode(targetMode, false);
        }
    }

    if (!window.pywebview || !window.pywebview.api || !window.pywebview.api.activate_custom_profile) return;
    try {
        const resStr = await window.pywebview.api.activate_custom_profile(profileId);
        const res = JSON.parse(resStr);
        if (res.status === 'success') {
            if (typeof showToast === 'function') showToast(`Profile "${res.profile_name}" activated into MSFS!`, 'success');
            await fetchAndRenderCustomProfiles(false);
            await loadRigDiagnostics(profileId);
            if (typeof updateProfileActivateButtonState === 'function') {
                await updateProfileActivateButtonState();
            }
        } else {
            if (typeof showToast === 'function') showToast(`Activation failed: ${res.message}`, 'error');
        }
    } catch (e) {
        console.error("Error activating profile:", e);
        if (typeof showToast === 'function') showToast(`Error activating profile: ${e}`, 'error');
    }
}

function requestDeleteCustomProfileById(profileId) {
    const profile = currentCustomProfiles.find(p => p.id === profileId);
    if (!profile) return;
    const dateFormatted = formatProfileDate(profile.created_at);
    const label = `${profile.name}${dateFormatted ? ' (' + dateFormatted + ')' : ''}`;

    showCustomModal({
        title: 'DELETE PROFILE',
        message: `Do you want to delete "${label}"?`,
        type: 'warning',
        showCancel: true,
        confirmText: 'YES',
        cancelText: 'NO',
        confirmClass: 'px-5 py-1.5 text-center rounded-xl bg-blue-600 hover:bg-blue-500 text-white typo-action-btn font-semibold text-xs uppercase transition-all border-0 cursor-pointer shadow-md',
        cancelClass: 'px-5 py-1.5 text-center rounded-xl bg-slate-800/90 hover:bg-slate-700 border border-slate-700/80 text-slate-300 hover:text-white typo-action-btn text-xs font-semibold uppercase transition-all cursor-pointer',
        onConfirm: async () => {
            await deleteSelectedCustomProfile(profileId);
            multiSelectedProfileIds.delete(profileId);
        }
    });
}

function requestDeleteMultiSelectedProfiles() {
    const count = multiSelectedProfileIds.size;
    if (count === 0) return;
    const ids = Array.from(multiSelectedProfileIds);

    showCustomModal({
        title: 'DELETE PROFILES',
        message: `Do you want to delete the "${count}" files selected ?`,
        type: 'warning',
        showCancel: true,
        confirmText: 'YES',
        cancelText: 'NO',
        confirmClass: 'px-5 py-1.5 text-center rounded-xl bg-blue-600 hover:bg-blue-500 text-white typo-action-btn font-semibold text-xs uppercase transition-all border-0 cursor-pointer shadow-md',
        cancelClass: 'px-5 py-1.5 text-center rounded-xl bg-slate-800/90 hover:bg-slate-700 border border-slate-700/80 text-slate-300 hover:text-white typo-action-btn text-xs font-semibold uppercase transition-all cursor-pointer',
        onConfirm: async () => {
            await deleteSelectedCustomProfile(ids.join(','));
            multiSelectedProfileIds.clear();
        }
    });
}

function confirmDeleteCustomProfile() {
    if (multiSelectedProfileIds.size > 0) {
        requestDeleteMultiSelectedProfiles();
    } else if (selectedProfileId) {
        requestDeleteCustomProfileById(selectedProfileId);
    } else {
        if (typeof showToast === 'function') showToast("Please select a profile to delete.", "warning");
    }
}

async function deleteSelectedCustomProfile(profileIdsToDelete) {
    const profileIds = profileIdsToDelete || selectedProfileId;
    if (!profileIds) return;

    if (!window.pywebview || !window.pywebview.api || !window.pywebview.api.delete_custom_profile) return;
    try {
        const resStr = await window.pywebview.api.delete_custom_profile(profileIds);
        const res = JSON.parse(resStr);
        if (res.status === 'success') {
            if (typeof showToast === 'function') showToast(res.message || "Profile(s) deleted successfully", 'info');
            selectedProfileId = '';
            multiSelectedProfileIds.clear();
            closeAllProfileDropdowns();
            await fetchAndRenderCustomProfiles(true);
            await loadRigDiagnostics();
        } else {
            if (typeof showToast === 'function') showToast(`Delete failed: ${res.message}`, 'error');
        }
    } catch (e) {
        console.error("Error deleting profile:", e);
    }
}

// Global key listener to trigger delete confirmation when Delete key is pressed with items multi-selected
document.addEventListener('keydown', (e) => {
    if (e.key === 'Delete' || e.key === 'Del') {
        const listEl = document.getElementById('opt-profile-dropdown-list');
        const isDropdownOpen = listEl && !listEl.classList.contains('hidden');
        if (isDropdownOpen && multiSelectedProfileIds.size > 0) {
            e.preventDefault();
            requestDeleteMultiSelectedProfiles();
            return;
        }

        const benchListEl = document.getElementById('opt-benchmark-dropdown-list');
        const isBenchDropdownOpen = benchListEl && !benchListEl.classList.contains('hidden');
        if (isBenchDropdownOpen && typeof multiSelectedBenchmarkFiles !== 'undefined' && multiSelectedBenchmarkFiles.size > 0) {
            e.preventDefault();
            requestDeleteMultiSelectedBenchmarks();
            return;
        }
    }
});

