        'WIII': 'Jakarta', 'WADD': 'Bali', 'VIDP': 'New Delhi', 'VABB': 'Mumbai',
        'VOBL': 'Bengaluru', 'VOMM': 'Chennai', 'VOHS': 'Hyderabad', 'VECC': 'Kolkata',
